import React, { useMemo, useState } from 'react';
import { SeafoodResultItem, Rating } from '../types';
import DonutChartByVolume from './DonutChartByVolume';
import StackedBarChart, { BarChartDataItem } from './StackedBarChart';

interface ChartsViewProps {
  results: SeafoodResultItem[];
  columnMapping: Record<string, string>;
  onSegmentClick: (title: string, data: SeafoodResultItem[]) => void;
}

type GroupedData = Record<string, {
  totalValue: number;
  breakdown: { [key in Rating]?: number };
  sourceItems: SeafoodResultItem[];
}>;

type ChartType = 'species' | 'country' | 'supplier';
type MetricType = 'volume' | 'count';

const ChartsView: React.FC<ChartsViewProps> = ({ results, columnMapping, onSegmentClick }) => {
  const [activeChart, setActiveChart] = useState<ChartType>('species');

  // Default to 'volume' only if 'Volume' is mapped, otherwise 'count'
  const [metric, setMetric] = useState<MetricType>(
    columnMapping['Volume'] && columnMapping['Volume'] !== 'N/A' ? 'volume' : 'count'
  );

  const getMappedKey = (field: string) => Object.keys(columnMapping).find(key => key === field) ? columnMapping[field] : null;

  const volumeKey = getMappedKey('Volume');
  const speciesKey = getMappedKey('Common name');
  const countryKey = getMappedKey('Source country');
  const supplierKey = getMappedKey('Supplier');

  const { donutData, speciesData, countryData, supplierData } = useMemo(() => {
    // Helper to get value based on metric
    const getValue = (item: SeafoodResultItem) => {
        if (metric === 'count') return 1;
        if (!volumeKey || item[volumeKey] === undefined) return 0;
        const volume = parseFloat(String(item[volumeKey]));
        return isNaN(volume) ? 0 : volume;
    };

    // --- Process for Donut Chart ---
    const donutData: { [key in Rating]?: { value: number; items: SeafoodResultItem[] } } = {};
    results.forEach(item => {
        const rating = item.rating;
        if (!donutData[rating]) {
            donutData[rating] = { value: 0, items: [] };
        }
        donutData[rating]!.value += getValue(item);
        donutData[rating]!.items.push(item);
    });

    // --- Process for Bar Charts ---
    const processGroupData = (key: string | null): BarChartDataItem[] => {
      if (!key) return [];

      const grouped = results.reduce((acc, item) => {
        const groupLabel = item[key] ? String(item[key]) : 'Unknown';
        if (!acc[groupLabel]) {
          acc[groupLabel] = { totalValue: 0, breakdown: {}, sourceItems: [] };
        }

        const value = getValue(item);
        acc[groupLabel].totalValue += value;
        acc[groupLabel].breakdown[item.rating] = (acc[groupLabel].breakdown[item.rating] || 0) + value;
        acc[groupLabel].sourceItems.push(item);

        return acc;
      }, {} as GroupedData);

      return Object.entries(grouped)
        .map(([label, data]) => ({ label, ...(data as GroupedData[string]) }))
        .sort((a, b) => b.totalValue - a.totalValue)
        .slice(0, 20); // Limit to top 20 by volume/count
    };

    const speciesData = processGroupData(speciesKey);
    const countryData = processGroupData(countryKey);
    const supplierData = processGroupData(supplierKey);

    return { donutData, speciesData, countryData, supplierData };
  }, [results, volumeKey, speciesKey, countryKey, supplierKey, metric]);

  const renderActiveChart = () => {
    switch (activeChart) {
      case 'country':
        return <StackedBarChart title={`Ratings by Source Country (Top 20 by ${metric === 'volume' ? 'Volume' : 'Count'})`} data={countryData} metric={metric} chartType="country" columnMapping={columnMapping} onSegmentClick={onSegmentClick} />;
      case 'supplier':
        return <StackedBarChart title={`Ratings by Supplier (Top 20 by ${metric === 'volume' ? 'Volume' : 'Count'})`} data={supplierData} metric={metric} chartType="supplier" columnMapping={columnMapping} onSegmentClick={onSegmentClick} />;
      case 'species':
      default:
        return <StackedBarChart title={`Ratings by Species Common Name (Top 20 by ${metric === 'volume' ? 'Volume' : 'Count'})`} data={speciesData} metric={metric} chartType="species" columnMapping={columnMapping} onSegmentClick={onSegmentClick} />;
    }
  };

  return (
    <div className="space-y-8 relative">
       {/* Top Metrics Toggle */}
       <div className="flex flex-col sm:flex-row justify-between items-center gap-4 mb-4">
            <div className="flex items-center gap-2 bg-gray-100 p-1 rounded-lg border border-gray-200">
                <span className="text-xs font-semibold text-gray-500 px-2 uppercase tracking-wide">Metric:</span>
                 <button 
                    onClick={() => setMetric('volume')}
                    className={`px-3 py-1.5 text-sm font-medium rounded-md transition-all focus:outline-none ${metric === 'volume' ? 'bg-white text-[#00629B] shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}
                >
                    Volume
                </button>
                <button 
                    onClick={() => setMetric('count')}
                    className={`px-3 py-1.5 text-sm font-medium rounded-md transition-all focus:outline-none ${metric === 'count' ? 'bg-white text-[#00629B] shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}
                >
                    # Products
                </button>
            </div>
       </div>

      <DonutChartByVolume data={donutData} metric={metric} onSegmentClick={onSegmentClick} />

      <div className="space-y-4">
        <div className="flex justify-center sm:justify-end">
          <div className="inline-flex bg-gray-100 p-1 rounded-lg border border-gray-200">
              <button 
                  onClick={() => setActiveChart('species')}
                  className={`px-4 py-2 text-sm font-medium rounded-md transition-all focus:outline-none ${activeChart === 'species' ? 'bg-white text-[#00629B] shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}
              >
                  By Species
              </button>
              <button 
                  onClick={() => setActiveChart('country')}
                  className={`px-4 py-2 text-sm font-medium rounded-md transition-all focus:outline-none ${activeChart === 'country' ? 'bg-white text-[#00629B] shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}
              >
                  By Country
              </button>
              <button 
                  onClick={() => setActiveChart('supplier')}
                  className={`px-4 py-2 text-sm font-medium rounded-md transition-all focus:outline-none ${activeChart === 'supplier' ? 'bg-white text-[#00629B] shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}
              >
                  By Supplier
              </button>
          </div>
        </div>

        {renderActiveChart()}
      </div>
    </div>
  );
};

