}

type GroupedData = Record<string, {
  totalValue: number;
  breakdown: { [key in Rating]?: number };
  sourceItems: SeafoodResultItem[];
}>;

type ChartType = 'species' | 'country' | 'supplier';
type MetricType = 'volume' | 'count';

const ratingLabels: { [key in Rating]: string } = {
  [Rating.BestChoice]: 'Green',
  [Rating.GoodAlternative]: 'Yellow',
  [Rating.Avoid]: 'Red',
  [Rating.Certified]: 'Certified',
  [Rating.NA]: 'N/A',
};

/**
 * Normalizes a label to allow grouping of similar but slightly different strings.
 */
const normalizeLabel = (label: string): string => {
  if (!label) return 'unknown';
  return label
    .toLowerCase()
    .replace(/[^\w\s]/g, ' ')
    .split(/\s+/)
    .filter(Boolean)
    .sort()
    .join(' ');
};

const ChartsView: React.FC<ChartsViewProps> = ({ results, columnMapping, onSegmentClick }) => {
  const [activeChart, setActiveChart] = useState<ChartType>('species');
  const [activeRating, setActiveRating] = useState<Rating | null>(null);

  const [metric, setMetric] = useState<MetricType>(
    columnMapping['Volume'] && columnMapping['Volume'] !== 'N/A' ? 'volume' : 'count'
  );

  const getMappedKey = (field: string) => Object.keys(columnMapping).find(key => key === field) ? columnMapping[field] : null;

  const volumeKey = getMappedKey('Volume');
  const speciesKey = getMappedKey('Common name');
  const countryKey = getMappedKey('Source country');
  const supplierKey = getMappedKey('Supplier');

  const { donutData, speciesData, countryData, supplierData } = useMemo(() => {
    const getValue = (item: SeafoodResultItem) => {
        if (metric === 'count') return 1;
        if (!volumeKey || item[volumeKey] === undefined) return 0;
        const volume = parseFloat(String(item[volumeKey]));
        return isNaN(volume) ? 0 : volume;
    };

    // 1. Always compute donut chart data from FULL result set
    const donutData: { [key in Rating]?: { value: number; items: SeafoodResultItem[] } } = {};
    results.forEach(item => {
        const rating = item.rating;
        if (!donutData[rating]) {
            donutData[rating] = { value: 0, items: [] };
        }
        donutData[rating]!.value += getValue(item);
        donutData[rating]!.items.push(item);
    });

    // 2. Compute bar chart data based on potentially filtered results
    const filteredResults = activeRating 
        ? results.filter(r => r.rating === activeRating)
        : results;

    const processGroupData = (key: string | null): BarChartDataItem[] => {
      if (!key) return [];

      const normalizedMap: Record<string, string> = {};
      const grouped: GroupedData = {};

      filteredResults.forEach(item => {
        const rawLabel = item[key] ? String(item[key]).trim() : 'Unknown';
        const norm = normalizeLabel(rawLabel);

        if (!normalizedMap[norm]) {
            normalizedMap[norm] = rawLabel;
        } else if (rawLabel.length > normalizedMap[norm].length) {
            normalizedMap[norm] = rawLabel;
        }

        const groupLabel = normalizedMap[norm];

        if (!grouped[groupLabel]) {
          grouped[groupLabel] = { totalValue: 0, breakdown: {}, sourceItems: [] };
        }

        const value = getValue(item);
        grouped[groupLabel].totalValue += value;
        grouped[groupLabel].breakdown[item.rating] = (grouped[groupLabel].breakdown[item.rating] || 0) + value;
        grouped[groupLabel].sourceItems.push(item);
      });

      return Object.entries(grouped)
        .map(([label, data]) => ({ label, ...data }))
        .sort((a, b) => b.totalValue - a.totalValue)
        .slice(0, 20);
    };

    const speciesData = processGroupData(speciesKey);
    const countryData = processGroupData(countryKey);
    const supplierData = processGroupData(supplierKey);

    return { donutData, speciesData, countryData, supplierData };
  }, [results, volumeKey, speciesKey, countryKey, supplierKey, metric, activeRating]);

  const handleRatingFilter = (rating: Rating) => {
    if (activeRating === rating) {
        setActiveRating(null); // Toggle off
    } else {
        setActiveRating(rating);
    }
  };

  const renderActiveChart = () => {
    const filterSuffix = activeRating ? ` (Filtered by ${ratingLabels[activeRating]})` : '';
    switch (activeChart) {
      case 'country':
        return <StackedBarChart title={`Ratings by Source Country (Top 20 by ${metric === 'volume' ? 'Volume' : 'Count'})${filterSuffix}`} data={countryData} metric={metric} chartType="country" columnMapping={columnMapping} onSegmentClick={onSegmentClick} />;
      case 'supplier':
        return <StackedBarChart title={`Ratings by Supplier (Top 20 by ${metric === 'volume' ? 'Volume' : 'Count'})${filterSuffix}`} data={supplierData} metric={metric} chartType="supplier" columnMapping={columnMapping} onSegmentClick={onSegmentClick} />;
      case 'species':
      default:
        return <StackedBarChart title={`Ratings by Species Common Name (Top 20 by ${metric === 'volume' ? 'Volume' : 'Count'})${filterSuffix}`} data={speciesData} metric={metric} chartType="species" columnMapping={columnMapping} onSegmentClick={onSegmentClick} />;
    }
  };

  return (
    <div className="space-y-8 relative">
       <div className="flex flex-col sm:flex-row justify-between items-center gap-4 mb-4">
            <div className="flex items-center gap-2 bg-gray-100 p-1 rounded-lg border border-gray-200">
                <span className="text-xs font-semibold text-gray-500 px-2 uppercase tracking-wide">Metric:</span>
                 <button 
                    onClick={() => setMetric('volume')}
                    className={`px-3 py-1.5 text-sm font-medium rounded-md transition-all focus:outline-none ${metric === 'volume' ? 'bg-white text-[#00629B] shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}
                >
                    Volume
                </button>
                <button 
                    onClick={() => setMetric('count')}
                    className={`px-3 py-1.5 text-sm font-medium rounded-md transition-all focus:outline-none ${metric === 'count' ? 'bg-white text-[#00629B] shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}
                >
                    # Products
                </button>
            </div>

            {activeRating && (
                <div className="flex items-center gap-3 animate-fade-in-up">
                    <span className="text-sm text-gray-600">
                        Filtering charts by: <span className="font-bold text-blue-700 bg-blue-50 px-2 py-1 rounded border border-blue-200">{ratingLabels[activeRating]}</span>
                    </span>
