import { User, UserRole } from '../types';

const USERS_KEY = 'seafoodWatchUsers';
const SESSION_KEY = 'seafoodWatchSession';

const DEFAULT_USERS: User[] = [
  { id: '1', username: 'admin', role: 'admin' },
  { id: '2', username: 'partner', role: 'user' },
];

export function getUsers(): User[] {
  const stored = localStorage.getItem(USERS_KEY);
  if (!stored) {
    localStorage.setItem(USERS_KEY, JSON.stringify(DEFAULT_USERS));
    return DEFAULT_USERS;
  }
  return JSON.parse(stored);
}

export function addUser(username: string, role: UserRole): User {
  const users = getUsers();
  const newUser = { id: Date.now().toString(), username, role };
  const updated = [...users, newUser];
  localStorage.setItem(USERS_KEY, JSON.stringify(updated));
  return newUser;
}

export function removeUser(id: string) {
  const users = getUsers();
  const updated = users.filter(u => u.id !== id);
  localStorage.setItem(USERS_KEY, JSON.stringify(updated));
}

export function getCurrentUser(): User | null {
  const session = localStorage.getItem(SESSION_KEY);
  return session ? JSON.parse(session) : null;
}

export function login(username: string): User | null {
  const users = getUsers();
  const user = users.find(u => u.username.toLowerCase() === username.toLowerCase());
  if (user) {
    localStorage.setItem(SESSION_KEY, JSON.stringify(user));
    return user;
  }
  return null;
}

export function logout() {
  localStorage.removeItem(SESSION_KEY);
}

