const Dashboard: React.FC<DashboardProps> = ({ history, onAnalyzeNew, onViewResults, userRole }) => {
  const [expandedRow, setExpandedRow] = useState<string | null>(null);

  const totalRows = history.reduce((acc, curr) => acc + curr.rowCount, 0);

  const totalReliabilitySum = history.reduce((acc, curr) => acc + (curr.averageReliability * curr.rowCount), 0);
  const overallAverageReliability = totalRows > 0 ? Math.round(totalReliabilitySum / totalRows) : 0;

  const totalMatchedRows = history.reduce((acc, curr) => acc + (curr.rowCount * curr.matchPercentage / 100), 0);
  const overallMatchRate = totalRows > 0 ? Math.round((totalMatchedRows / totalRows) * 100) : 0;

  const overallRatingDistribution = history.reduce((acc: { [key in Rating]?: number }, curr) => {
    for (const rating in curr.ratingDistribution) {
      const key = rating as Rating;
      acc[key] = (acc[key] || 0) + (curr.ratingDistribution[key] || 0);
    }
    return acc;
  }, {});

  const allIssues = history.flatMap(h => h.commonIssues);
  const issueCounts = allIssues.reduce((acc, issueItem) => {
    if (issueItem.issue.toLowerCase().includes('analyzing') || issueItem.issue.toLowerCase().includes('error')) {
      return acc;
    }
    acc[issueItem.issue] = (acc[issueItem.issue] || 0) + issueItem.count;
    return acc;
  }, {} as Record<string, number>);

  const topIssues = Object.entries(issueCounts)
    .sort(([, countA], [, countB]) => (countB as number) - (countA as number))
    .slice(0, 5);

  return (
    <div className="space-y-8">
      <div className="flex justify-between items-center">
          <h2 className="text-2xl font-bold text-gray-800">
            {userRole === 'admin' ? 'Administrative Dashboard' : 'Partner Dashboard'}
          </h2>
          <button
            onClick={onAnalyzeNew}
            className="w-full sm:w-auto px-6 py-3 text-lg font-semibold text-white bg-[#00629B] rounded-md hover:bg-[#00497b] focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-[#00629B] transition-colors duration-200"
          >
            Upload New Dataset
          </button>
      </div>

      {history.length > 0 ? (
        <>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                <StatCard title="Overall Match Rate" value={`${overallMatchRate}%`} icon={<svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>} />
                <StatCard title="Avg. Reliability" value={`${overallAverageReliability}%`} icon={<svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="2"><path strokeLinecap="round" strokeLinejoin="round" d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z" /></svg>} />
                <StatCard title="Total Items Analyzed" value={totalRows.toLocaleString()} icon={<svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h7" /></svg>} />
                <StatCard title="Datasets" value={history.length.toString()} icon={<svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12" /></svg>} />
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                <div className="lg:col-span-2 bg-white p-6 rounded-lg shadow-lg border border-gray-200">
                    <h2 className="text-xl font-bold text-gray-800 mb-4">Sourcing History</h2>
                    <div className="overflow-x-auto">
                        <table className="min-w-full divide-y divide-gray-200">
                            <thead className="bg-gray-50">
                                <tr>
                                    <th scope="col" className="px-2 py-3 w-12"><span className="sr-only">Expand</span></th>
                                    <th scope="col" className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">File Name</th>
                                    <th scope="col" className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Date</th>
                                    <th scope="col" className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider text-right">Actions</th>
                                </tr>
                            </thead>
                            <tbody className="bg-white divide-y divide-gray-200">
                                {history.map(item => (
                                    <React.Fragment key={item.id}>
                                    <tr className="hover:bg-gray-50">
                                        <td className="px-2 py-4 whitespace-nowrap">
                                          <button 
                                            onClick={() => setExpandedRow(expandedRow === item.id ? null : item.id)}
                                            className="p-1 rounded-full hover:bg-gray-200"
                                          >
                                            <svg xmlns="http://www.w3.org/2000/svg" className={`h-5 w-5 text-gray-500 transition-transform duration-200 ${expandedRow === item.id ? 'rotate-90' : ''}`} viewBox="0 0 20 20" fill="currentColor">
                                                <path fillRule="evenodd" d="M7.293 14.707a1 1 0 010-1.414L10.586 10 7.293 6.707a1 1 0 011.414-1.414l4 4a1 1 0 010 1.414l-4 4a1 1 0 01-1.414 0z" clipRule="evenodd" />
                                            </svg>
                                          </button>
                                        </td>
                                        <td className="px-4 py-4 whitespace-nowrap text-sm font-medium text-gray-900">{item.fileName}</td>
                                        <td className="px-4 py-4 whitespace-nowrap text-sm text-gray-500">{new Date(item.uploadDate).toLocaleDateString()}</td>
                                        <td className="px-4 py-4 whitespace-nowrap text-right">
                                          <button 
                                            onClick={() => onViewResults(item)}
                                            className="text-blue-600 hover:text-blue-900 font-bold text-xs uppercase tracking-wider"
                                          >
                                            View Report
                                          </button>
                                        </td>
                                    </tr>
                                    {expandedRow === item.id && (
                                      <tr>
                                        <td colSpan={6} className="p-4 bg-gray-50 border-t">
                                          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                                            <div>
                                              <h4 className="font-semibold text-gray-700 mb-2">Metrics Summary</h4>
                                              <div className="grid grid-cols-2 gap-4 text-xs">
                                                <div className="bg-white p-2 rounded border">
                                                  <span className="text-gray-400">Match Rate:</span>
                                                  <span className="block font-bold">{item.matchPercentage.toFixed(0)}%</span>
                                                </div>
                                                <div className="bg-white p-2 rounded border">
                                                  <span className="text-gray-400">Reliability:</span>
                                                  <span className="block font-bold">{item.averageReliability.toFixed(0)}%</span>
                                                </div>
                                              </div>
                                            </div>
                                            <div>
                                              <h4 className="font-semibold text-gray-700 mb-2">Rating Distribution</h4>
                                              <div className="flex flex-wrap gap-2">
                                                {Object.entries(item.ratingDistribution).map(([rating, count]) => (
                                                  <div key={rating} className="flex items-center gap-2 bg-white p-2 rounded-md border text-[10px]">
                                                    <RatingBadge rating={rating as Rating} />
                                                    <span className="font-bold text-gray-800">{count}</span>
                                                  </div>
                                                ))}
                                              </div>
                                            </div>
                                          </div>
                                        </td>
                                      </tr>
                                    )}
                                    </React.Fragment>
                                ))}
                            </tbody>
                        </table>
                    </div>
                </div>

                <div className="space-y-8">
                  <div className="bg-white p-6 rounded-lg shadow-lg border border-gray-200">
                      <h2 className="text-xl font-bold text-gray-800 mb-4">Network Sustainability</h2>
                      {totalRows > 0 ? (
                        <DonutChart data={overallRatingDistribution} total={totalRows} />
                      ) : <p className="text-sm text-gray-500">No data to display.</p> }
                  </div>
                  <div className="bg-white p-6 rounded-lg shadow-lg border border-gray-200">
                      <h2 className="text-xl font-bold text-gray-800 mb-4">Global Data Gaps</h2>
                      {topIssues.length > 0 ? (
                          <ul className="space-y-3">
                              {topIssues.map(([issue, count]) => (
                                  <li key={issue} className="text-sm text-gray-700">
                                      <p className="font-semibold leading-tight">{issue}</p>
                                      <p className="text-gray-500 text-xs mt-1">Found in {count} records</p>
                                  </li>
                              ))}
                          </ul>
                      ) : (
                          <p className="text-sm text-gray-500">No recurring data gaps identified.</p>
                      )}
                  </div>
                </div>
            </div>
        </>
      ) : (
         <div className="text-center bg-white p-12 rounded-lg shadow-lg border border-gray-200 flex flex-col items-center">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-16 w-16 text-gray-300 mb-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M9 17v-2m3 2v-4m3 4v-6m2 10H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
            </svg>
            <p className="text-gray-500 text-lg mb-6">No sourcing history found. Start by uploading a dataset.</p>
            <button
              onClick={onAnalyzeNew}
              className="px-8 py-4 text-lg font-semibold text-white bg-[#00629B] rounded-md hover:bg-[#00497b]"
            >
              Upload First Dataset
            </button>
         </div>
      )}
    </div>
  );
};

export default Dashboard;

import React, { useState, useCallback, useEffect, useRef } from 'react';
import { SeafoodInputItem, SeafoodResultItem, Rating, UploadSummary, User } from './types';
import { rateSeafoodData, analyzeSheetLayout, updateAnalysisForId } from './services/geminiService';
import { loadDatabaseFromUrl } from './services/referenceDatabase';
import { getUploadHistory, saveUploadToHistory } from './services/historyService';
import { performDataAudit, AuditReport } from './services/dataAuditService';
import { getCurrentUser, logout } from './services/authService';
import Header from './components/Header';
import FileUpload from './components/FileUpload';
import ResultsTable from './components/ResultsTable';
import Loader from './components/Loader';
import Dashboard from './components/Dashboard';
import ColumnMapper from './components/ColumnMapper';
import DataPreview from './components/DataPreview';
import ChartsView from './components/ChartsView';
import Modal from './components/Modal';
import DataQualityAudit from './components/DataQualityAudit';
import Login from './components/Login';
import UserManagement from './components/UserManagement';

// This declaration is necessary because the library is loaded from a script tag in index.html
declare var XLSX: any;

type View = 'dashboard' | 'analyzer' | 'users';
type AnalyzerState = 'upload' | 'preview' | 'mapping' | 'audit' | 'loading' | 'results';
type ResultsViewMode = 'table' | 'charts';

const MAPPABLE_FIELDS = [
  'Wild or Farmed',
  'Common name',
  'Scientific name',
  'Source country',
  'Body of water',
  'Production Method',
  'Certification',
  'Supplier',
  'Product Name',
  'Volume',
];

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [view, setView] = useState<View>('dashboard');
  const [analyzerState, setAnalyzerState] = useState<AnalyzerState>('upload');
  const [results, setResults] = useState<SeafoodResultItem[] | null>(null);
  const [error, setError] = useState<string | null>(null);

  // State for raw data and headers
  const [originalData, setOriginalData] = useState<SeafoodInputItem[] | null>(null);
  const [originalHeaders, setOriginalHeaders] = useState<string[]>([]);
  const [currentFileName, setCurrentFileName] = useState<string>('');

  // State for column mapping and display-optimized results
  const [columnMapping, setColumnMapping] = useState<Record<string, string>>({});
  const [displayResults, setDisplayResults] = useState<any[] | null>(null);
  const [displayHeaders, setDisplayHeaders] = useState<string[]>([]);
  const [visibleColumns, setVisibleColumns] = useState<Set<string>>(new Set());
  const [auditReport, setAuditReport] = useState<AuditReport | null>(null);

  // State for preview step
  const [workbook, setWorkbook] = useState<any>(null); // XLSX workbook object
  const [sheetNames, setSheetNames] = useState<string[]>([]);
  const [selectedSheet, setSelectedSheet] = useState<string>('');
  const [headerRowIndex, setHeaderRowIndex] = useState<number>(1);
  const [previewData, setPreviewData] = useState<(string|number)[][]>([]);
  const [isPreviewLoading, setIsPreviewLoading] = useState<boolean>(false);
  const [previewWarning, setPreviewWarning] = useState<string | null>(null);

  const [uploadHistory, setUploadHistory] = useState<UploadSummary[]>([]);
  const [progress, setProgress] = useState<{ processed: number; total: number } | null>(null);

  // State for results view
  const [resultsViewMode, setResultsViewMode] = useState<ResultsViewMode>('table');
  const [activeFilter, setActiveFilter] = useState<{title: string; data: any[]} | null>(null);
  const [isFilterModalOpen, setIsFilterModalOpen] = useState(false);
  const [modalFilterData, setModalFilterData] = useState<{title: string; data: SeafoodResultItem[]} | null>(null);

  const analysisAbortController = useRef<AbortController | null>(null);

  useEffect(() => {
    const user = getCurrentUser();
    if (user) {
      setCurrentUser(user);
      // Admin: default to Dashboard. User: default to Analyzer.
      setView(user.role === 'admin' ? 'dashboard' : 'analyzer');
    }

    setUploadHistory(getUploadHistory());
    loadDatabaseFromUrl('seafood-watch-data.csv');
  }, []);

  const handleLogin = (user: User) => {
    setCurrentUser(user);
    setView(user.role === 'admin' ? 'dashboard' : 'analyzer');
  };

  const handleLogout = () => {
    logout();
    setCurrentUser(null);
    resetAnalyzerState();
  };

  const resetAnalyzerState = () => {
    setResults(null);
    setDisplayResults(null);
    setDisplayHeaders([]);
    setError(null);
    setOriginalData(null);
    setOriginalHeaders([]);
    setCurrentFileName('');
    setProgress(null);
    setWorkbook(null);
    setSheetNames([]);
    setSelectedSheet('');
    setHeaderRowIndex(1);
    setPreviewData([]);
    setColumnMapping({});
    setAuditReport(null);
    setVisibleColumns(new Set());
    setResultsViewMode('table');
    setActiveFilter(null);
    setIsFilterModalOpen(false);
    setModalFilterData(null);
    setAnalyzerState('upload');
    setIsPreviewLoading(false);
    setPreviewWarning(null);
    analysisAbortController.current = null;
  };

  const generatePreviewData = (worksheet: any) => {
    const previewJson: (string|number)[][] = XLSX.utils.sheet_to_json(worksheet, { header: 1, defval: '', raw: false, blankrows: false });
    setPreviewData(previewJson.slice(0, 15)); // Preview first 15 rows
  };

  const handleProcessFile = useCallback(async (file: File) => {
    resetAnalyzerState();
    setAnalyzerState('preview');
    setIsPreviewLoading(true);

    const reader = new FileReader();
    reader.onload = async (e) => {
      try {
        const data = e.target?.result;
        if (!data) throw new Error("File data could not be read.");

        let wb: any;
        try {
          wb = XLSX.read(data, { type: 'binary', cellNF: false, cellText: false });
        } catch (parseError) {
          console.error("File parsing error:", parseError);
          throw new Error("Could not parse file. Please ensure it is a valid, uncorrupted XLSX or CSV file.");
        }

        const names = wb.SheetNames;
        if (names.length === 0) {
          throw new Error("The uploaded file is empty or contains no sheets.");
        }

        setWorkbook(wb);
        setSheetNames(names);
        setCurrentFileName(file.name);

        let bestSheetName = names[0];
        let bestHeaderRow = 1;

        try {
          const sheetPreviews = names.map(name => {
            const ws = wb.Sheets[name];
            const sheetData = XLSX.utils.sheet_to_json(ws, { header: 1, defval: '', raw: false, blankrows: false }).slice(0, 15);
            return { sheetName: name, data: sheetData };
          });

          const layout = await analyzeSheetLayout(sheetPreviews);
          bestSheetName = layout.bestSheetName;
          bestHeaderRow = layout.bestHeaderRow;
        } catch (aiError) {
          console.warn("AI sheet analysis failed, falling back to default.", aiError);
          setPreviewWarning("AI analysis for sheet layout failed. We've selected the first sheet and header row as a default.");
        }

        setSelectedSheet(bestSheetName);
        setHeaderRowIndex(bestHeaderRow);
        generatePreviewData(wb.Sheets[bestSheetName]);

      } catch (err: any) {
        console.error(err);
        setError(`Error processing file: ${err.message}`);
        setAnalyzerState('upload');
      } finally {
        setIsPreviewLoading(false);
      }
    };
    reader.readAsBinaryString(file);
  }, []);

  const handleSheetChange = (sheetName: string) => {
    if (workbook) {
      setSelectedSheet(sheetName);
      generatePreviewData(workbook.Sheets[sheetName]);
    }
  };

  const handleHeaderRowChange = (newRowIndex: number) => {
    setHeaderRowIndex(newRowIndex);
  };

  const handleConfirmPreview = useCallback(() => {
    setError(null);
    if (!workbook || !selectedSheet) {
        setError("Workbook data is missing. Please re-upload.");
        setAnalyzerState('upload');
        return;
    }

    try {
        const worksheet = workbook.Sheets[selectedSheet];
        const dataAsArray: any[][] = XLSX.utils.sheet_to_json(worksheet, { header: 1, defval: '', blankrows: false });

        if (dataAsArray.length < headerRowIndex) {
            throw new Error(`Header row ${headerRowIndex} does not exist in the data.`);
        }

        const rawHeaders: string[] = dataAsArray[headerRowIndex - 1].map(header => String(header).trim());
        const headers: string[] = [];
        const counts: Record<string, number> = {};

        for (const header of rawHeaders) {
            if (!header) {
                headers.push('');
                continue;
            }
            counts[header] = (counts[header] || 0) + 1;
            if (counts[header] > 1) {
                let newHeader = `${header} (${counts[header]})`;
                while (rawHeaders.includes(newHeader) || headers.includes(newHeader)) {
                    counts[header]++;
                    newHeader = `${header} (${counts[header]})`;
                }
                headers.push(newHeader);
            } else {
                headers.push(header);
            }
        }

        const jsonData = dataAsArray.slice(headerRowIndex).map(row => {
            const rowObject: SeafoodInputItem = {};
            headers.forEach((header, index) => {
                if(header) {
                    rowObject[header] = row[index];
                }
            });
            return rowObject;
        }).filter(obj => Object.keys(obj).length > 0);

        if (jsonData.length === 0) {
          throw new Error("The selected sheet and header row result in no data to process.");
        }

        setOriginalData(jsonData);
        setOriginalHeaders(headers.filter(h => h));
        setAnalyzerState('mapping');

    } catch(err: any) {
        setError(`Error processing sheet: ${err.message}`);
    }
  }, [workbook, selectedSheet, headerRowIndex]);

  const handleConfirmMapping = useCallback((mapping: Record<string, string>) => {
    if (!originalData) {
        setError("Original data missing.");
        setAnalyzerState('upload');
        return;
    }
    setColumnMapping(mapping);
    const report = performDataAudit(originalData, mapping);
    setAuditReport(report);
    setAnalyzerState('audit');
  }, [originalData]);

  const handleStartAnalysis = useCallback(async () => {
    if (!originalData) return;
    setAnalyzerState('loading');
    setError(null);
    analysisAbortController.current = new AbortController();

    try {
        const commonNameHeader = columnMapping['Common name'];
        let dataToProcess = originalData;
        if (commonNameHeader && commonNameHeader !== 'N/A') {
            dataToProcess = originalData.filter(row => {
                const val = row[commonNameHeader];
                return val !== undefined && val !== null && String(val).trim() !== '';
            });
        }

        setProgress({ processed: 0, total: dataToProcess.length });
        if (dataToProcess.length === 0) {
             throw new Error("No valid rows found to process. Please ensure your data has values in the 'Common name' column.");
        }

        const transformedData = dataToProcess.map(row => {
            const newRow: { [key: string]: string | number } = {};
            for (const mappableField of MAPPABLE_FIELDS) {
                const userColumnName = columnMapping[mappableField];
                if (userColumnName && userColumnName !== 'N/A' && row[userColumnName] !== undefined) {
                    newRow[mappableField] = row[userColumnName];
                }
            }
            return newRow;
        });

        const handleProgressUpdate = (processed: number, total: number) => {
          setProgress({ processed, total });
        };

        const analysisResults = await rateSeafoodData(transformedData, handleProgressUpdate, analysisAbortController.current.signal);

        const finalResults: SeafoodResultItem[] = dataToProcess.map((originalItem, index) => {
            const analysisPart = analysisResults[index];
            return {
                ...originalItem,
                uniqueId: analysisPart.uniqueId,
                matchedKDEs: analysisPart.matchedKDEs, 
                rating: analysisPart.rating,
                reliabilityScore: analysisPart.reliabilityScore,
                notes: analysisPart.notes,
            };
        });

        setResults(finalResults);
        setDisplayResults(finalResults);
        setDisplayHeaders(originalHeaders);

        const mappedHeaders = Object.values(columnMapping).filter(h => h && h !== 'N/A') as string[];
        setVisibleColumns(new Set([...mappedHeaders, 'uniqueId', 'rating', 'reliabilityScore']));

        const matchedCount = finalResults.filter(r => r.rating !== Rating.NA).length;
        const matchPercentage = finalResults.length > 0 ? (matchedCount / finalResults.length) * 100 : 0;
        const totalReliability = finalResults.reduce((acc, r) => acc + r.reliabilityScore, 0);
        const averageReliability = finalResults.length > 0 ? totalReliability / finalResults.length : 0;
        const ratingDistribution = finalResults.reduce<{[key in Rating]?: number}>((acc, item) => {
            acc[item.rating] = (acc[item.rating] || 0) + 1;
            return acc;
        }, {});

        const noteCounts = finalResults.reduce((acc, item) => {
          acc[item.notes] = (acc[item.notes] || 0) + 1;
          return acc;
        }, {} as { [key: string]: number });
        const commonIssues = Object.entries(noteCounts)
          .sort(([, countA], [, countB]) => (countB as number) - (countA as number))
          .slice(0, 5)
          .map(([issue, count]) => ({ issue, count: count as number }));

        const uploadSummaryData: Omit<UploadSummary, 'id' | 'uploadDate'> = {
            fileName: currentFileName, 
            rowCount: finalResults.length, 
            matchPercentage,
            averageReliability, 
            ratingDistribution, 
            commonIssues,
            fullResults: finalResults,
            columnMapping: columnMapping,
            originalHeaders: originalHeaders
        };

        setUploadHistory(saveUploadToHistory(uploadSummaryData));
        setAnalyzerState('results');
    } catch (err: any) {
        if (err.name === 'AbortError' || err.message.includes('aborted')) return;
        setError(`An error occurred during analysis: ${err.message}`);
        setAnalyzerState('audit'); 
    }
  }, [originalData, currentFileName, originalHeaders, columnMapping]);

  const handleCancelAnalysis = useCallback(() => {
    if (analysisAbortController.current) {
        analysisAbortController.current.abort();
    }
    setAnalyzerState('audit');
    setError(null);
  }, []);

  const handleViewHistoricalResults = (summary: UploadSummary) => {
    if (summary.fullResults && summary.columnMapping && summary.originalHeaders) {
      setResults(summary.fullResults);
      setDisplayResults(summary.fullResults);
      setDisplayHeaders(summary.originalHeaders);
      setColumnMapping(summary.columnMapping);
      setCurrentFileName(summary.fileName);

      const mappedHeaders = Object.values(summary.columnMapping).filter(h => h && h !== 'N/A') as string[];
      setVisibleColumns(new Set([...mappedHeaders, 'uniqueId', 'rating', 'reliabilityScore']));

      setView('analyzer');
      setAnalyzerState('results');
      setResultsViewMode('table');
    } else {
      setError("This historical report doesn't contain detailed result data.");
    }
  };

  const handleUpdateResult = useCallback(async (index: number, newUniqueId: string) => {
     if (!results || !results[index]) return;
     const updatedResults = [...results];
     updatedResults[index] = { ...updatedResults[index], isUpdating: true, uniqueId: newUniqueId };
     setResults(updatedResults);
     setDisplayResults(updatedResults);

     try {
         const originalItem = updatedResults[index];
         const updatedAnalysis = await updateAnalysisForId(originalItem, newUniqueId);
         const finalResults = [...results];
         finalResults[index] = { ...originalItem, ...updatedAnalysis, isUpdating: false };
         setResults(finalResults);
         setDisplayResults(finalResults);
     } catch (err) {
         console.error("Failed to update result:", err);
         const revertedResults = [...results];
         revertedResults[index] = { ...revertedResults[index], isUpdating: false };
         setResults(revertedResults);
         setDisplayResults(revertedResults);
         setError("Failed to update the record.");
     }
  }, [results]);

  const handleExport = useCallback(() => {
    if (!results || originalHeaders.length === 0) return;
    const headers = [...originalHeaders, 'Unique ID', 'Matched KDEs', 'Rating', 'Reliability Score', 'Notes'];
    const escapeCsv = (val: any): string => {
        if (val === undefined || val === null) return '';
        const str = String(val);
        if (str.includes(',') || str.includes('"') || str.includes('\n')) {
            return `"${str.replace(/"/g, '""')}"`;
        }
        return str;
    };
    const csvContent = [
        headers.join(','),
        ...results.map(row => {
            const originalValues = originalHeaders.map(header => escapeCsv(row[header]));
            const analysisValues = [
                escapeCsv(row.uniqueId), 
                escapeCsv(row.matchedKDEs),
                escapeCsv(row.rating), 
                escapeCsv(row.reliabilityScore), 
                escapeCsv(row.notes)
            ];
            return [...originalValues, ...analysisValues].join(',');
        })
    ].join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.setAttribute('download', `${currentFileName.replace(/\.[^/.]+$/, "")}_analyzed.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  }, [results, originalHeaders, currentFileName]);

  const handleChartSegmentClick = (title: string, data: SeafoodResultItem[]) => {
    setModalFilterData({ title, data });
    setIsFilterModalOpen(true);
  };
  const handleConfirmFilter = () => {
    if (modalFilterData) {
      setActiveFilter({ title: modalFilterData.title, data: modalFilterData.data });
      setResultsViewMode('table');
    }
    setIsFilterModalOpen(false);
  };

  if (!currentUser) {
    return <Login onLogin={handleLogin} />;
  }

  const renderContent = () => {
    if (view === 'users' && currentUser.role === 'admin') {
      return <UserManagement />;
    }

    if (view === 'dashboard') {
      return (
          <div className="animate-fade-in-up">
              <Dashboard 
                history={uploadHistory} 
                onAnalyzeNew={() => { resetAnalyzerState(); setView('analyzer'); }} 
                onViewResults={handleViewHistoricalResults}
                userRole={currentUser.role}
              />
          </div>
      );
    }

    return (
      <div className="animate-fade-in-up" key={analyzerState}>
        {error && (
            <div className="bg-red-100 border border-red-400 text-red-700 px-4 py-3 rounded-lg relative my-6 max-w-4xl mx-auto" role="alert">
              <strong className="font-bold">Error:</strong><span className="block sm:inline ml-2">{error}</span>
            </div>
        )}
        {analyzerState === 'upload' && <FileUpload onProcessFile={handleProcessFile} isLoading={false} />}
        {analyzerState === 'preview' && <DataPreview isAnalyzing={isPreviewLoading} sheetNames={sheetNames} selectedSheet={selectedSheet} onSheetChange={handleSheetChange} headerRowIndex={headerRowIndex} onHeaderRowChange={handleHeaderRowChange} previewData={previewData} onConfirm={handleConfirmPreview} onCancel={resetAnalyzerState} warning={previewWarning}/>}
        {analyzerState === 'mapping' && originalHeaders.length > 0 && <ColumnMapper fileHeaders={originalHeaders} mappableFields={MAPPABLE_FIELDS} onConfirm={handleConfirmMapping} onCancel={() => { setOriginalData(null); setAnalyzerState('preview'); }}/>}
        {analyzerState === 'audit' && auditReport && <DataQualityAudit report={auditReport} onConfirm={handleStartAnalysis} onBack={() => setAnalyzerState('mapping')} />}
        {analyzerState === 'loading' && <Loader progress={progress} onCancel={handleCancelAnalysis} />}
        {analyzerState === 'results' && results && displayResults && (
          <div className="flex flex-col items-center space-y-6">
            <div className="flex justify-center p-1 bg-gray-200 rounded-lg" role="tablist">
              <button onClick={() => setResultsViewMode('table')} className={`px-4 py-2 text-sm font-semibold rounded-md ${resultsViewMode === 'table' ? 'bg-white shadow text-gray-800' : 'text-gray-600'}`}>Table</button>
              <button onClick={() => setResultsViewMode('charts')} className={`px-4 py-2 text-sm font-semibold rounded-md ${resultsViewMode === 'charts' ? 'bg-white shadow text-gray-800' : 'text-gray-600'}`}>Charts</button>
            </div>
            <div className="w-full max-w-7xl">
              {resultsViewMode === 'table' ? (
                <ResultsTable 
                    results={activeFilter ? activeFilter.data : displayResults} 
                    originalHeaders={displayHeaders} 
                    columnMapping={columnMapping}
                    onExport={handleExport}
                    filterTitle={activeFilter?.title}
                    onClearFilter={() => setActiveFilter(null)}
                    visibleColumns={visibleColumns}
                    onVisibleColumnsChange={setVisibleColumns}
                    onUpdateResult={handleUpdateResult}
                />
              ) : (
                <ChartsView results={results} columnMapping={columnMapping} onSegmentClick={handleChartSegmentClick} />
              )}
            </div>
            <button onClick={() => setView('dashboard')} className="px-6 py-2 font-semibold text-white bg-[#00629B] rounded-md hover:bg-[#00497b]">Back to Dashboard</button>
          </div>
        )}
         <Modal isOpen={isFilterModalOpen} onClose={() => setIsFilterModalOpen(false)} onConfirm={handleConfirmFilter} title="View Filtered Data">
            <p>Would you like to see the {modalFilterData?.data.length} items for "{modalFilterData?.title}" in the data table?</p>
         </Modal>
      </div>
    );
  };

  return (
    <div className="min-h-screen bg-gray-50 text-gray-800 font-sans">
      <nav className="bg-[#00629B] text-white shadow-lg">
        <div className="container mx-auto px-6 py-3 flex justify-between items-center">
          <div className="flex items-center gap-8">
            <h1 className="text-lg font-bold">Seafood Watch Sourcing</h1>
            <div className="hidden md:flex gap-4">
              <button onClick={() => setView('dashboard')} className={`text-sm px-3 py-1 rounded hover:bg-[#00497b] transition-colors ${view === 'dashboard' ? 'bg-[#00497b] font-bold underline decoration-2' : ''}`}>Dashboard</button>
              <button onClick={() => { resetAnalyzerState(); setView('analyzer'); }} className={`text-sm px-3 py-1 rounded hover:bg-[#00497b] transition-colors ${view === 'analyzer' ? 'bg-[#00497b] font-bold underline decoration-2' : ''}`}>New Analysis</button>
              {currentUser.role === 'admin' && (
                <button onClick={() => setView('users')} className={`text-sm px-3 py-1 rounded hover:bg-[#00497b] transition-colors ${view === 'users' ? 'bg-[#00497b] font-bold underline decoration-2' : ''}`}>Manage Users</button>
              )}
            </div>
          </div>
          <div className="flex items-center gap-4">
            <div className="text-right hidden sm:block">
              <p className="text-xs font-bold opacity-80 uppercase tracking-tighter">Signed in as</p>
              <p className="text-sm font-medium">{currentUser.username} ({currentUser.role})</p>
            </div>
            <button onClick={handleLogout} className="text-xs font-bold bg-white text-[#00629B] px-3 py-1 rounded hover:bg-gray-100 transition-colors uppercase">Logout</button>
          </div>
        </div>
      </nav>
      <Header />
      <main className="container mx-auto p-4 sm:p-6 md:p-8">
        {renderContent()}
      </main>
      <footer className="text-center py-4 text-gray-400 text-xs border-t bg-white">
        <p>&copy; {new Date().getFullYear()} Monterey Bay Aquarium Seafood Watch Program • Internal Partner Portal</p>
      </footer>
    </div>
  );
};

export default App;

export enum Rating {
  BestChoice = "Best Choice",
  GoodAlternative = "Good Alternative",
  Avoid = "Avoid",
  Certified = "Certified",
  NA = "N/A",
}

export type UserRole = 'admin' | 'user';

export interface User {
  id: string;
  username: string;
  role: UserRole;
}

export interface SeafoodInputItem {
  [key: string]: string | number | boolean | null | undefined;
}

export interface SeafoodResultItem extends SeafoodInputItem {
  rating: Rating;
  uniqueId: string;
  matchedKDEs: string;
  reliabilityScore: number;
  notes: string;
  isUpdating?: boolean; // Used for UI loading state during manual edits
}

export interface UploadSummary {
  id: string;
  fileName: string;
  uploadDate: string; // ISO string
  rowCount: number;
  matchPercentage: number;
  averageReliability: number;
  ratingDistribution: { [key in Rating]?: number };
  commonIssues: { issue: string; count: number }[];
  // Extended for persistence
  fullResults?: SeafoodResultItem[];
  columnMapping?: Record<string, string>;
  originalHeaders?: string[];
}

import React, { useState, useCallback, useEffect, useRef } from 'react';
import { SeafoodInputItem, SeafoodResultItem, Rating, UploadSummary, User } from './types';
import { rateSeafoodData, analyzeSheetLayout, updateAnalysisForId } from './services/geminiService';
import { loadDatabaseFromUrl } from './services/referenceDatabase';
import { getUploadHistory, saveUploadToHistory } from './services/historyService';
import { performDataAudit, AuditReport } from './services/dataAuditService';
import { getCurrentUser, logout } from './services/authService';
import Header from './components/Header';
import FileUpload from './components/FileUpload';
import ResultsTable from './components/ResultsTable';
import Loader from './components/Loader';
import Dashboard from './components/Dashboard';
import ColumnMapper from './components/ColumnMapper';
import DataPreview from './components/DataPreview';
import ChartsView from './components/ChartsView';
import Modal from './components/Modal';
import DataQualityAudit from './components/DataQualityAudit';
import Login from './components/Login';
import UserManagement from './components/UserManagement';

// This declaration is necessary because the library is loaded from a script tag in index.html
declare var XLSX: any;

type View = 'dashboard' | 'analyzer' | 'users';
type AnalyzerState = 'upload' | 'preview' | 'mapping' | 'audit' | 'loading' | 'results';
type ResultsViewMode = 'table' | 'charts';

const MAPPABLE_FIELDS = [
  'Wild or Farmed',
  'Common name',
  'Scientific name',
  'Source country',
  'Body of water',
  'Production Method',
  'Certification',
  'Supplier',
  'Product Name',
  'Volume',
];

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [view, setView] = useState<View>('dashboard');
  const [analyzerState, setAnalyzerState] = useState<AnalyzerState>('upload');
  const [results, setResults] = useState<SeafoodResultItem[] | null>(null);
  const [error, setError] = useState<string | null>(null);

  // State for raw data and headers
  const [originalData, setOriginalData] = useState<SeafoodInputItem[] | null>(null);
  const [originalHeaders, setOriginalHeaders] = useState<string[]>([]);
  const [currentFileName, setCurrentFileName] = useState<string>('');

  // State for column mapping and display-optimized results
  const [columnMapping, setColumnMapping] = useState<Record<string, string>>({});
  const [displayResults, setDisplayResults] = useState<any[] | null>(null);
  const [displayHeaders, setDisplayHeaders] = useState<string[]>([]);
  const [visibleColumns, setVisibleColumns] = useState<Set<string>>(new Set());
  const [auditReport, setAuditReport] = useState<AuditReport | null>(null);

  // State for preview step
  const [workbook, setWorkbook] = useState<any>(null); // XLSX workbook object
  const [sheetNames, setSheetNames] = useState<string[]>([]);
  const [selectedSheet, setSelectedSheet] = useState<string>('');
  const [headerRowIndex, setHeaderRowIndex] = useState<number>(1);
  const [previewData, setPreviewData] = useState<(string|number)[][]>([]);
  const [isPreviewLoading, setIsPreviewLoading] = useState<boolean>(false);
  const [previewWarning, setPreviewWarning] = useState<string | null>(null);

  const [uploadHistory, setUploadHistory] = useState<UploadSummary[]>([]);
  const [progress, setProgress] = useState<{ processed: number; total: number } | null>(null);

  // State for results view
  const [resultsViewMode, setResultsViewMode] = useState<ResultsViewMode>('table');
  const [activeFilter, setActiveFilter] = useState<{title: string; data: any[]} | null>(null);
  const [isFilterModalOpen, setIsFilterModalOpen] = useState(false);
  const [modalFilterData, setModalFilterData] = useState<{title: string; data: SeafoodResultItem[]} | null>(null);

  const analysisAbortController = useRef<AbortController | null>(null);

  useEffect(() => {
    const user = getCurrentUser();
    if (user) {
      setCurrentUser(user);
      // Admin: default to Dashboard. User: default to Analyzer (Upload view).
      setView(user.role === 'admin' ? 'dashboard' : 'analyzer');
    }

    setUploadHistory(getUploadHistory());
    loadDatabaseFromUrl('seafood-watch-data.csv');
  }, []);

  const handleLogin = (user: User) => {
    setCurrentUser(user);
    // Role based landing page
    setView(user.role === 'admin' ? 'dashboard' : 'analyzer');
  };

  const handleLogout = () => {
    logout();
    setCurrentUser(null);
    resetAnalyzerState();
  };

  const resetAnalyzerState = useCallback(() => {
    setResults(null);
    setDisplayResults(null);
    setDisplayHeaders([]);
    setError(null);
    setOriginalData(null);
    setOriginalHeaders([]);
    setCurrentFileName('');
    setProgress(null);
    setWorkbook(null);
    setSheetNames([]);
    setSelectedSheet('');
    setHeaderRowIndex(1);
    setPreviewData([]);
    setColumnMapping({});
    setAuditReport(null);
    setVisibleColumns(new Set());
    setResultsViewMode('table');
    setActiveFilter(null);
    setIsFilterModalOpen(false);
    setModalFilterData(null);
    setAnalyzerState('upload');
    setIsPreviewLoading(false);
    setPreviewWarning(null);
    analysisAbortController.current = null;
  }, []);

  const generatePreviewData = (worksheet: any) => {
    const previewJson: (string|number)[][] = XLSX.utils.sheet_to_json(worksheet, { header: 1, defval: '', raw: false, blankrows: false });
    setPreviewData(previewJson.slice(0, 15)); // Preview first 15 rows
  };

  const handleProcessFile = useCallback(async (file: File) => {
    resetAnalyzerState();
    setAnalyzerState('preview');
    setIsPreviewLoading(true);

    const reader = new FileReader();
    reader.onload = async (e) => {
      try {
        const data = e.target?.result;
        if (!data) throw new Error("File data could not be read.");

        let wb: any;
        try {
          wb = XLSX.read(data, { type: 'binary', cellNF: false, cellText: false });
        } catch (parseError) {
          console.error("File parsing error:", parseError);
          throw new Error("Could not parse file. Please ensure it is a valid XLSX or CSV file.");
        }

        const names = wb.SheetNames;
        if (names.length === 0) throw new Error("The file contains no sheets.");

        setWorkbook(wb);
        setSheetNames(names);
        setCurrentFileName(file.name);

        let bestSheetName = names[0];
        let bestHeaderRow = 1;

        try {
          const sheetPreviews = names.map(name => {
            const ws = wb.Sheets[name];
            const sheetData = XLSX.utils.sheet_to_json(ws, { header: 1, defval: '', raw: false, blankrows: false }).slice(0, 15);
            return { sheetName: name, data: sheetData };
          });
          const layout = await analyzeSheetLayout(sheetPreviews);
          bestSheetName = layout.bestSheetName;
          bestHeaderRow = layout.bestHeaderRow;
        } catch (aiError) {
          setPreviewWarning("AI auto-layout failed. Manual selection required.");
        }

        setSelectedSheet(bestSheetName);
        setHeaderRowIndex(bestHeaderRow);
        generatePreviewData(wb.Sheets[bestSheetName]);

      } catch (err: any) {
        setError(`Error processing file: ${err.message}`);
        setAnalyzerState('upload');
      } finally {
        setIsPreviewLoading(false);
      }
    };
    reader.readAsBinaryString(file);
  }, [resetAnalyzerState]);

  const handleSheetChange = (sheetName: string) => {
    if (workbook) {
      setSelectedSheet(sheetName);
      generatePreviewData(workbook.Sheets[sheetName]);
    }
  };

  const handleHeaderRowChange = (newRowIndex: number) => {
    setHeaderRowIndex(newRowIndex);
  };

  const handleConfirmPreview = useCallback(() => {
    setError(null);
    if (!workbook || !selectedSheet) return;

    try {
        const worksheet = workbook.Sheets[selectedSheet];
        const dataAsArray: any[][] = XLSX.utils.sheet_to_json(worksheet, { header: 1, defval: '', blankrows: false });

        if (dataAsArray.length < headerRowIndex) {
            throw new Error(`Header row ${headerRowIndex} not found.`);
        }

        const rawHeaders: string[] = dataAsArray[headerRowIndex - 1].map(header => String(header).trim());
        const headers: string[] = [];
        const counts: Record<string, number> = {};

        for (const header of rawHeaders) {
            if (!header) { headers.push(''); continue; }
            counts[header] = (counts[header] || 0) + 1;
            headers.push(counts[header] > 1 ? `${header} (${counts[header]})` : header);
        }

        const jsonData = dataAsArray.slice(headerRowIndex).map(row => {
            const rowObject: SeafoodInputItem = {};
            headers.forEach((header, index) => {
                if(header) rowObject[header] = row[index];
            });
            return rowObject;
        }).filter(obj => Object.keys(obj).length > 0);

        setOriginalData(jsonData);
        setOriginalHeaders(headers.filter(h => h));
        setAnalyzerState('mapping');

    } catch(err: any) {
        setError(`Error processing sheet: ${err.message}`);
    }
  }, [workbook, selectedSheet, headerRowIndex]);

  const handleConfirmMapping = useCallback((mapping: Record<string, string>) => {
    if (!originalData) return;
    setColumnMapping(mapping);
    const report = performDataAudit(originalData, mapping);
    setAuditReport(report);
    setAnalyzerState('audit');
  }, [originalData]);

  const handleStartAnalysis = useCallback(async () => {
    if (!originalData) return;
    setAnalyzerState('loading');
    setError(null);
    analysisAbortController.current = new AbortController();

    try {
        const commonNameHeader = columnMapping['Common name'];
        let dataToProcess = originalData;
        if (commonNameHeader && commonNameHeader !== 'N/A') {
            dataToProcess = originalData.filter(row => {
                const val = row[commonNameHeader];
                return val !== undefined && val !== null && String(val).trim() !== '';
            });
        }

        setProgress({ processed: 0, total: dataToProcess.length });

        const transformedData = dataToProcess.map(row => {
            const newRow: { [key: string]: string | number } = {};
            for (const mappableField of MAPPABLE_FIELDS) {
                const userColumnName = columnMapping[mappableField];
                if (userColumnName && userColumnName !== 'N/A' && row[userColumnName] !== undefined) {
                    newRow[mappableField] = row[userColumnName];
                }
            }
            return newRow;
        });

        const analysisResults = await rateSeafoodData(transformedData, (p, t) => setProgress({ processed: p, total: t }), analysisAbortController.current.signal);

        const finalResults: SeafoodResultItem[] = dataToProcess.map((originalItem, index) => {
            const analysisPart = analysisResults[index];
            return {
                ...originalItem,
                uniqueId: analysisPart.uniqueId,
                matchedKDEs: analysisPart.matchedKDEs, 
                rating: analysisPart.rating,
                reliabilityScore: analysisPart.reliabilityScore,
                notes: analysisPart.notes,
            };
        });

        setResults(finalResults);
        setDisplayResults(finalResults);
        setDisplayHeaders(originalHeaders);

        const mappedHeaders = Object.values(columnMapping).filter(h => h && h !== 'N/A') as string[];
        setVisibleColumns(new Set([...mappedHeaders, 'uniqueId', 'rating', 'reliabilityScore']));

        // Persistence logic
        const matchedCount = finalResults.filter(r => r.rating !== Rating.NA).length;
        const matchPercentage = finalResults.length > 0 ? (matchedCount / finalResults.length) * 100 : 0;
        const totalReliability = finalResults.reduce((acc, r) => acc + r.reliabilityScore, 0);
        const averageReliability = finalResults.length > 0 ? totalReliability / finalResults.length : 0;
        const ratingDistribution = finalResults.reduce<{[key in Rating]?: number}>((acc, item) => {
            acc[item.rating] = (acc[item.rating] || 0) + 1;
            return acc;
        }, {});

        const uploadSummaryData: Omit<UploadSummary, 'id' | 'uploadDate'> = {
            fileName: currentFileName, 
            rowCount: finalResults.length, 
            matchPercentage,
            averageReliability, 
            ratingDistribution, 
            commonIssues: [],
            fullResults: finalResults,
            columnMapping: columnMapping,
            originalHeaders: originalHeaders
        };

        setUploadHistory(saveUploadToHistory(uploadSummaryData));
        setAnalyzerState('results');
    } catch (err: any) {
        if (err.name === 'AbortError') return;
        setError(`Analysis error: ${err.message}`);
        setAnalyzerState('audit'); 
    }
  }, [originalData, currentFileName, originalHeaders, columnMapping]);

  const handleCancelAnalysis = useCallback(() => {
    if (analysisAbortController.current) analysisAbortController.current.abort();
    setAnalyzerState('audit');
    setError(null);
  }, []);

  const handleViewHistoricalResults = (summary: UploadSummary) => {
    if (summary.fullResults && summary.columnMapping && summary.originalHeaders) {
      setResults(summary.fullResults);
      setDisplayResults(summary.fullResults);
      setDisplayHeaders(summary.originalHeaders);
      setColumnMapping(summary.columnMapping);
      setCurrentFileName(summary.fileName);

      const mappedHeaders = Object.values(summary.columnMapping).filter(h => h && h !== 'N/A') as string[];
      setVisibleColumns(new Set([...mappedHeaders, 'uniqueId', 'rating', 'reliabilityScore']));

      setView('analyzer');
      setAnalyzerState('results');
      setResultsViewMode('table');
    } else {
      setError("Historical data not found.");
    }
  };

  const handleUpdateResult = useCallback(async (index: number, newUniqueId: string) => {
     if (!results || !results[index]) return;
     const updatedResults = [...results];
     updatedResults[index] = { ...updatedResults[index], isUpdating: true, uniqueId: newUniqueId };
     setResults(updatedResults);
     setDisplayResults(updatedResults);

     try {
         const originalItem = updatedResults[index];
         const updatedAnalysis = await updateAnalysisForId(originalItem, newUniqueId);
         const finalResults = [...results];
         finalResults[index] = { ...originalItem, ...updatedAnalysis, isUpdating: false };
         setResults(finalResults);
         setDisplayResults(finalResults);
     } catch (err) {
         setError("Failed to update record.");
     }
  }, [results]);

  const handleExport = useCallback(() => {
    if (!results || originalHeaders.length === 0) return;
    const headers = [...originalHeaders, 'Unique ID', 'Matched KDEs', 'Rating', 'Reliability Score', 'Notes'];
    const csvContent = [
        headers.join(','),
        ...results.map(row => {
            const originalValues = originalHeaders.map(h => `"${String(row[h] || '').replace(/"/g, '""')}"`);
            const analysisValues = [row.uniqueId, row.matchedKDEs, row.rating, row.reliabilityScore, row.notes]
              .map(v => `"${String(v || '').replace(/"/g, '""')}"`);
            return [...originalValues, ...analysisValues].join(',');
        })
    ].join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.setAttribute('download', `${currentFileName.replace(/\.[^/.]+$/, "")}_analyzed.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  }, [results, originalHeaders, currentFileName]);

  if (!currentUser) return <Login onLogin={handleLogin} />;

  const renderContent = () => {
    if (view === 'users' && currentUser.role === 'admin') return <UserManagement />;

    if (view === 'dashboard') {
      return (
          <div className="animate-fade-in-up">
              <Dashboard 
                history={uploadHistory} 
                onAnalyzeNew={() => { resetAnalyzerState(); setView('analyzer'); }} 
                onViewResults={handleViewHistoricalResults}
                userRole={currentUser.role}
              />
          </div>
      );
    }

    return (
      <div className="animate-fade-in-up">
        {error && (
            <div className="bg-red-100 border border-red-400 text-red-700 px-4 py-3 rounded-lg relative my-6 max-w-4xl mx-auto">
              <strong>Error:</strong><span className="ml-2">{error}</span>
            </div>
        )}
        {analyzerState === 'upload' && <FileUpload onProcessFile={handleProcessFile} isLoading={false} />}
        {analyzerState === 'preview' && <DataPreview isAnalyzing={isPreviewLoading} sheetNames={sheetNames} selectedSheet={selectedSheet} onSheetChange={handleSheetChange} headerRowIndex={headerRowIndex} onHeaderRowChange={handleHeaderRowChange} previewData={previewData} onConfirm={handleConfirmPreview} onCancel={resetAnalyzerState} warning={previewWarning}/>}
        {analyzerState === 'mapping' && originalHeaders.length > 0 && <ColumnMapper fileHeaders={originalHeaders} mappableFields={MAPPABLE_FIELDS} onConfirm={handleConfirmMapping} onCancel={() => setAnalyzerState('preview')}/>}
        {analyzerState === 'audit' && auditReport && <DataQualityAudit report={auditReport} onConfirm={handleStartAnalysis} onBack={() => setAnalyzerState('mapping')} />}
        {analyzerState === 'loading' && <Loader progress={progress} onCancel={handleCancelAnalysis} />}
        {analyzerState === 'results' && results && displayResults && (
          <div className="flex flex-col items-center space-y-6">
            <div className="flex justify-center p-1 bg-gray-200 rounded-lg">
              <button onClick={() => setResultsViewMode('table')} className={`px-4 py-2 text-sm font-semibold rounded-md ${resultsViewMode === 'table' ? 'bg-white shadow text-gray-800' : 'text-gray-600'}`}>Table</button>
              <button onClick={() => setResultsViewMode('charts')} className={`px-4 py-2 text-sm font-semibold rounded-md ${resultsViewMode === 'charts' ? 'bg-white shadow text-gray-800' : 'text-gray-600'}`}>Charts</button>
            </div>
            <div className="w-full max-w-7xl">
              {resultsViewMode === 'table' ? (
                <ResultsTable 
                    results={activeFilter ? activeFilter.data : displayResults} 
                    originalHeaders={displayHeaders} 
                    columnMapping={columnMapping}
                    onExport={handleExport}
                    filterTitle={activeFilter?.title}
                    onClearFilter={() => setActiveFilter(null)}
                    visibleColumns={visibleColumns}
                    onVisibleColumnsChange={setVisibleColumns}
                    onUpdateResult={handleUpdateResult}
                />
              ) : (
                <ChartsView results={results} columnMapping={columnMapping} onSegmentClick={(t, d) => { setModalFilterData({title: t, data: d}); setIsFilterModalOpen(true); }} />
              )}
            </div>
            <button onClick={() => setView('dashboard')} className="px-6 py-2 font-semibold text-white bg-[#00629B] rounded-md hover:bg-[#00497b]">Back to Dashboard</button>
          </div>
        )}
         <Modal isOpen={isFilterModalOpen} onClose={() => setIsFilterModalOpen(false)} onConfirm={() => { if(modalFilterData) setActiveFilter(modalFilterData); setResultsViewMode('table'); setIsFilterModalOpen(false); }} title="View Filtered Data">
            <p>Would you like to see the {modalFilterData?.data.length} items for "{modalFilterData?.title}" in the data table?</p>
         </Modal>
      </div>
    );
  };

  return (
    <div className="min-h-screen bg-gray-50 text-gray-800 font-sans">
      <nav className="bg-[#00629B] text-white shadow-lg sticky top-0 z-50">
