import { UploadSummary } from '../types';

const HISTORY_KEY = 'seafoodWatchUploadHistory';
const MAX_HISTORY_ITEMS = 10;

export function getUploadHistory(): UploadSummary[] {
  try {
    const historyJson = localStorage.getItem(HISTORY_KEY);
    if (!historyJson) return [];
    const history = JSON.parse(historyJson);
    return Array.isArray(history) ? history : [];
  } catch (error) {
    console.error('Failed to parse history', error);
    return [];
  }
}

export function saveUploadToHistory(newSummary: Omit<UploadSummary, 'id' | 'uploadDate'>): UploadSummary[] {
  const history = getUploadHistory();

  const summaryWithMetadata: UploadSummary = {
    ...newSummary,
    id: Date.now().toString() + Math.random().toString(36).substr(2, 5),
    uploadDate: new Date().toISOString(),
  };

  const updatedHistory = [summaryWithMetadata, ...history].slice(0, MAX_HISTORY_ITEMS);

  try {
    localStorage.setItem(HISTORY_KEY, JSON.stringify(updatedHistory));
  } catch (error) {
    // If we exceed quota (too much data), try saving without full results as fallback
    console.error('LocalStorage quota exceeded, item not saved with full results.');
  }

  return updatedHistory;
}

