    const added = addUser({
      username: newUsername,
      email: newEmail,
      company: newCompany,
      role: newRole,
      password: newPassword
    });
    setUsers([...users, added]);
    setNewUsername('');
    setNewEmail('');
    setNewCompany('');
    setNewPassword('');
