        setHeaderRowIndex(bestHeaderRow);
        generatePreviewData(wb.Sheets[bestSheetName]);

      } catch (err: any) {
        setError(`Error processing file: ${err.message}`);
        setAnalyzerState('upload');
      } finally {
        setIsPreviewLoading(false);
      }
    };
    reader.readAsBinaryString(file);
  }, [resetAnalyzerState]);

  const handleSheetChange = (sheetName: string) => {
    if (workbook) {
      setSelectedSheet(sheetName);
      generatePreviewData(workbook.Sheets[sheetName]);
    }
  };

  const handleHeaderRowChange = (newRowIndex: number) => {
    setHeaderRowIndex(newRowIndex);
  };

  const handleConfirmPreview = useCallback(() => {
    setError(null);
    if (!workbook || !selectedSheet) return;

    try {
        const worksheet = workbook.Sheets[selectedSheet];
        const dataAsArray: any[][] = XLSX.utils.sheet_to_json(worksheet, { header: 1, defval: '', blankrows: false });

        if (dataAsArray.length < headerRowIndex) {
            throw new Error(`Header row ${headerRowIndex} not found.`);
        }

        const rawHeaders: string[] = dataAsArray[headerRowIndex - 1].map(header => String(header).trim());
        const headers: string[] = [];
        const counts: Record<string, number> = {};

        for (const header of rawHeaders) {
            if (!header) { headers.push(''); continue; }
            counts[header] = (counts[header] || 0) + 1;
            headers.push(counts[header] > 1 ? `${header} (${counts[header]})` : header);
        }

        const jsonData = dataAsArray.slice(headerRowIndex).map(row => {
            const rowObject: SeafoodInputItem = {};
            headers.forEach((header, index) => {
                if(header) rowObject[header] = row[index];
            });
            return rowObject;
        }).filter(obj => Object.keys(obj).length > 0);

        setOriginalData(jsonData);
        setOriginalHeaders(headers.filter(h => h));
        setAnalyzerState('mapping');

    } catch(err: any) {
        setError(`Error processing sheet: ${err.message}`);
    }
  }, [workbook, selectedSheet, headerRowIndex]);

  const handleConfirmMapping = useCallback((mapping: Record<string, string>) => {
    if (!originalData) return;
    setColumnMapping(mapping);
    const report = performDataAudit(originalData, mapping);
    setAuditReport(report);
    setAnalyzerState('audit');
  }, [originalData]);

  const handleStartAnalysis = useCallback(async () => {
    if (!originalData) return;
    setAnalyzerState('loading');
    setError(null);
    analysisAbortController.current = new AbortController();

    try {
        const commonNameHeader = columnMapping['Common name'];
        let dataToProcess = originalData;
        if (commonNameHeader && commonNameHeader !== 'N/A') {
            dataToProcess = originalData.filter(row => {
                const val = row[commonNameHeader];
                return val !== undefined && val !== null && String(val).trim() !== '';
            });
        }

        setProgress({ processed: 0, total: dataToProcess.length });

        const transformedData = dataToProcess.map(row => {
            const newRow: { [key: string]: string | number } = {};
            for (const mappableField of MAPPABLE_FIELDS) {
                const userColumnName = columnMapping[mappableField];
                if (userColumnName && userColumnName !== 'N/A' && row[userColumnName] !== undefined) {
                    newRow[mappableField] = row[userColumnName];
                }
            }
            return newRow;
        });

        const analysisResults = await rateSeafoodData(transformedData, (p, t) => setProgress({ processed: p, total: t }), analysisAbortController.current.signal);

        const finalResults: SeafoodResultItem[] = dataToProcess.map((originalItem, index) => {
            const analysisPart = analysisResults[index];
            return {
                ...originalItem,
                uniqueId: analysisPart.uniqueId,
                matchedKDEs: analysisPart.matchedKDEs, 
                rating: analysisPart.rating,
                reliabilityScore: analysisPart.reliabilityScore,
                notes: analysisPart.notes,
            };
        });

        setResults(finalResults);
        setDisplayResults(finalResults);
        setDisplayHeaders(originalHeaders);

        const mappedHeaders = Object.values(columnMapping).filter(h => h && h !== 'N/A') as string[];
        setVisibleColumns(new Set([...mappedHeaders, 'uniqueId', 'rating', 'reliabilityScore']));

        // Persistence logic
        const matchedCount = finalResults.filter(r => r.rating !== Rating.NA).length;
        const matchPercentage = finalResults.length > 0 ? (matchedCount / finalResults.length) * 100 : 0;
        const totalReliability = finalResults.reduce((acc, r) => acc + r.reliabilityScore, 0);
        const averageReliability = finalResults.length > 0 ? totalReliability / finalResults.length : 0;
        const ratingDistribution = finalResults.reduce<{[key in Rating]?: number}>((acc, item) => {
            acc[item.rating] = (acc[item.rating] || 0) + 1;
            return acc;
        }, {});

        const uploadSummaryData: Omit<UploadSummary, 'id' | 'uploadDate'> = {
            fileName: currentFileName, 
            rowCount: finalResults.length, 
            matchPercentage,
            averageReliability, 
            ratingDistribution, 
            commonIssues: [],
            fullResults: finalResults,
            columnMapping: columnMapping,
            originalHeaders: originalHeaders
        };

        setUploadHistory(saveUploadToHistory(uploadSummaryData));
        setAnalyzerState('results');
    } catch (err: any) {
        if (err.name === 'AbortError') return;
        setError(`Analysis error: ${err.message}`);
        setAnalyzerState('audit'); 
    }
  }, [originalData, currentFileName, originalHeaders, columnMapping]);

  const handleCancelAnalysis = useCallback(() => {
    if (analysisAbortController.current) analysisAbortController.current.abort();
    setAnalyzerState('audit');
    setError(null);
  }, []);

  const handleViewHistoricalResults = (summary: UploadSummary) => {
    if (summary.fullResults && summary.columnMapping && summary.originalHeaders) {
      setResults(summary.fullResults);
      setDisplayResults(summary.fullResults);
      setDisplayHeaders(summary.originalHeaders);
      setColumnMapping(summary.columnMapping);
      setCurrentFileName(summary.fileName);

      const mappedHeaders = Object.values(summary.columnMapping).filter(h => h && h !== 'N/A') as string[];
      setVisibleColumns(new Set([...mappedHeaders, 'uniqueId', 'rating', 'reliabilityScore']));

      setView('analyzer');
      setAnalyzerState('results');
      setResultsViewMode('table');
    } else {
      setError("Historical data not found.");
    }
  };

  const handleUpdateResult = useCallback(async (index: number, newUniqueId: string) => {
     if (!results || !results[index]) return;
     const updatedResults = [...results];
     updatedResults[index] = { ...updatedResults[index], isUpdating: true, uniqueId: newUniqueId };
     setResults(updatedResults);
     setDisplayResults(updatedResults);

     try {
         const originalItem = updatedResults[index];
         const updatedAnalysis = await updateAnalysisForId(originalItem, newUniqueId);
         const finalResults = [...results];
         finalResults[index] = { ...originalItem, ...updatedAnalysis, isUpdating: false };
         setResults(finalResults);
         setDisplayResults(finalResults);
     } catch (err) {
         setError("Failed to update record.");
     }
  }, [results]);

  const handleExport = useCallback(() => {
    if (!results || originalHeaders.length === 0) return;
    const headers = [...originalHeaders, 'Unique ID', 'Matched KDEs', 'Rating', 'Reliability Score', 'Notes'];
    const csvContent = [
        headers.join(','),
        ...results.map(row => {
            const originalValues = originalHeaders.map(h => `"${String(row[h] || '').replace(/"/g, '""')}"`);
            const analysisValues = [row.uniqueId, row.matchedKDEs, row.rating, row.reliabilityScore, row.notes]
              .map(v => `"${String(v || '').replace(/"/g, '""')}"`);
            return [...originalValues, ...analysisValues].join(',');
        })
    ].join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.setAttribute('download', `${currentFileName.replace(/\.[^/.]+$/, "")}_analyzed.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  }, [results, originalHeaders, currentFileName]);

  if (!currentUser) return <Login onLogin={handleLogin} />;

  const renderContent = () => {
    if (view === 'users' && currentUser.role === 'admin') return <UserManagement />;

    if (view === 'dashboard' || (view === 'analyzer' && analyzerState === 'results')) {
      // If we're in analyzer-results, the ResultsTable handles the back button to dash
      if (view === 'dashboard') {
        return (
            <div className="animate-fade-in-up">
                <Dashboard 
                  history={uploadHistory} 
                  onAnalyzeNew={() => { resetAnalyzerState(); setView('analyzer'); }} 
                  onViewResults={handleViewHistoricalResults}
                  userRole={currentUser.role}
                />
            </div>
        );
      }
    }

    return (
      <div className="animate-fade-in-up">
        {error && (
            <div className="bg-red-100 border border-red-400 text-red-700 px-4 py-3 rounded-lg relative my-6 max-w-4xl mx-auto">
              <strong>Error:</strong><span className="ml-2">{error}</span>
            </div>
        )}
        {analyzerState === 'upload' && <FileUpload onProcessFile={handleProcessFile} isLoading={false} />}
        {analyzerState === 'preview' && <DataPreview isAnalyzing={isPreviewLoading} sheetNames={sheetNames} selectedSheet={selectedSheet} onSheetChange={handleSheetChange} headerRowIndex={headerRowIndex} onHeaderRowChange={handleHeaderRowChange} previewData={previewData} onConfirm={handleConfirmPreview} onCancel={resetAnalyzerState} warning={previewWarning}/>}
        {analyzerState === 'mapping' && originalHeaders.length > 0 && <ColumnMapper fileHeaders={originalHeaders} mappableFields={MAPPABLE_FIELDS} onConfirm={handleConfirmMapping} onCancel={() => setAnalyzerState('preview')}/>}
        {analyzerState === 'audit' && auditReport && <DataQualityAudit report={auditReport} onConfirm={handleStartAnalysis} onBack={() => setAnalyzerState('mapping')} />}
        {analyzerState === 'loading' && <Loader progress={progress} onCancel={handleCancelAnalysis} />}
        {analyzerState === 'results' && results && displayResults && (
          <div className="flex flex-col items-center space-y-6">
            <div className="flex justify-center p-1 bg-gray-200 rounded-lg">
              <button onClick={() => setResultsViewMode('table')} className={`px-4 py-2 text-sm font-semibold rounded-md ${resultsViewMode === 'table' ? 'bg-white shadow text-gray-800' : 'text-gray-600'}`}>Table</button>
              <button onClick={() => setResultsViewMode('charts')} className={`px-4 py-2 text-sm font-semibold rounded-md ${resultsViewMode === 'charts' ? 'bg-white shadow text-gray-800' : 'text-gray-600'}`}>Charts</button>
            </div>
            <div className="w-full max-w-7xl">
              {resultsViewMode === 'table' ? (
                <ResultsTable 
                    results={activeFilter ? activeFilter.data : displayResults} 
                    originalHeaders={displayHeaders} 
                    columnMapping={columnMapping}
                    onExport={handleExport}
                    filterTitle={activeFilter?.title}
                    onClearFilter={() => setActiveFilter(null)}
                    visibleColumns={visibleColumns}
                    onVisibleColumnsChange={setVisibleColumns}
                    onUpdateResult={handleUpdateResult}
                />
              ) : (
                <ChartsView results={results} columnMapping={columnMapping} onSegmentClick={(t, d) => { setModalFilterData({title: t, data: d}); setIsFilterModalOpen(true); }} />
              )}
            </div>
            <button onClick={() => setView('dashboard')} className="px-6 py-2 font-semibold text-white bg-[#00629B] rounded-md hover:bg-[#00497b]">Back to Dashboard</button>
          </div>
        )}
         <Modal isOpen={isFilterModalOpen} onClose={() => setIsFilterModalOpen(false)} onConfirm={() => { if(modalFilterData) setActiveFilter(modalFilterData); setResultsViewMode('table'); setIsFilterModalOpen(false); }} title="View Filtered Data">
            <p>Would you like to see the {modalFilterData?.data.length} items for "{modalFilterData?.title}" in the data table?</p>
         </Modal>
      </div>
    );
  };

  return (
    <div className="min-h-screen bg-white text-gray-800 font-sans flex flex-col">
      {/* Top Branding Bar */}
      <nav className="bg-[#00629B] text-white shadow-sm z-50">
        <div className="container mx-auto px-6 py-2 flex justify-between items-center">
          <Logo />
          <div className="flex items-center gap-6">
            <div className="text-right hidden sm:flex flex-col items-end">
              <span className="text-xs font-bold opacity-80 uppercase tracking-widest">{currentUser.role}</span>
              <span className="text-sm font-medium">{currentUser.username}</span>
            </div>
            <div className="h-8 w-px bg-white/20 hidden sm:block"></div>
            <button 
              onClick={handleLogout} 
              className="text-xs font-bold bg-white/10 hover:bg-white/20 px-3 py-1.5 rounded transition-all flex items-center gap-2 border border-white/30"
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" />
              </svg>
              Logout
            </button>
          </div>
        </div>
      </nav>

      {/* Tab Navigation Bar */}
      <div className="bg-white border-b border-gray-200 sticky top-0 z-40 shadow-sm">
        <div className="container mx-auto px-6">
          <div className="flex items-center space-x-8">
            <button 
              onClick={() => { setView('dashboard'); resetAnalyzerState(); }}
              className={`py-4 text-sm font-bold border-b-2 transition-all duration-200 flex items-center gap-2 ${view === 'dashboard' || (view === 'analyzer' && analyzerState === 'results') ? 'border-[#00629B] text-[#00629B]' : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'}`}
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2H6a2 2 0 01-2-2V6zM14 6a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2h-2a2 2 0 01-2-2V6zM4 16a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2H6a2 2 0 01-2-2v-2zM14 16a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2h-2a2 2 0 01-2-2v-2z" />
              </svg>
              Results Dashboard
            </button>

            <button 
              onClick={() => { setView('analyzer'); resetAnalyzerState(); }}
              className={`py-4 text-sm font-bold border-b-2 transition-all duration-200 flex items-center gap-2 ${view === 'analyzer' && analyzerState !== 'results' ? 'border-[#00629B] text-[#00629B]' : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'}`}
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 13h6m-3-3v6m5 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
              </svg>
              New Analysis
            </button>

            {currentUser.role === 'admin' && (
              <button 
                onClick={() => setView('users')}
                className={`py-4 text-sm font-bold border-b-2 transition-all duration-200 flex items-center gap-2 ${view === 'users' ? 'border-[#00629B] text-[#00629B]' : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'}`}
              >
                <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4.354a4 4 0 110 5.292M15 21H3v-1a6 6 0 0112 0v1zm0 0h6v-1a6 6 0 00-9-5.197M13 7a4 4 0 11-8 0 4 4 0 018 0z" />
                </svg>
                Manage Users
              </button>
            )}
          </div>
        </div>
      </div>

      <Header />

      <main className="container mx-auto p-4 sm:p-6 md:p-8 flex-grow bg-gray-50/30">
        {renderContent()}
      </main>

      <footer className="text-center py-6 text-gray-400 text-xs border-t bg-white">
        <p>&copy; {new Date().getFullYear()} Monterey Bay Aquarium Seafood Watch Program • Partner Portal</p>
        <p className="mt-1 opacity-60 italic">AI-Powered Sourcing Intelligence</p>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useCallback, useEffect, useRef } from 'react';
import { SeafoodInputItem, SeafoodResultItem, Rating, UploadSummary, User } from './types';
import { rateSeafoodData, analyzeSheetLayout, updateAnalysisForId } from './services/geminiService';
import { loadDatabaseFromUrl } from './services/referenceDatabase';
import { getUploadHistory, saveUploadToHistory } from './services/historyService';
import { performDataAudit, AuditReport } from './services/dataAuditService';
import { getCurrentUser, logout } from './services/authService';
import FileUpload from './components/FileUpload';
import ResultsTable from './components/ResultsTable';
import Loader from './components/Loader';
import Dashboard from './components/Dashboard';
import ColumnMapper from './components/ColumnMapper';
import DataPreview from './components/DataPreview';
import ChartsView from './components/ChartsView';
import Modal from './components/Modal';
import DataQualityAudit from './components/DataQualityAudit';
import Login from './components/Login';
import UserManagement from './components/UserManagement';
import Logo from './components/Logo';

// This declaration is necessary because the library is loaded from a script tag in index.html
declare var XLSX: any;

type View = 'dashboard' | 'analyzer' | 'users';
type AnalyzerState = 'upload' | 'preview' | 'mapping' | 'audit' | 'loading' | 'results';
type ResultsViewMode = 'table' | 'charts';

const MAPPABLE_FIELDS = [
  'Wild or Farmed',
  'Common name',
  'Scientific name',
  'Source country',
  'Body of water',
  'Production Method',
  'Certification',
  'Supplier',
  'Product Name',
  'Volume',
];

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [view, setView] = useState<View>('dashboard');
  const [analyzerState, setAnalyzerState] = useState<AnalyzerState>('upload');
  const [results, setResults] = useState<SeafoodResultItem[] | null>(null);
  const [error, setError] = useState<string | null>(null);

  // State for raw data and headers
  const [originalData, setOriginalData] = useState<SeafoodInputItem[] | null>(null);
  const [originalHeaders, setOriginalHeaders] = useState<string[]>([]);
  const [currentFileName, setCurrentFileName] = useState<string>('');

  // State for column mapping and display-optimized results
  const [columnMapping, setColumnMapping] = useState<Record<string, string>>({});
  const [displayResults, setDisplayResults] = useState<any[] | null>(null);
  const [displayHeaders, setDisplayHeaders] = useState<string[]>([]);
  const [visibleColumns, setVisibleColumns] = useState<Set<string>>(new Set());
  const [auditReport, setAuditReport] = useState<AuditReport | null>(null);

  // State for preview step
  const [workbook, setWorkbook] = useState<any>(null); // XLSX workbook object
  const [sheetNames, setSheetNames] = useState<string[]>([]);
  const [selectedSheet, setSelectedSheet] = useState<string>('');
  const [headerRowIndex, setHeaderRowIndex] = useState<number>(1);
  const [previewData, setPreviewData] = useState<(string|number)[][]>([]);
  const [isPreviewLoading, setIsPreviewLoading] = useState<boolean>(false);
  const [previewWarning, setPreviewWarning] = useState<string | null>(null);

  const [uploadHistory, setUploadHistory] = useState<UploadSummary[]>([]);
  const [progress, setProgress] = useState<{ processed: number; total: number } | null>(null);

  // State for results view
  const [resultsViewMode, setResultsViewMode] = useState<ResultsViewMode>('table');
  const [activeFilter, setActiveFilter] = useState<{title: string; data: any[]} | null>(null);
  const [isFilterModalOpen, setIsFilterModalOpen] = useState(false);
  const [modalFilterData, setModalFilterData] = useState<{title: string; data: SeafoodResultItem[]} | null>(null);

  const analysisAbortController = useRef<AbortController | null>(null);

  useEffect(() => {
    const user = getCurrentUser();
    if (user) {
      setCurrentUser(user);
      // Admin: default to Dashboard. User: default to Analyzer (Upload view).
      setView(user.role === 'admin' ? 'dashboard' : 'analyzer');
    }

    setUploadHistory(getUploadHistory());
    loadDatabaseFromUrl('seafood-watch-data.csv');
  }, []);

  const handleLogin = (user: User) => {
    setCurrentUser(user);
    // Role based landing page
    setView(user.role === 'admin' ? 'dashboard' : 'analyzer');
  };

  const handleLogout = () => {
    logout();
    setCurrentUser(null);
    resetAnalyzerState();
  };

  const resetAnalyzerState = useCallback(() => {
    setResults(null);
    setDisplayResults(null);
    setDisplayHeaders([]);
    setError(null);
    setOriginalData(null);
    setOriginalHeaders([]);
    setCurrentFileName('');
    setProgress(null);
    setWorkbook(null);
    setSheetNames([]);
    setSelectedSheet('');
    setHeaderRowIndex(1);
    setPreviewData([]);
    setColumnMapping({});
    setAuditReport(null);
    setVisibleColumns(new Set());
    setResultsViewMode('table');
    setActiveFilter(null);
    setIsFilterModalOpen(false);
    setModalFilterData(null);
    setAnalyzerState('upload');
    setIsPreviewLoading(false);
    setPreviewWarning(null);
    analysisAbortController.current = null;
  }, []);

  const generatePreviewData = (worksheet: any) => {
    const previewJson: (string|number)[][] = XLSX.utils.sheet_to_json(worksheet, { header: 1, defval: '', raw: false, blankrows: false });
    setPreviewData(previewJson.slice(0, 15)); // Preview first 15 rows
  };

  const handleProcessFile = useCallback(async (file: File) => {
    resetAnalyzerState();
    setAnalyzerState('preview');
    setIsPreviewLoading(true);

    const reader = new FileReader();
    reader.onload = async (e) => {
      try {
        const data = e.target?.result;
        if (!data) throw new Error("File data could not be read.");

        let wb: any;
        try {
          wb = XLSX.read(data, { type: 'binary', cellNF: false, cellText: false });
        } catch (parseError) {
          console.error("File parsing error:", parseError);
          throw new Error("Could not parse file. Please ensure it is a valid XLSX or CSV file.");
        }

        const names = wb.SheetNames;
        if (names.length === 0) throw new Error("The file contains no sheets.");

        setWorkbook(wb);
        setSheetNames(names);
        setCurrentFileName(file.name);

        let bestSheetName = names[0];
        let bestHeaderRow = 1;

        try {
          const sheetPreviews = names.map(name => {
            const ws = wb.Sheets[name];
            const sheetData = XLSX.utils.sheet_to_json(ws, { header: 1, defval: '', raw: false, blankrows: false }).slice(0, 15);
            return { sheetName: name, data: sheetData };
          });
          const layout = await analyzeSheetLayout(sheetPreviews);
          bestSheetName = layout.bestSheetName;
          bestHeaderRow = layout.bestHeaderRow;
        } catch (aiError) {
          setPreviewWarning("AI auto-layout failed. Manual selection required.");
        }

        setSelectedSheet(bestSheetName);
        setHeaderRowIndex(bestHeaderRow);
        generatePreviewData(wb.Sheets[bestSheetName]);

      } catch (err: any) {
        setError(`Error processing file: ${err.message}`);
        setAnalyzerState('upload');
      } finally {
        setIsPreviewLoading(false);
      }
    };
    reader.readAsBinaryString(file);
  }, [resetAnalyzerState]);

  const handleSheetChange = (sheetName: string) => {
    if (workbook) {
      setSelectedSheet(sheetName);
      generatePreviewData(workbook.Sheets[sheetName]);
    }
  };

  const handleHeaderRowChange = (newRowIndex: number) => {
    setHeaderRowIndex(newRowIndex);
  };

  const handleConfirmPreview = useCallback(() => {
    setError(null);
    if (!workbook || !selectedSheet) return;

    try {
        const worksheet = workbook.Sheets[selectedSheet];
        const dataAsArray: any[][] = XLSX.utils.sheet_to_json(worksheet, { header: 1, defval: '', blankrows: false });

        if (dataAsArray.length < headerRowIndex) {
            throw new Error(`Header row ${headerRowIndex} not found.`);
        }

        const rawHeaders: string[] = dataAsArray[headerRowIndex - 1].map(header => String(header).trim());
        const headers: string[] = [];
        const counts: Record<string, number> = {};

        for (const header of rawHeaders) {
            if (!header) { headers.push(''); continue; }
            counts[header] = (counts[header] || 0) + 1;
            headers.push(counts[header] > 1 ? `${header} (${counts[header]})` : header);
        }

        const jsonData = dataAsArray.slice(headerRowIndex).map(row => {
            const rowObject: SeafoodInputItem = {};
            headers.forEach((header, index) => {
                if(header) rowObject[header] = row[index];
            });
            return rowObject;
        }).filter(obj => Object.keys(obj).length > 0);

        setOriginalData(jsonData);
        setOriginalHeaders(headers.filter(h => h));
        setAnalyzerState('mapping');

    } catch(err: any) {
        setError(`Error processing sheet: ${err.message}`);
    }
  }, [workbook, selectedSheet, headerRowIndex]);

  const handleConfirmMapping = useCallback((mapping: Record<string, string>) => {
    if (!originalData) return;
    setColumnMapping(mapping);
    const report = performDataAudit(originalData, mapping);
    setAuditReport(report);
    setAnalyzerState('audit');
  }, [originalData]);

  const handleStartAnalysis = useCallback(async () => {
    if (!originalData) return;
    setAnalyzerState('loading');
    setError(null);
    analysisAbortController.current = new AbortController();

    try {
        const commonNameHeader = columnMapping['Common name'];
        let dataToProcess = originalData;
        if (commonNameHeader && commonNameHeader !== 'N/A') {
            dataToProcess = originalData.filter(row => {
                const val = row[commonNameHeader];
                return val !== undefined && val !== null && String(val).trim() !== '';
            });
        }

        setProgress({ processed: 0, total: dataToProcess.length });

        const transformedData = dataToProcess.map(row => {
            const newRow: { [key: string]: string | number } = {};
            for (const mappableField of MAPPABLE_FIELDS) {
                const userColumnName = columnMapping[mappableField];
                if (userColumnName && userColumnName !== 'N/A' && row[userColumnName] !== undefined) {
                    newRow[mappableField] = row[userColumnName];
                }
            }
            return newRow;
        });

        const analysisResults = await rateSeafoodData(transformedData, (p, t) => setProgress({ processed: p, total: t }), analysisAbortController.current.signal);

        const finalResults: SeafoodResultItem[] = dataToProcess.map((originalItem, index) => {
            const analysisPart = analysisResults[index];
            return {
                ...originalItem,
                uniqueId: analysisPart.uniqueId,
                matchedKDEs: analysisPart.matchedKDEs, 
                rating: analysisPart.rating,
                reliabilityScore: analysisPart.reliabilityScore,
                notes: analysisPart.notes,
            };
        });

        setResults(finalResults);
        setDisplayResults(finalResults);
        setDisplayHeaders(originalHeaders);

        const mappedHeaders = Object.values(columnMapping).filter(h => h && h !== 'N/A') as string[];
        setVisibleColumns(new Set([...mappedHeaders, 'uniqueId', 'rating', 'reliabilityScore']));

        // Persistence logic
        const matchedCount = finalResults.filter(r => r.rating !== Rating.NA).length;
        const matchPercentage = finalResults.length > 0 ? (matchedCount / finalResults.length) * 100 : 0;
        const totalReliability = finalResults.reduce((acc, r) => acc + r.reliabilityScore, 0);
        const averageReliability = finalResults.length > 0 ? totalReliability / finalResults.length : 0;
        const ratingDistribution = finalResults.reduce<{[key in Rating]?: number}>((acc, item) => {
            acc[item.rating] = (acc[item.rating] || 0) + 1;
            return acc;
        }, {});

        const uploadSummaryData: Omit<UploadSummary, 'id' | 'uploadDate'> = {
            fileName: currentFileName, 
            rowCount: finalResults.length, 
            matchPercentage,
            averageReliability, 
            ratingDistribution, 
            commonIssues: [],
            fullResults: finalResults,
            columnMapping: columnMapping,
            originalHeaders: originalHeaders
        };

        setUploadHistory(saveUploadToHistory(uploadSummaryData));
        setAnalyzerState('results');
    } catch (err: any) {
        if (err.name === 'AbortError') return;
        setError(`Analysis error: ${err.message}`);
        setAnalyzerState('audit'); 
    }
  }, [originalData, currentFileName, originalHeaders, columnMapping]);

  const handleCancelAnalysis = useCallback(() => {
    if (analysisAbortController.current) analysisAbortController.current.abort();
    setAnalyzerState('audit');
    setError(null);
  }, []);

  const handleViewHistoricalResults = (summary: UploadSummary) => {
    if (summary.fullResults && summary.columnMapping && summary.originalHeaders) {
      setResults(summary.fullResults);
      setDisplayResults(summary.fullResults);
      setDisplayHeaders(summary.originalHeaders);
      setColumnMapping(summary.columnMapping);
      setCurrentFileName(summary.fileName);

      const mappedHeaders = Object.values(summary.columnMapping).filter(h => h && h !== 'N/A') as string[];
      setVisibleColumns(new Set([...mappedHeaders, 'uniqueId', 'rating', 'reliabilityScore']));

      setView('analyzer');
      setAnalyzerState('results');
      setResultsViewMode('table');
    } else {
      setError("Historical data not found.");
    }
  };

  const handleUpdateResult = useCallback(async (index: number, newUniqueId: string) => {
     if (!results || !results[index]) return;
     const updatedResults = [...results];
     updatedResults[index] = { ...updatedResults[index], isUpdating: true, uniqueId: newUniqueId };
     setResults(updatedResults);
     setDisplayResults(updatedResults);

     try {
         const originalItem = updatedResults[index];
         const updatedAnalysis = await updateAnalysisForId(originalItem, newUniqueId);
         const finalResults = [...results];
         finalResults[index] = { ...originalItem, ...updatedAnalysis, isUpdating: false };
         setResults(finalResults);
         setDisplayResults(finalResults);
     } catch (err) {
         setError("Failed to update record.");
     }
  }, [results]);

  const handleExport = useCallback(() => {
    if (!results || originalHeaders.length === 0) return;
    const headers = [...originalHeaders, 'Unique ID', 'Matched KDEs', 'Rating', 'Reliability Score', 'Notes'];
    const csvContent = [
        headers.join(','),
        ...results.map(row => {
            const originalValues = originalHeaders.map(h => `"${String(row[h] || '').replace(/"/g, '""')}"`);
            const analysisValues = [row.uniqueId, row.matchedKDEs, row.rating, row.reliabilityScore, row.notes]
              .map(v => `"${String(v || '').replace(/"/g, '""')}"`);
            return [...originalValues, ...analysisValues].join(',');
        })
    ].join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.setAttribute('download', `${currentFileName.replace(/\.[^/.]+$/, "")}_analyzed.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  }, [results, originalHeaders, currentFileName]);

  if (!currentUser) return <Login onLogin={handleLogin} />;

  const renderContent = () => {
    if (view === 'users' && currentUser.role === 'admin') return <UserManagement />;

    if (view === 'dashboard' || (view === 'analyzer' && analyzerState === 'results')) {
      // If we're in analyzer-results, the ResultsTable handles the back button to dash
      if (view === 'dashboard') {
        return (
            <div className="animate-fade-in-up">
                <Dashboard 
                  history={uploadHistory} 
                  onAnalyzeNew={() => { resetAnalyzerState(); setView('analyzer'); }} 
                  onViewResults={handleViewHistoricalResults}
                  userRole={currentUser.role}
                />
            </div>
        );
      }
    }

    return (
      <div className="animate-fade-in-up">
        {error && (
            <div className="bg-red-100 border border-red-400 text-red-700 px-4 py-3 rounded-lg relative my-6 max-w-4xl mx-auto">
              <strong>Error:</strong><span className="ml-2">{error}</span>
            </div>
        )}
        {analyzerState === 'upload' && <FileUpload onProcessFile={handleProcessFile} isLoading={false} />}
        {analyzerState === 'preview' && <DataPreview isAnalyzing={isPreviewLoading} sheetNames={sheetNames} selectedSheet={selectedSheet} onSheetChange={handleSheetChange} headerRowIndex={headerRowIndex} onHeaderRowChange={handleHeaderRowChange} previewData={previewData} onConfirm={handleConfirmPreview} onCancel={resetAnalyzerState} warning={previewWarning}/>}
        {analyzerState === 'mapping' && originalHeaders.length > 0 && <ColumnMapper fileHeaders={originalHeaders} mappableFields={MAPPABLE_FIELDS} onConfirm={handleConfirmMapping} onCancel={() => setAnalyzerState('preview')}/>}
        {analyzerState === 'audit' && auditReport && <DataQualityAudit report={auditReport} onConfirm={handleStartAnalysis} onBack={() => setAnalyzerState('mapping')} />}
        {analyzerState === 'loading' && <Loader progress={progress} onCancel={handleCancelAnalysis} />}
        {analyzerState === 'results' && results && displayResults && (
          <div className="flex flex-col items-center space-y-6">
            <div className="flex justify-center p-1 bg-gray-200 rounded-lg">
              <button onClick={() => setResultsViewMode('table')} className={`px-4 py-2 text-sm font-semibold rounded-md ${resultsViewMode === 'table' ? 'bg-white shadow text-gray-800' : 'text-gray-600'}`}>Table</button>
              <button onClick={() => setResultsViewMode('charts')} className={`px-4 py-2 text-sm font-semibold rounded-md ${resultsViewMode === 'charts' ? 'bg-white shadow text-gray-800' : 'text-gray-600'}`}>Charts</button>
            </div>
            <div className="w-full max-w-7xl">
              {resultsViewMode === 'table' ? (
                <ResultsTable 
                    results={activeFilter ? activeFilter.data : displayResults} 
                    originalHeaders={displayHeaders} 
                    columnMapping={columnMapping}
                    onExport={handleExport}
                    filterTitle={activeFilter?.title}
                    onClearFilter={() => setActiveFilter(null)}
                    visibleColumns={visibleColumns}
                    onVisibleColumnsChange={setVisibleColumns}
                    onUpdateResult={handleUpdateResult}
                />
              ) : (
                <ChartsView results={results} columnMapping={columnMapping} onSegmentClick={(t, d) => { setModalFilterData({title: t, data: d}); setIsFilterModalOpen(true); }} />
              )}
            </div>
            <button onClick={() => setView('dashboard')} className="px-6 py-2 font-semibold text-white bg-[#00629B] rounded-md hover:bg-[#00497b]">Back to Dashboard</button>
          </div>
        )}
         <Modal isOpen={isFilterModalOpen} onClose={() => setIsFilterModalOpen(false)} onConfirm={() => { if(modalFilterData) setActiveFilter(modalFilterData); setResultsViewMode('table'); setIsFilterModalOpen(false); }} title="View Filtered Data">
            <p>Would you like to see the {modalFilterData?.data.length} items for "{modalFilterData?.title}" in the data table?</p>
         </Modal>
      </div>
    );
  };

  return (
    <div className="min-h-screen bg-white text-gray-800 font-sans flex flex-col">
      {/* Top Branding Bar */}
      <nav className="bg-[#00629B] text-white shadow-sm z-50">
        <div className="container mx-auto px-6 py-2 flex justify-between items-center">
          <Logo />
          <div className="flex items-center gap-6">
            <div className="text-right hidden sm:flex flex-col items-end">
              <span className="text-xs font-bold opacity-80 uppercase tracking-widest">{currentUser.role}</span>
              <span className="text-sm font-medium">{currentUser.username}</span>
            </div>
            <div className="h-8 w-px bg-white/20 hidden sm:block"></div>
            <button 
              onClick={handleLogout} 
              className="text-xs font-bold bg-white/10 hover:bg-white/20 px-3 py-1.5 rounded transition-all flex items-center gap-2 border border-white/30"
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" />
              </svg>
              Logout
            </button>
          </div>
        </div>
      </nav>

      {/* Main Title Header Section - Clean look, above tabs */}
      <div className="bg-white pt-10 pb-6 border-b border-gray-100">
        <div className="container mx-auto px-6 text-center">
          <h1 className="text-4xl font-extrabold text-[#00629B] tracking-tight leading-tight mb-2">
            Seafood Watch <br className="sm:hidden" /> Sust-AI-nability Analyzer
          </h1>
          <p className="text-gray-500 text-sm md:text-base max-w-2xl mx-auto leading-relaxed">
            Leverage AI to evaluate and visualize the eco-friendliness of your seafood products based on Seafood Watch recommendations.
          </p>
        </div>
      </div>

      {/* Tab Navigation Bar */}
      <div className="bg-white border-b border-gray-200 sticky top-0 z-40 shadow-sm">
        <div className="container mx-auto px-6">
          <div className="flex items-center space-x-8">
            <button 
              onClick={() => { setView('dashboard'); resetAnalyzerState(); }}
              className={`py-4 text-sm font-bold border-b-2 transition-all duration-200 flex items-center gap-2 ${view === 'dashboard' || (view === 'analyzer' && analyzerState === 'results') ? 'border-[#00629B] text-[#00629B]' : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'}`}
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2H6a2 2 0 01-2-2V6zM14 6a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2h-2a2 2 0 01-2-2V6zM4 16a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2H6a2 2 0 01-2-2v-2zM14 16a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2h-2a2 2 0 01-2-2v-2z" />
              </svg>
              Results Dashboard
            </button>

            <button 
              onClick={() => { setView('analyzer'); resetAnalyzerState(); }}
              className={`py-4 text-sm font-bold border-b-2 transition-all duration-200 flex items-center gap-2 ${view === 'analyzer' && analyzerState !== 'results' ? 'border-[#00629B] text-[#00629B]' : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'}`}
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 13h6m-3-3v6m5 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
              </svg>
              New Analysis
            </button>

            {currentUser.role === 'admin' && (
              <button 
                onClick={() => setView('users')}
                className={`py-4 text-sm font-bold border-b-2 transition-all duration-200 flex items-center gap-2 ${view === 'users' ? 'border-[#00629B] text-[#00629B]' : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'}`}
              >
                <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4.354a4 4 0 110 5.292M15 21H3v-1a6 6 0 0112 0v1zm0 0h6v-1a6 6 0 00-9-5.197M13 7a4 4 0 11-8 0 4 4 0 018 0z" />
                </svg>
                Manage Users
              </button>
            )}
          </div>
        </div>
      </div>

      <main className="container mx-auto p-4 sm:p-6 md:p-8 flex-grow bg-gray-50/30">
        {renderContent()}
      </main>

      <footer className="text-center py-6 text-gray-400 text-xs border-t bg-white">
        <p>&copy; {new Date().getFullYear()} Monterey Bay Aquarium Seafood Watch Program • Partner Portal</p>
        <p className="mt-1 opacity-60 italic">AI-Powered Sourcing Intelligence</p>
      </footer>
    </div>
  );
};

export default App;

// This component is no longer used independently. 
// Its content has been integrated into the main App layout to satisfy header placement requirements.
export default null;

import React, { useState, useCallback, useEffect, useRef } from 'react';
import { SeafoodInputItem, SeafoodResultItem, Rating, UploadSummary, User } from './types';
import { rateSeafoodData, analyzeSheetLayout, updateAnalysisForId } from './services/geminiService';
import { loadDatabaseFromUrl } from './services/referenceDatabase';
import { getUploadHistory, saveUploadToHistory } from './services/historyService';
import { performDataAudit, AuditReport } from './services/dataAuditService';
import { getCurrentUser, logout } from './services/authService';
import FileUpload from './components/FileUpload';
import ResultsTable from './components/ResultsTable';
import Loader from './components/Loader';
import Dashboard from './components/Dashboard';
import ColumnMapper from './components/ColumnMapper';
import DataPreview from './components/DataPreview';
import ChartsView from './components/ChartsView';
import Modal from './components/Modal';
import DataQualityAudit from './components/DataQualityAudit';
import Login from './components/Login';
import UserManagement from './components/UserManagement';
import Logo from './components/Logo';

// This declaration is necessary because the library is loaded from a script tag in index.html
declare var XLSX: any;

type View = 'dashboard' | 'analyzer' | 'users';
type AnalyzerState = 'upload' | 'preview' | 'mapping' | 'audit' | 'loading' | 'results';
type ResultsViewMode = 'table' | 'charts';

const MAPPABLE_FIELDS = [
  'Wild or Farmed',
  'Common name',
  'Scientific name',
  'Source country',
  'Body of water',
  'Production Method',
  'Certification',
  'Supplier',
  'Product Name',
  'Volume',
];

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [view, setView] = useState<View>('dashboard');
  const [analyzerState, setAnalyzerState] = useState<AnalyzerState>('upload');
  const [results, setResults] = useState<SeafoodResultItem[] | null>(null);
  const [error, setError] = useState<string | null>(null);

  // State for raw data and headers
  const [originalData, setOriginalData] = useState<SeafoodInputItem[] | null>(null);
  const [originalHeaders, setOriginalHeaders] = useState<string[]>([]);
  const [currentFileName, setCurrentFileName] = useState<string>('');

  // State for column mapping and display-optimized results
  const [columnMapping, setColumnMapping] = useState<Record<string, string>>({});
  const [displayResults, setDisplayResults] = useState<any[] | null>(null);
  const [displayHeaders, setDisplayHeaders] = useState<string[]>([]);
  const [visibleColumns, setVisibleColumns] = useState<Set<string>>(new Set());
  const [auditReport, setAuditReport] = useState<AuditReport | null>(null);

  // State for preview step
  const [workbook, setWorkbook] = useState<any>(null); // XLSX workbook object
  const [sheetNames, setSheetNames] = useState<string[]>([]);
  const [selectedSheet, setSelectedSheet] = useState<string>('');
  const [headerRowIndex, setHeaderRowIndex] = useState<number>(1);
  const [previewData, setPreviewData] = useState<(string|number)[][]>([]);
  const [isPreviewLoading, setIsPreviewLoading] = useState<boolean>(false);
  const [previewWarning, setPreviewWarning] = useState<string | null>(null);

  const [uploadHistory, setUploadHistory] = useState<UploadSummary[]>([]);
  const [progress, setProgress] = useState<{ processed: number; total: number } | null>(null);

  // State for results view
  const [resultsViewMode, setResultsViewMode] = useState<ResultsViewMode>('table');
  const [activeFilter, setActiveFilter] = useState<{title: string; data: any[]} | null>(null);
  const [isFilterModalOpen, setIsFilterModalOpen] = useState(false);
  const [modalFilterData, setModalFilterData] = useState<{title: string; data: SeafoodResultItem[]} | null>(null);

  const analysisAbortController = useRef<AbortController | null>(null);

  useEffect(() => {
    const user = getCurrentUser();
    if (user) {
      setCurrentUser(user);
      // Admin: default to Dashboard. User: default to Analyzer (Upload view).
      setView(user.role === 'admin' ? 'dashboard' : 'analyzer');
    }

    setUploadHistory(getUploadHistory());
    loadDatabaseFromUrl('seafood-watch-data.csv');
  }, []);

  const handleLogin = (user: User) => {
    setCurrentUser(user);
    // Role based landing page
    setView(user.role === 'admin' ? 'dashboard' : 'analyzer');
  };

  const handleLogout = () => {
    logout();
    setCurrentUser(null);
    resetAnalyzerState();
  };

  const resetAnalyzerState = useCallback(() => {
    setResults(null);
    setDisplayResults(null);
    setDisplayHeaders([]);
    setError(null);
    setOriginalData(null);
    setOriginalHeaders([]);
    setCurrentFileName('');
    setProgress(null);
    setWorkbook(null);
    setSheetNames([]);
    setSelectedSheet('');
    setHeaderRowIndex(1);
    setPreviewData([]);
    setColumnMapping({});
    setAuditReport(null);
    setVisibleColumns(new Set());
    setResultsViewMode('table');
    setActiveFilter(null);
    setIsFilterModalOpen(false);
    setModalFilterData(null);
    setAnalyzerState('upload');
    setIsPreviewLoading(false);
    setPreviewWarning(null);
    analysisAbortController.current = null;
  }, []);

  const generatePreviewData = (worksheet: any) => {
    const previewJson: (string|number)[][] = XLSX.utils.sheet_to_json(worksheet, { header: 1, defval: '', raw: false, blankrows: false });
    setPreviewData(previewJson.slice(0, 15)); // Preview first 15 rows
  };

  const handleProcessFile = useCallback(async (file: File) => {
    resetAnalyzerState();
    setAnalyzerState('preview');
    setIsPreviewLoading(true);

    const reader = new FileReader();
    reader.onload = async (e) => {
      try {
        const data = e.target?.result;
        if (!data) throw new Error("File data could not be read.");

        let wb: any;
        try {
          wb = XLSX.read(data, { type: 'binary', cellNF: false, cellText: false });
        } catch (parseError) {
          console.error("File parsing error:", parseError);
          throw new Error("Could not parse file. Please ensure it is a valid XLSX or CSV file.");
        }

        const names = wb.SheetNames;
        if (names.length === 0) throw new Error("The file contains no sheets.");

        setWorkbook(wb);
        setSheetNames(names);
        setCurrentFileName(file.name);

        let bestSheetName = names[0];
        let bestHeaderRow = 1;

        try {
          const sheetPreviews = names.map(name => {
            const ws = wb.Sheets[name];
            const sheetData = XLSX.utils.sheet_to_json(ws, { header: 1, defval: '', raw: false, blankrows: false }).slice(0, 15);
            return { sheetName: name, data: sheetData };
          });
          const layout = await analyzeSheetLayout(sheetPreviews);
          bestSheetName = layout.bestSheetName;
          bestHeaderRow = layout.bestHeaderRow;
        } catch (aiError) {
          setPreviewWarning("AI auto-layout failed. Manual selection required.");
        }

        setSelectedSheet(bestSheetName);
        setHeaderRowIndex(bestHeaderRow);
        generatePreviewData(wb.Sheets[bestSheetName]);

      } catch (err: any) {
        setError(`Error processing file: ${err.message}`);
        setAnalyzerState('upload');
      } finally {
        setIsPreviewLoading(false);
      }
    };
    reader.readAsBinaryString(file);
  }, [resetAnalyzerState]);

  const handleSheetChange = (sheetName: string) => {
    if (workbook) {
      setSelectedSheet(sheetName);
      generatePreviewData(workbook.Sheets[sheetName]);
    }
  };

  const handleHeaderRowChange = (newRowIndex: number) => {
    setHeaderRowIndex(newRowIndex);
  };

  const handleConfirmPreview = useCallback(() => {
    setError(null);
    if (!workbook || !selectedSheet) return;

    try {
        const worksheet = workbook.Sheets[selectedSheet];
        const dataAsArray: any[][] = XLSX.utils.sheet_to_json(worksheet, { header: 1, defval: '', blankrows: false });

        if (dataAsArray.length < headerRowIndex) {
            throw new Error(`Header row ${headerRowIndex} not found.`);
        }

        const rawHeaders: string[] = dataAsArray[headerRowIndex - 1].map(header => String(header).trim());
        const headers: string[] = [];
        const counts: Record<string, number> = {};

        for (const header of rawHeaders) {
            if (!header) { headers.push(''); continue; }
            counts[header] = (counts[header] || 0) + 1;
            headers.push(counts[header] > 1 ? `${header} (${counts[header]})` : header);
        }

        const jsonData = dataAsArray.slice(headerRowIndex).map(row => {
            const rowObject: SeafoodInputItem = {};
            headers.forEach((header, index) => {
                if(header) rowObject[header] = row[index];
            });
            return rowObject;
        }).filter(obj => Object.keys(obj).length > 0);

        setOriginalData(jsonData);
        setOriginalHeaders(headers.filter(h => h));
        setAnalyzerState('mapping');

    } catch(err: any) {
        setError(`Error processing sheet: ${err.message}`);
    }
  }, [workbook, selectedSheet, headerRowIndex]);

  const handleConfirmMapping = useCallback((mapping: Record<string, string>) => {
    if (!originalData) return;
    setColumnMapping(mapping);
    const report = performDataAudit(originalData, mapping);
    setAuditReport(report);
    setAnalyzerState('audit');
  }, [originalData]);

  const handleStartAnalysis = useCallback(async () => {
    if (!originalData) return;
    setAnalyzerState('loading');
    setError(null);
    analysisAbortController.current = new AbortController();

    try {
        const commonNameHeader = columnMapping['Common name'];
        let dataToProcess = originalData;
        if (commonNameHeader && commonNameHeader !== 'N/A') {
            dataToProcess = originalData.filter(row => {
                const val = row[commonNameHeader];
                return val !== undefined && val !== null && String(val).trim() !== '';
            });
        }

        setProgress({ processed: 0, total: dataToProcess.length });

        const transformedData = dataToProcess.map(row => {
            const newRow: { [key: string]: string | number } = {};
            for (const mappableField of MAPPABLE_FIELDS) {
                const userColumnName = columnMapping[mappableField];
                if (userColumnName && userColumnName !== 'N/A' && row[userColumnName] !== undefined) {
                    newRow[mappableField] = row[userColumnName];
                }
            }
            return newRow;
        });

        const analysisResults = await rateSeafoodData(transformedData, (p, t) => setProgress({ processed: p, total: t }), analysisAbortController.current.signal);

        const finalResults: SeafoodResultItem[] = dataToProcess.map((originalItem, index) => {
            const analysisPart = analysisResults[index];
            return {
                ...originalItem,
                uniqueId: analysisPart.uniqueId,
                matchedKDEs: analysisPart.matchedKDEs, 
                rating: analysisPart.rating,
                reliabilityScore: analysisPart.reliabilityScore,
                notes: analysisPart.notes,
            };
        });

        setResults(finalResults);
        setDisplayResults(finalResults);
        setDisplayHeaders(originalHeaders);

        const mappedHeaders = Object.values(columnMapping).filter(h => h && h !== 'N/A') as string[];
        setVisibleColumns(new Set([...mappedHeaders, 'uniqueId', 'rating', 'reliabilityScore']));

        // Persistence logic
        const matchedCount = finalResults.filter(r => r.rating !== Rating.NA).length;
        const matchPercentage = finalResults.length > 0 ? (matchedCount / finalResults.length) * 100 : 0;
        const totalReliability = finalResults.reduce((acc, r) => acc + r.reliabilityScore, 0);
        const averageReliability = finalResults.length > 0 ? totalReliability / finalResults.length : 0;
        const ratingDistribution = finalResults.reduce<{[key in Rating]?: number}>((acc, item) => {
            acc[item.rating] = (acc[item.rating] || 0) + 1;
            return acc;
        }, {});

        const uploadSummaryData: Omit<UploadSummary, 'id' | 'uploadDate'> = {
            fileName: currentFileName, 
            rowCount: finalResults.length, 
            matchPercentage,
            averageReliability, 
            ratingDistribution, 
            commonIssues: [],
            fullResults: finalResults,
            columnMapping: columnMapping,
            originalHeaders: originalHeaders
        };

        setUploadHistory(saveUploadToHistory(uploadSummaryData));
        setAnalyzerState('results');
    } catch (err: any) {
        if (err.name === 'AbortError') return;
        setError(`Analysis error: ${err.message}`);
        setAnalyzerState('audit'); 
    }
  }, [originalData, currentFileName, originalHeaders, columnMapping]);

  const handleCancelAnalysis = useCallback(() => {
    if (analysisAbortController.current) analysisAbortController.current.abort();
    setAnalyzerState('audit');
    setError(null);
  }, []);

  const handleViewHistoricalResults = (summary: UploadSummary) => {
    if (summary.fullResults && summary.columnMapping && summary.originalHeaders) {
      setResults(summary.fullResults);
      setDisplayResults(summary.fullResults);
      setDisplayHeaders(summary.originalHeaders);
      setColumnMapping(summary.columnMapping);
      setCurrentFileName(summary.fileName);

      const mappedHeaders = Object.values(summary.columnMapping).filter(h => h && h !== 'N/A') as string[];
      setVisibleColumns(new Set([...mappedHeaders, 'uniqueId', 'rating', 'reliabilityScore']));

      setView('analyzer');
      setAnalyzerState('results');
      setResultsViewMode('table');
    } else {
      setError("Historical data not found.");
    }
  };

  const handleUpdateResult = useCallback(async (index: number, newUniqueId: string) => {
     if (!results || !results[index]) return;
     const updatedResults = [...results];
     updatedResults[index] = { ...updatedResults[index], isUpdating: true, uniqueId: newUniqueId };
     setResults(updatedResults);
     setDisplayResults(updatedResults);

     try {
         const originalItem = updatedResults[index];
         const updatedAnalysis = await updateAnalysisForId(originalItem, newUniqueId);
         const finalResults = [...results];
         finalResults[index] = { ...originalItem, ...updatedAnalysis, isUpdating: false };
         setResults(finalResults);
         setDisplayResults(finalResults);
     } catch (err) {
         setError("Failed to update record.");
     }
  }, [results]);

  const handleExport = useCallback(() => {
    if (!results || originalHeaders.length === 0) return;
    const headers = [...originalHeaders, 'Unique ID', 'Matched KDEs', 'Rating', 'Reliability Score', 'Notes'];
    const csvContent = [
        headers.join(','),
        ...results.map(row => {
            const originalValues = originalHeaders.map(h => `"${String(row[h] || '').replace(/"/g, '""')}"`);
            const analysisValues = [row.uniqueId, row.matchedKDEs, row.rating, row.reliabilityScore, row.notes]
              .map(v => `"${String(v || '').replace(/"/g, '""')}"`);
            return [...originalValues, ...analysisValues].join(',');
        })
    ].join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.setAttribute('download', `${currentFileName.replace(/\.[^/.]+$/, "")}_analyzed.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  }, [results, originalHeaders, currentFileName]);

  if (!currentUser) return <Login onLogin={handleLogin} />;

  const renderContent = () => {
    if (view === 'users' && currentUser.role === 'admin') return <UserManagement />;

    if (view === 'dashboard' || (view === 'analyzer' && analyzerState === 'results')) {
      // If we're in analyzer-results, the ResultsTable handles the back button to dash
      if (view === 'dashboard') {
        return (
            <div className="animate-fade-in-up">
                <Dashboard 
                  history={uploadHistory} 
                  onAnalyzeNew={() => { resetAnalyzerState(); setView('analyzer'); }} 
                  onViewResults={handleViewHistoricalResults}
                  userRole={currentUser.role}
                />
            </div>
        );
      }
    }

    return (
      <div className="animate-fade-in-up">
        {error && (
            <div className="bg-red-100 border border-red-400 text-red-700 px-4 py-3 rounded-lg relative my-6 max-w-4xl mx-auto">
              <strong>Error:</strong><span className="ml-2">{error}</span>
            </div>
        )}
        {analyzerState === 'upload' && <FileUpload onProcessFile={handleProcessFile} isLoading={false} />}
        {analyzerState === 'preview' && <DataPreview isAnalyzing={isPreviewLoading} sheetNames={sheetNames} selectedSheet={selectedSheet} onSheetChange={handleSheetChange} headerRowIndex={headerRowIndex} onHeaderRowChange={handleHeaderRowChange} previewData={previewData} onConfirm={handleConfirmPreview} onCancel={resetAnalyzerState} warning={previewWarning}/>}
        {analyzerState === 'mapping' && originalHeaders.length > 0 && <ColumnMapper fileHeaders={originalHeaders} mappableFields={MAPPABLE_FIELDS} onConfirm={handleConfirmMapping} onCancel={() => setAnalyzerState('preview')}/>}
        {analyzerState === 'audit' && auditReport && <DataQualityAudit report={auditReport} onConfirm={handleStartAnalysis} onBack={() => setAnalyzerState('mapping')} />}
        {analyzerState === 'loading' && <Loader progress={progress} onCancel={handleCancelAnalysis} />}
        {analyzerState === 'results' && results && displayResults && (
          <div className="flex flex-col items-center space-y-6">
            <div className="flex justify-center p-1 bg-gray-200 rounded-lg">
              <button onClick={() => setResultsViewMode('table')} className={`px-4 py-2 text-sm font-semibold rounded-md ${resultsViewMode === 'table' ? 'bg-white shadow text-gray-800' : 'text-gray-600'}`}>Table</button>
              <button onClick={() => setResultsViewMode('charts')} className={`px-4 py-2 text-sm font-semibold rounded-md ${resultsViewMode === 'charts' ? 'bg-white shadow text-gray-800' : 'text-gray-600'}`}>Charts</button>
            </div>
            <div className="w-full max-w-7xl">
              {resultsViewMode === 'table' ? (
                <ResultsTable 
                    results={activeFilter ? activeFilter.data : displayResults} 
                    originalHeaders={displayHeaders} 
                    columnMapping={columnMapping}
                    onExport={handleExport}
                    filterTitle={activeFilter?.title}
                    onClearFilter={() => setActiveFilter(null)}
                    visibleColumns={visibleColumns}
                    onVisibleColumnsChange={setVisibleColumns}
                    onUpdateResult={handleUpdateResult}
                />
              ) : (
                <ChartsView results={results} columnMapping={columnMapping} onSegmentClick={(t, d) => { setModalFilterData({title: t, data: d}); setIsFilterModalOpen(true); }} />
              )}
            </div>
            <button onClick={() => setView('dashboard')} className="px-6 py-2 font-semibold text-white bg-[#00629B] rounded-md hover:bg-[#00497b]">Back to Dashboard</button>
          </div>
        )}
         <Modal isOpen={isFilterModalOpen} onClose={() => setIsFilterModalOpen(false)} onConfirm={() => { if(modalFilterData) setActiveFilter(modalFilterData); setResultsViewMode('table'); setIsFilterModalOpen(false); }} title="View Filtered Data">
            <p>Would you like to see the {modalFilterData?.data.length} items for "{modalFilterData?.title}" in the data table?</p>
         </Modal>
      </div>
    );
  };

  return (
    <div className="min-h-screen bg-white text-gray-800 font-sans flex flex-col">
      {/* Top Branding Bar with Integrated Title/Description */}
      <nav className="bg-[#00629B] text-white shadow-md z-50">
        <div className="container mx-auto px-6 py-6">
          <div className="flex justify-between items-start mb-10">
            <Logo />
            <div className="flex items-center gap-6">
              <div className="text-right hidden sm:flex flex-col items-end">
                <span className="text-xs font-bold opacity-70 uppercase tracking-widest">{currentUser.role}</span>
                <span className="text-sm font-medium">{currentUser.username}</span>
              </div>
              <div className="h-8 w-px bg-white/20 hidden sm:block"></div>
              <button 
                onClick={handleLogout} 
                className="text-xs font-bold bg-white/10 hover:bg-white/20 px-3 py-1.5 rounded transition-all flex items-center gap-2 border border-white/30"
              >
                <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" />
                </svg>
                Logout
              </button>
            </div>
          </div>

          <div className="text-center pb-4">
            <h1 className="text-4xl font-extrabold text-white tracking-tight leading-tight mb-3">
              Seafood Watch Sust-AI-nability Analyzer
            </h1>
            <p className="text-blue-100 text-sm md:text-base max-w-2xl mx-auto leading-relaxed opacity-90">
              Leverage AI to evaluate and visualize the eco-friendliness of your seafood products based on Seafood Watch recommendations.
            </p>
          </div>
        </div>
      </nav>

      {/* Tab Navigation Bar */}
      <div className="bg-white border-b border-gray-200 sticky top-0 z-40 shadow-sm">
        <div className="container mx-auto px-6">
          <div className="flex items-center space-x-8">
            <button 
              onClick={() => { setView('dashboard'); resetAnalyzerState(); }}
              className={`py-4 text-sm font-bold border-b-2 transition-all duration-200 flex items-center gap-2 ${view === 'dashboard' || (view === 'analyzer' && analyzerState === 'results') ? 'border-[#00629B] text-[#00629B]' : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'}`}
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2H6a2 2 0 01-2-2V6zM14 6a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2h-2a2 2 0 01-2-2V6zM4 16a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2H6a2 2 0 01-2-2v-2zM14 16a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2h-2a2 2 0 01-2-2v-2z" />
              </svg>
              Results Dashboard
            </button>

            <button 
              onClick={() => { setView('analyzer'); resetAnalyzerState(); }}
              className={`py-4 text-sm font-bold border-b-2 transition-all duration-200 flex items-center gap-2 ${view === 'analyzer' && analyzerState !== 'results' ? 'border-[#00629B] text-[#00629B]' : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'}`}
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 13h6m-3-3v6m5 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
              </svg>
              New Analysis
            </button>

            {currentUser.role === 'admin' && (
              <button 
                onClick={() => setView('users')}
                className={`py-4 text-sm font-bold border-b-2 transition-all duration-200 flex items-center gap-2 ${view === 'users' ? 'border-[#00629B] text-[#00629B]' : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'}`}
              >
                <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4.354a4 4 0 110 5.292M15 21H3v-1a6 6 0 0112 0v1zm0 0h6v-1a6 6 0 00-9-5.197M13 7a4 4 0 11-8 0 4 4 0 018 0z" />
                </svg>
                Manage Users
              </button>
            )}
          </div>
        </div>
      </div>

      <main className="container mx-auto p-4 sm:p-6 md:p-8 flex-grow bg-gray-50/30">
        {renderContent()}
      </main>

      <footer className="text-center py-6 text-gray-400 text-xs border-t bg-white">
        <p>&copy; {new Date().getFullYear()} Monterey Bay Aquarium Seafood Watch Program • Partner Portal</p>
        <p className="mt-1 opacity-60 italic">AI-Powered Sourcing Intelligence</p>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useCallback, useEffect, useRef } from 'react';
import { SeafoodInputItem, SeafoodResultItem, Rating, UploadSummary, User } from './types';
import { rateSeafoodData, analyzeSheetLayout, updateAnalysisForId } from './services/geminiService';
import { loadDatabaseFromUrl } from './services/referenceDatabase';
import { getUploadHistory, saveUploadToHistory } from './services/historyService';
import { performDataAudit, AuditReport } from './services/dataAuditService';
import { getCurrentUser, logout } from './services/authService';
import FileUpload from './components/FileUpload';
import ResultsTable from './components/ResultsTable';
import Loader from './components/Loader';
import Dashboard from './components/Dashboard';
import ColumnMapper from './components/ColumnMapper';
import DataPreview from './components/DataPreview';
import ChartsView from './components/ChartsView';
import Modal from './components/Modal';
import DataQualityAudit from './components/DataQualityAudit';
import Login from './components/Login';
import UserManagement from './components/UserManagement';

// This declaration is necessary because the library is loaded from a script tag in index.html
declare var XLSX: any;

type View = 'dashboard' | 'analyzer' | 'users';
type AnalyzerState = 'upload' | 'preview' | 'mapping' | 'audit' | 'loading' | 'results';
type ResultsViewMode = 'table' | 'charts';

const MAPPABLE_FIELDS = [
  'Wild or Farmed',
  'Common name',
  'Scientific name',
  'Source country',
  'Body of water',
  'Production Method',
  'Certification',
  'Supplier',
  'Product Name',
  'Volume',
];

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [view, setView] = useState<View>('dashboard');
  const [analyzerState, setAnalyzerState] = useState<AnalyzerState>('upload');
  const [results, setResults] = useState<SeafoodResultItem[] | null>(null);
  const [error, setError] = useState<string | null>(null);

  // State for raw data and headers
  const [originalData, setOriginalData] = useState<SeafoodInputItem[] | null>(null);
  const [originalHeaders, setOriginalHeaders] = useState<string[]>([]);
  const [currentFileName, setCurrentFileName] = useState<string>('');

  // State for column mapping and display-optimized results
  const [columnMapping, setColumnMapping] = useState<Record<string, string>>({});
  const [displayResults, setDisplayResults] = useState<any[] | null>(null);
  const [displayHeaders, setDisplayHeaders] = useState<string[]>([]);
  const [visibleColumns, setVisibleColumns] = useState<Set<string>>(new Set());
  const [auditReport, setAuditReport] = useState<AuditReport | null>(null);

  // State for preview step
  const [workbook, setWorkbook] = useState<any>(null); // XLSX workbook object
  const [sheetNames, setSheetNames] = useState<string[]>([]);
  const [selectedSheet, setSelectedSheet] = useState<string>('');
  const [headerRowIndex, setHeaderRowIndex] = useState<number>(1);
  const [previewData, setPreviewData] = useState<(string|number)[][]>([]);
  const [isPreviewLoading, setIsPreviewLoading] = useState<boolean>(false);
  const [previewWarning, setPreviewWarning] = useState<string | null>(null);

  const [uploadHistory, setUploadHistory] = useState<UploadSummary[]>([]);
  const [progress, setProgress] = useState<{ processed: number; total: number } | null>(null);

  // State for results view
  const [resultsViewMode, setResultsViewMode] = useState<ResultsViewMode>('table');
  const [activeFilter, setActiveFilter] = useState<{title: string; data: any[]} | null>(null);
  const [isFilterModalOpen, setIsFilterModalOpen] = useState(false);
  const [modalFilterData, setModalFilterData] = useState<{title: string; data: SeafoodResultItem[]} | null>(null);

  const analysisAbortController = useRef<AbortController | null>(null);

  useEffect(() => {
    const user = getCurrentUser();
    if (user) {
      setCurrentUser(user);
      // Admin: default to Dashboard. User: default to Analyzer (Upload view).
      setView(user.role === 'admin' ? 'dashboard' : 'analyzer');
    }

    setUploadHistory(getUploadHistory());
    loadDatabaseFromUrl('seafood-watch-data.csv');
  }, []);

  const handleLogin = (user: User) => {
    setCurrentUser(user);
    // Role based landing page
    setView(user.role === 'admin' ? 'dashboard' : 'analyzer');
  };

  const handleLogout = () => {
    logout();
    setCurrentUser(null);
    resetAnalyzerState();
  };

  const resetAnalyzerState = useCallback(() => {
    setResults(null);
    setDisplayResults(null);
    setDisplayHeaders([]);
    setError(null);
    setOriginalData(null);
    setOriginalHeaders([]);
    setCurrentFileName('');
    setProgress(null);
    setWorkbook(null);
    setSheetNames([]);
    setSelectedSheet('');
    setHeaderRowIndex(1);
    setPreviewData([]);
    setColumnMapping({});
    setAuditReport(null);
    setVisibleColumns(new Set());
    setResultsViewMode('table');
    setActiveFilter(null);
    setIsFilterModalOpen(false);
    setModalFilterData(null);
    setAnalyzerState('upload');
    setIsPreviewLoading(false);
    setPreviewWarning(null);
    analysisAbortController.current = null;
  }, []);

  const generatePreviewData = (worksheet: any) => {
    const previewJson: (string|number)[][] = XLSX.utils.sheet_to_json(worksheet, { header: 1, defval: '', raw: false, blankrows: false });
    setPreviewData(previewJson.slice(0, 15)); // Preview first 15 rows
  };

  const handleProcessFile = useCallback(async (file: File) => {
    resetAnalyzerState();
    setAnalyzerState('preview');
    setIsPreviewLoading(true);

    const reader = new FileReader();
    reader.onload = async (e) => {
      try {
        const data = e.target?.result;
        if (!data) throw new Error("File data could not be read.");

        let wb: any;
        try {
          wb = XLSX.read(data, { type: 'binary', cellNF: false, cellText: false });
        } catch (parseError) {
          console.error("File parsing error:", parseError);
          throw new Error("Could not parse file. Please ensure it is a valid XLSX or CSV file.");
        }

        const names = wb.SheetNames;
        if (names.length === 0) throw new Error("The file contains no sheets.");

        setWorkbook(wb);
        setSheetNames(names);
        setCurrentFileName(file.name);

        let bestSheetName = names[0];
        let bestHeaderRow = 1;

        try {
          const sheetPreviews = names.map(name => {
            const ws = wb.Sheets[name];
            const sheetData = XLSX.utils.sheet_to_json(ws, { header: 1, defval: '', raw: false, blankrows: false }).slice(0, 15);
            return { sheetName: name, data: sheetData };
          });
          const layout = await analyzeSheetLayout(sheetPreviews);
          bestSheetName = layout.bestSheetName;
          bestHeaderRow = layout.bestHeaderRow;
        } catch (aiError) {
          setPreviewWarning("AI auto-layout failed. Manual selection required.");
        }

        setSelectedSheet(bestSheetName);
        setHeaderRowIndex(bestHeaderRow);
        generatePreviewData(wb.Sheets[bestSheetName]);

      } catch (err: any) {
        setError(`Error processing file: ${err.message}`);
        setAnalyzerState('upload');
      } finally {
        setIsPreviewLoading(false);
      }
    };
    reader.readAsBinaryString(file);
  }, [resetAnalyzerState]);

  const handleSheetChange = (sheetName: string) => {
    if (workbook) {
      setSelectedSheet(sheetName);
      generatePreviewData(workbook.Sheets[sheetName]);
    }
  };

  const handleHeaderRowChange = (newRowIndex: number) => {
    setHeaderRowIndex(newRowIndex);
  };

  const handleConfirmPreview = useCallback(() => {
    setError(null);
    if (!workbook || !selectedSheet) return;

    try {
        const worksheet = workbook.Sheets[selectedSheet];
        const dataAsArray: any[][] = XLSX.utils.sheet_to_json(worksheet, { header: 1, defval: '', blankrows: false });

        if (dataAsArray.length < headerRowIndex) {
            throw new Error(`Header row ${headerRowIndex} not found.`);
        }

        const rawHeaders: string[] = dataAsArray[headerRowIndex - 1].map(header => String(header).trim());
        const headers: string[] = [];
        const counts: Record<string, number> = {};

        for (const header of rawHeaders) {
            if (!header) { headers.push(''); continue; }
            counts[header] = (counts[header] || 0) + 1;
            headers.push(counts[header] > 1 ? `${header} (${counts[header]})` : header);
        }

        const jsonData = dataAsArray.slice(headerRowIndex).map(row => {
            const rowObject: SeafoodInputItem = {};
            headers.forEach((header, index) => {
                if(header) rowObject[header] = row[index];
            });
            return rowObject;
        }).filter(obj => Object.keys(obj).length > 0);

        setOriginalData(jsonData);
        setOriginalHeaders(headers.filter(h => h));
        setAnalyzerState('mapping');

    } catch(err: any) {
        setError(`Error processing sheet: ${err.message}`);
    }
  }, [workbook, selectedSheet, headerRowIndex]);

  const handleConfirmMapping = useCallback((mapping: Record<string, string>) => {
    if (!originalData) return;
    setColumnMapping(mapping);
    const report = performDataAudit(originalData, mapping);
    setAuditReport(report);
    setAnalyzerState('audit');
  }, [originalData]);

  const handleStartAnalysis = useCallback(async () => {
    if (!originalData) return;
    setAnalyzerState('loading');
    setError(null);
    analysisAbortController.current = new AbortController();

    try {
        const commonNameHeader = columnMapping['Common name'];
        let dataToProcess = originalData;
        if (commonNameHeader && commonNameHeader !== 'N/A') {
            dataToProcess = originalData.filter(row => {
                const val = row[commonNameHeader];
                return val !== undefined && val !== null && String(val).trim() !== '';
            });
        }

        setProgress({ processed: 0, total: dataToProcess.length });

        const transformedData = dataToProcess.map(row => {
            const newRow: { [key: string]: string | number } = {};
            for (const mappableField of MAPPABLE_FIELDS) {
                const userColumnName = columnMapping[mappableField];
                if (userColumnName && userColumnName !== 'N/A' && row[userColumnName] !== undefined) {
                    newRow[mappableField] = row[userColumnName];
                }
            }
            return newRow;
        });

        const analysisResults = await rateSeafoodData(transformedData, (p, t) => setProgress({ processed: p, total: t }), analysisAbortController.current.signal);

        const finalResults: SeafoodResultItem[] = dataToProcess.map((originalItem, index) => {
            const analysisPart = analysisResults[index];
            return {
                ...originalItem,
                uniqueId: analysisPart.uniqueId,
                matchedKDEs: analysisPart.matchedKDEs, 
                rating: analysisPart.rating,
                reliabilityScore: analysisPart.reliabilityScore,
                notes: analysisPart.notes,
            };
        });

        setResults(finalResults);
        setDisplayResults(finalResults);
        setDisplayHeaders(originalHeaders);

        const mappedHeaders = Object.values(columnMapping).filter(h => h && h !== 'N/A') as string[];
        setVisibleColumns(new Set([...mappedHeaders, 'uniqueId', 'rating', 'reliabilityScore']));

        // Persistence logic
        const matchedCount = finalResults.filter(r => r.rating !== Rating.NA).length;
        const matchPercentage = finalResults.length > 0 ? (matchedCount / finalResults.length) * 100 : 0;
        const totalReliability = finalResults.reduce((acc, r) => acc + r.reliabilityScore, 0);
        const averageReliability = finalResults.length > 0 ? totalReliability / finalResults.length : 0;
        const ratingDistribution = finalResults.reduce<{[key in Rating]?: number}>((acc, item) => {
            acc[item.rating] = (acc[item.rating] || 0) + 1;
            return acc;
        }, {});

        const uploadSummaryData: Omit<UploadSummary, 'id' | 'uploadDate'> = {
            fileName: currentFileName, 
            rowCount: finalResults.length, 
            matchPercentage,
            averageReliability, 
            ratingDistribution, 
            commonIssues: [],
            fullResults: finalResults,
            columnMapping: columnMapping,
            originalHeaders: originalHeaders
        };

        setUploadHistory(saveUploadToHistory(uploadSummaryData));
        setAnalyzerState('results');
    } catch (err: any) {
        if (err.name === 'AbortError') return;
        setError(`Analysis error: ${err.message}`);
        setAnalyzerState('audit'); 
    }
  }, [originalData, currentFileName, originalHeaders, columnMapping]);

  const handleCancelAnalysis = useCallback(() => {
    if (analysisAbortController.current) analysisAbortController.current.abort();
    setAnalyzerState('audit');
    setError(null);
  }, []);

  const handleViewHistoricalResults = (summary: UploadSummary) => {
    if (summary.fullResults && summary.columnMapping && summary.originalHeaders) {
      setResults(summary.fullResults);
      setDisplayResults(summary.fullResults);
      setDisplayHeaders(summary.originalHeaders);
      setColumnMapping(summary.columnMapping);
      setCurrentFileName(summary.fileName);

      const mappedHeaders = Object.values(summary.columnMapping).filter(h => h && h !== 'N/A') as string[];
      setVisibleColumns(new Set([...mappedHeaders, 'uniqueId', 'rating', 'reliabilityScore']));

      setView('analyzer');
      setAnalyzerState('results');
      setResultsViewMode('table');
    } else {
      setError("Historical data not found.");
    }
  };

  const handleUpdateResult = useCallback(async (index: number, newUniqueId: string) => {
     if (!results || !results[index]) return;
     const updatedResults = [...results];
     updatedResults[index] = { ...updatedResults[index], isUpdating: true, uniqueId: newUniqueId };
     setResults(updatedResults);
     setDisplayResults(updatedResults);

     try {
         const originalItem = updatedResults[index];
         const updatedAnalysis = await updateAnalysisForId(originalItem, newUniqueId);
         const finalResults = [...results];
         finalResults[index] = { ...originalItem, ...updatedAnalysis, isUpdating: false };
         setResults(finalResults);
         setDisplayResults(finalResults);
     } catch (err) {
         setError("Failed to update record.");
     }
  }, [results]);

  const handleExport = useCallback(() => {
    if (!results || originalHeaders.length === 0) return;
    const headers = [...originalHeaders, 'Unique ID', 'Matched KDEs', 'Rating', 'Reliability Score', 'Notes'];
    const csvContent = [
        headers.join(','),
        ...results.map(row => {
            const originalValues = originalHeaders.map(h => `"${String(row[h] || '').replace(/"/g, '""')}"`);
            const analysisValues = [row.uniqueId, row.matchedKDEs, row.rating, row.reliabilityScore, row.notes]
              .map(v => `"${String(v || '').replace(/"/g, '""')}"`);
            return [...originalValues, ...analysisValues].join(',');
        })
    ].join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.setAttribute('download', `${currentFileName.replace(/\.[^/.]+$/, "")}_analyzed.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  }, [results, originalHeaders, currentFileName]);

  if (!currentUser) return <Login onLogin={handleLogin} />;

  const renderContent = () => {
    if (view === 'users' && currentUser.role === 'admin') return <UserManagement />;

    if (view === 'dashboard' || (view === 'analyzer' && analyzerState === 'results')) {
      // If we're in analyzer-results, the ResultsTable handles the back button to dash
      if (view === 'dashboard') {
        return (
            <div className="animate-fade-in-up">
                <Dashboard 
                  history={uploadHistory} 
                  onAnalyzeNew={() => { resetAnalyzerState(); setView('analyzer'); }} 
                  onViewResults={handleViewHistoricalResults}
                  userRole={currentUser.role}
                />
            </div>
        );
      }
    }

    return (
      <div className="animate-fade-in-up">
        {error && (
            <div className="bg-red-100 border border-red-400 text-red-700 px-4 py-3 rounded-lg relative my-6 max-w-4xl mx-auto">
              <strong>Error:</strong><span className="ml-2">{error}</span>
            </div>
        )}
        {analyzerState === 'upload' && <FileUpload onProcessFile={handleProcessFile} isLoading={false} />}
        {analyzerState === 'preview' && <DataPreview isAnalyzing={isPreviewLoading} sheetNames={sheetNames} selectedSheet={selectedSheet} onSheetChange={handleSheetChange} headerRowIndex={headerRowIndex} onHeaderRowChange={handleHeaderRowChange} previewData={previewData} onConfirm={handleConfirmPreview} onCancel={resetAnalyzerState} warning={previewWarning}/>}
        {analyzerState === 'mapping' && originalHeaders.length > 0 && <ColumnMapper fileHeaders={originalHeaders} mappableFields={MAPPABLE_FIELDS} onConfirm={handleConfirmMapping} onCancel={() => setAnalyzerState('preview')}/>}
        {analyzerState === 'audit' && auditReport && <DataQualityAudit report={auditReport} onConfirm={handleStartAnalysis} onBack={() => setAnalyzerState('mapping')} />}
        {analyzerState === 'loading' && <Loader progress={progress} onCancel={handleCancelAnalysis} />}
        {analyzerState === 'results' && results && displayResults && (
          <div className="flex flex-col items-center space-y-6">
            <div className="flex justify-center p-1 bg-gray-200 rounded-lg">
              <button onClick={() => setResultsViewMode('table')} className={`px-4 py-2 text-sm font-semibold rounded-md ${resultsViewMode === 'table' ? 'bg-white shadow text-gray-800' : 'text-gray-600'}`}>Table</button>
              <button onClick={() => setResultsViewMode('charts')} className={`px-4 py-2 text-sm font-semibold rounded-md ${resultsViewMode === 'charts' ? 'bg-white shadow text-gray-800' : 'text-gray-600'}`}>Charts</button>
            </div>
            <div className="w-full max-w-7xl">
              {resultsViewMode === 'table' ? (
                <ResultsTable 
                    results={activeFilter ? activeFilter.data : displayResults} 
                    originalHeaders={displayHeaders} 
                    columnMapping={columnMapping}
                    onExport={handleExport}
                    filterTitle={activeFilter?.title}
                    onClearFilter={() => setActiveFilter(null)}
                    visibleColumns={visibleColumns}
                    onVisibleColumnsChange={setVisibleColumns}
                    onUpdateResult={handleUpdateResult}
                />
              ) : (
                <ChartsView results={results} columnMapping={columnMapping} onSegmentClick={(t, d) => { setModalFilterData({title: t, data: d}); setIsFilterModalOpen(true); }} />
              )}
            </div>
            <button onClick={() => setView('dashboard')} className="px-6 py-2 font-semibold text-white bg-[#00629B] rounded-md hover:bg-[#00497b]">Back to Dashboard</button>
          </div>
        )}
         <Modal isOpen={isFilterModalOpen} onClose={() => setIsFilterModalOpen(false)} onConfirm={() => { if(modalFilterData) setActiveFilter(modalFilterData); setResultsViewMode('table'); setIsFilterModalOpen(false); }} title="View Filtered Data">
            <p>Would you like to see the {modalFilterData?.data.length} items for "{modalFilterData?.title}" in the data table?</p>
         </Modal>
      </div>
    );
  };

  return (
    <div className="min-h-screen bg-white text-gray-800 font-sans flex flex-col">
      {/* Top Branding Bar with Integrated Title/Description - COMPACT VERSION */}
      <nav className="bg-[#00629B] text-white shadow-md z-50">
        <div className="container mx-auto px-6 py-4">
          <div className="flex justify-between items-center mb-4">
            <div className="flex flex-col">
                <h1 className="text-2xl font-extrabold text-white tracking-tight leading-tight">
                  Seafood Watch Sust-AI-nability Analyzer
                </h1>
                <p className="text-blue-100 text-xs mt-1 opacity-90 hidden sm:block">
                  Evaluate eco-friendliness with AI-driven Seafood Watch intelligence.
                </p>
            </div>
            <div className="flex items-center gap-4">
              <div className="text-right hidden sm:flex flex-col items-end">
                <span className="text-[10px] font-bold opacity-70 uppercase tracking-widest leading-none">{currentUser.role}</span>
                <span className="text-sm font-medium">{currentUser.username}</span>
              </div>
              <div className="h-6 w-px bg-white/20 hidden sm:block"></div>
              <button 
                onClick={handleLogout} 
                className="text-xs font-bold bg-white/10 hover:bg-white/20 px-3 py-1 rounded transition-all flex items-center gap-2 border border-white/20"
              >
                Logout
              </button>
            </div>
          </div>
        </div>
      </nav>

      {/* Tab Navigation Bar */}
      <div className="bg-white border-b border-gray-200 sticky top-0 z-40 shadow-sm">
        <div className="container mx-auto px-6">
          <div className="flex items-center space-x-8">
            <button 
              onClick={() => { setView('dashboard'); resetAnalyzerState(); }}
              className={`py-4 text-sm font-bold border-b-2 transition-all duration-200 flex items-center gap-2 ${view === 'dashboard' || (view === 'analyzer' && analyzerState === 'results') ? 'border-[#00629B] text-[#00629B]' : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'}`}
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2H6a2 2 0 01-2-2V6zM14 6a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2h-2a2 2 0 01-2-2V6zM4 16a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2H6a2 2 0 01-2-2v-2zM14 16a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2h-2a2 2 0 01-2-2v-2z" />
              </svg>
              Results Dashboard
            </button>

            <button 
              onClick={() => { setView('analyzer'); resetAnalyzerState(); }}
              className={`py-4 text-sm font-bold border-b-2 transition-all duration-200 flex items-center gap-2 ${view === 'analyzer' && analyzerState !== 'results' ? 'border-[#00629B] text-[#00629B]' : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'}`}
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 13h6m-3-3v6m5 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
              </svg>
              New Analysis
            </button>

            {currentUser.role === 'admin' && (
              <button 
                onClick={() => setView('users')}
                className={`py-4 text-sm font-bold border-b-2 transition-all duration-200 flex items-center gap-2 ${view === 'users' ? 'border-[#00629B] text-[#00629B]' : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'}`}
              >
                <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4.354a4 4 0 110 5.292M15 21H3v-1a6 6 0 0112 0v1zm0 0h6v-1a6 6 0 00-9-5.197M13 7a4 4 0 11-8 0 4 4 0 018 0z" />
                </svg>
                Manage Users
              </button>
            )}
          </div>
        </div>
      </div>

      <main className="container mx-auto p-4 sm:p-6 md:p-8 flex-grow bg-gray-50/30">
        {renderContent()}
      </main>

      <footer className="text-center py-6 text-gray-400 text-xs border-t bg-white">
        <p>&copy; {new Date().getFullYear()} Monterey Bay Aquarium Seafood Watch Program • Partner Portal</p>
        <p className="mt-1 opacity-60 italic">AI-Powered Sourcing Intelligence</p>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useCallback, useEffect, useRef } from 'react';
import { SeafoodInputItem, SeafoodResultItem, Rating, UploadSummary, User } from './types';
import { rateSeafoodData, analyzeSheetLayout, updateAnalysisForId } from './services/geminiService';
import { loadDatabaseFromUrl } from './services/referenceDatabase';
import { getUploadHistory, saveUploadToHistory } from './services/historyService';
import { performDataAudit, AuditReport } from './services/dataAuditService';
import { getCurrentUser, logout } from './services/authService';
import FileUpload from './components/FileUpload';
import ResultsTable from './components/ResultsTable';
import Loader from './components/Loader';
import Dashboard from './components/Dashboard';
import ColumnMapper from './components/ColumnMapper';
import DataPreview from './components/DataPreview';
import ChartsView from './components/ChartsView';
import Modal from './components/Modal';
import DataQualityAudit from './components/DataQualityAudit';
import Login from './components/Login';
import UserManagement from './components/UserManagement';

// This declaration is necessary because the library is loaded from a script tag in index.html
declare var XLSX: any;

type View = 'dashboard' | 'analyzer' | 'users';
type AnalyzerState = 'upload' | 'preview' | 'mapping' | 'audit' | 'loading' | 'results';
type ResultsViewMode = 'table' | 'charts';

const MAPPABLE_FIELDS = [
  'Wild or Farmed',
  'Common name',
  'Scientific name',
  'Source country',
  'Body of water',
  'Production Method',
  'Certification',
  'Supplier',
  'Product Name',
  'Volume',
];

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [view, setView] = useState<View>('dashboard');
  const [analyzerState, setAnalyzerState] = useState<AnalyzerState>('upload');
  const [results, setResults] = useState<SeafoodResultItem[] | null>(null);
  const [error, setError] = useState<string | null>(null);

  // State for raw data and headers
  const [originalData, setOriginalData] = useState<SeafoodInputItem[] | null>(null);
  const [originalHeaders, setOriginalHeaders] = useState<string[]>([]);
  const [currentFileName, setCurrentFileName] = useState<string>('');

  // State for column mapping and display-optimized results
  const [columnMapping, setColumnMapping] = useState<Record<string, string>>({});
  const [displayResults, setDisplayResults] = useState<any[] | null>(null);
  const [displayHeaders, setDisplayHeaders] = useState<string[]>([]);
  const [visibleColumns, setVisibleColumns] = useState<Set<string>>(new Set());
  const [auditReport, setAuditReport] = useState<AuditReport | null>(null);

  // State for preview step
  const [workbook, setWorkbook] = useState<any>(null); // XLSX workbook object
  const [sheetNames, setSheetNames] = useState<string[]>([]);
  const [selectedSheet, setSelectedSheet] = useState<string>('');
  const [headerRowIndex, setHeaderRowIndex] = useState<number>(1);
  const [previewData, setPreviewData] = useState<(string|number)[][]>([]);
  const [isPreviewLoading, setIsPreviewLoading] = useState<boolean>(false);
  const [previewWarning, setPreviewWarning] = useState<string | null>(null);

  const [uploadHistory, setUploadHistory] = useState<UploadSummary[]>([]);
  const [progress, setProgress] = useState<{ processed: number; total: number } | null>(null);

  // State for results view
  const [resultsViewMode, setResultsViewMode] = useState<ResultsViewMode>('table');
  const [activeFilter, setActiveFilter] = useState<{title: string; data: any[]} | null>(null);
  const [isFilterModalOpen, setIsFilterModalOpen] = useState(false);
  const [modalFilterData, setModalFilterData] = useState<{title: string; data: SeafoodResultItem[]} | null>(null);

  const analysisAbortController = useRef<AbortController | null>(null);

  useEffect(() => {
    const user = getCurrentUser();
    if (user) {
      setCurrentUser(user);
      // Admin: default to Dashboard. User: default to Analyzer (Upload view).
      setView(user.role === 'admin' ? 'dashboard' : 'analyzer');
    }

    setUploadHistory(getUploadHistory());
    loadDatabaseFromUrl('seafood-watch-data.csv');
  }, []);

  const handleLogin = (user: User) => {
    setCurrentUser(user);
    // Role based landing page
    setView(user.role === 'admin' ? 'dashboard' : 'analyzer');
  };

  const handleLogout = () => {
    logout();
    setCurrentUser(null);
    resetAnalyzerState();
  };

  const resetAnalyzerState = useCallback(() => {
    setResults(null);
    setDisplayResults(null);
    setDisplayHeaders([]);
    setError(null);
    setOriginalData(null);
    setOriginalHeaders([]);
    setCurrentFileName('');
    setProgress(null);
    setWorkbook(null);
    setSheetNames([]);
    setSelectedSheet('');
    setHeaderRowIndex(1);
    setPreviewData([]);
    setColumnMapping({});
    setAuditReport(null);
    setVisibleColumns(new Set());
    setResultsViewMode('table');
    setActiveFilter(null);
    setIsFilterModalOpen(false);
    setModalFilterData(null);
    setAnalyzerState('upload');
    setIsPreviewLoading(false);
    setPreviewWarning(null);
    analysisAbortController.current = null;
  }, []);

  const generatePreviewData = (worksheet: any) => {
    const previewJson: (string|number)[][] = XLSX.utils.sheet_to_json(worksheet, { header: 1, defval: '', raw: false, blankrows: false });
    setPreviewData(previewJson.slice(0, 15)); // Preview first 15 rows
  };

  const handleProcessFile = useCallback(async (file: File) => {
    resetAnalyzerState();
    setAnalyzerState('preview');
    setIsPreviewLoading(true);

    const reader = new FileReader();
    reader.onload = async (e) => {
      try {
        const data = e.target?.result;
        if (!data) throw new Error("File data could not be read.");

        let wb: any;
        try {
          wb = XLSX.read(data, { type: 'binary', cellNF: false, cellText: false });
        } catch (parseError) {
          console.error("File parsing error:", parseError);
          throw new Error("Could not parse file. Please ensure it is a valid XLSX or CSV file.");
        }

        const names = wb.SheetNames;
        if (names.length === 0) throw new Error("The file contains no sheets.");

        setWorkbook(wb);
        setSheetNames(names);
        setCurrentFileName(file.name);

        let bestSheetName = names[0];
        let bestHeaderRow = 1;

        try {
          const sheetPreviews = names.map(name => {
            const ws = wb.Sheets[name];
            const sheetData = XLSX.utils.sheet_to_json(ws, { header: 1, defval: '', raw: false, blankrows: false }).slice(0, 15);
            return { sheetName: name, data: sheetData };
          });
          const layout = await analyzeSheetLayout(sheetPreviews);
          bestSheetName = layout.bestSheetName;
          bestHeaderRow = layout.bestHeaderRow;
        } catch (aiError) {
          setPreviewWarning("AI auto-layout failed. Manual selection required.");
        }

        setSelectedSheet(bestSheetName);
        setHeaderRowIndex(bestHeaderRow);
        generatePreviewData(wb.Sheets[bestSheetName]);

      } catch (err: any) {
        setError(`Error processing file: ${err.message}`);
        setAnalyzerState('upload');
      } finally {
        setIsPreviewLoading(false);
      }
    };
    reader.readAsBinaryString(file);
  }, [resetAnalyzerState]);

  const handleSheetChange = (sheetName: string) => {
    if (workbook) {
      setSelectedSheet(sheetName);
      generatePreviewData(workbook.Sheets[sheetName]);
    }
  };

  const handleHeaderRowChange = (newRowIndex: number) => {
    setHeaderRowIndex(newRowIndex);
  };

  const handleConfirmPreview = useCallback(() => {
    setError(null);
    if (!workbook || !selectedSheet) return;

    try {
        const worksheet = workbook.Sheets[selectedSheet];
        const dataAsArray: any[][] = XLSX.utils.sheet_to_json(worksheet, { header: 1, defval: '', blankrows: false });

        if (dataAsArray.length < headerRowIndex) {
            throw new Error(`Header row ${headerRowIndex} not found.`);
        }

        const rawHeaders: string[] = dataAsArray[headerRowIndex - 1].map(header => String(header).trim());
        const headers: string[] = [];
        const counts: Record<string, number> = {};

        for (const header of rawHeaders) {
            if (!header) { headers.push(''); continue; }
            counts[header] = (counts[header] || 0) + 1;
            headers.push(counts[header] > 1 ? `${header} (${counts[header]})` : header);
        }

        const jsonData = dataAsArray.slice(headerRowIndex).map(row => {
            const rowObject: SeafoodInputItem = {};
            headers.forEach((header, index) => {
                if(header) rowObject[header] = row[index];
            });
            return rowObject;
        }).filter(obj => Object.keys(obj).length > 0);

        setOriginalData(jsonData);
        setOriginalHeaders(headers.filter(h => h));
        setAnalyzerState('mapping');

    } catch(err: any) {
        setError(`Error processing sheet: ${err.message}`);
    }
  }, [workbook, selectedSheet, headerRowIndex]);

  const handleConfirmMapping = useCallback((mapping: Record<string, string>) => {
    if (!originalData) return;
    setColumnMapping(mapping);
    const report = performDataAudit(originalData, mapping);
    setAuditReport(report);
    setAnalyzerState('audit');
  }, [originalData]);

  const handleStartAnalysis = useCallback(async () => {
    if (!originalData) return;
    setAnalyzerState('loading');
    setError(null);
    analysisAbortController.current = new AbortController();

    try {
        const commonNameHeader = columnMapping['Common name'];
        let dataToProcess = originalData;
        if (commonNameHeader && commonNameHeader !== 'N/A') {
            dataToProcess = originalData.filter(row => {
                const val = row[commonNameHeader];
                return val !== undefined && val !== null && String(val).trim() !== '';
            });
        }

        setProgress({ processed: 0, total: dataToProcess.length });

        const transformedData = dataToProcess.map(row => {
            const newRow: { [key: string]: string | number } = {};
            for (const mappableField of MAPPABLE_FIELDS) {
                const userColumnName = columnMapping[mappableField];
                if (userColumnName && userColumnName !== 'N/A' && row[userColumnName] !== undefined) {
                    newRow[mappableField] = row[userColumnName];
                }
            }
            return newRow;
        });

        const analysisResults = await rateSeafoodData(transformedData, (p, t) => setProgress({ processed: p, total: t }), analysisAbortController.current.signal);

        const finalResults: SeafoodResultItem[] = dataToProcess.map((originalItem, index) => {
            const analysisPart = analysisResults[index];
            return {
                ...originalItem,
                uniqueId: analysisPart.uniqueId,
                matchedKDEs: analysisPart.matchedKDEs, 
                rating: analysisPart.rating,
                reliabilityScore: analysisPart.reliabilityScore,
                notes: analysisPart.notes,
            };
        });

        setResults(finalResults);
        setDisplayResults(finalResults);
        setDisplayHeaders(originalHeaders);

        const mappedHeaders = Object.values(columnMapping).filter(h => h && h !== 'N/A') as string[];
        setVisibleColumns(new Set([...mappedHeaders, 'uniqueId', 'rating', 'reliabilityScore']));

        // Persistence logic
        const matchedCount = finalResults.filter(r => r.rating !== Rating.NA).length;
        const matchPercentage = finalResults.length > 0 ? (matchedCount / finalResults.length) * 100 : 0;
        const totalReliability = finalResults.reduce((acc, r) => acc + r.reliabilityScore, 0);
        const averageReliability = finalResults.length > 0 ? totalReliability / finalResults.length : 0;
        const ratingDistribution = finalResults.reduce<{[key in Rating]?: number}>((acc, item) => {
            acc[item.rating] = (acc[item.rating] || 0) + 1;
            return acc;
        }, {});

        const uploadSummaryData: Omit<UploadSummary, 'id' | 'uploadDate'> = {
            fileName: currentFileName, 
            rowCount: finalResults.length, 
            matchPercentage,
            averageReliability, 
            ratingDistribution, 
            commonIssues: [],
            fullResults: finalResults,
            columnMapping: columnMapping,
            originalHeaders: originalHeaders
        };

        setUploadHistory(saveUploadToHistory(uploadSummaryData));
        setAnalyzerState('results');
    } catch (err: any) {
        if (err.name === 'AbortError') return;
        setError(`Analysis error: ${err.message}`);
        setAnalyzerState('audit'); 
    }
  }, [originalData, currentFileName, originalHeaders, columnMapping]);

  const handleCancelAnalysis = useCallback(() => {
    if (analysisAbortController.current) analysisAbortController.current.abort();
    setAnalyzerState('audit');
    setError(null);
  }, []);

  const handleViewHistoricalResults = (summary: UploadSummary) => {
    if (summary.fullResults && summary.columnMapping && summary.originalHeaders) {
      setResults(summary.fullResults);
      setDisplayResults(summary.fullResults);
      setDisplayHeaders(summary.originalHeaders);
      setColumnMapping(summary.columnMapping);
      setCurrentFileName(summary.fileName);

      const mappedHeaders = Object.values(summary.columnMapping).filter(h => h && h !== 'N/A') as string[];
      setVisibleColumns(new Set([...mappedHeaders, 'uniqueId', 'rating', 'reliabilityScore']));

      setView('analyzer');
      setAnalyzerState('results');
      setResultsViewMode('table');
    } else {
      setError("Historical data not found.");
    }
  };

  const handleUpdateResult = useCallback(async (index: number, newUniqueId: string) => {
     if (!results || !results[index]) return;
     const updatedResults = [...results];
     updatedResults[index] = { ...updatedResults[index], isUpdating: true, uniqueId: newUniqueId };
     setResults(updatedResults);
     setDisplayResults(updatedResults);

     try {
         const originalItem = updatedResults[index];
         const updatedAnalysis = await updateAnalysisForId(originalItem, newUniqueId);
         const finalResults = [...results];
         finalResults[index] = { ...originalItem, ...updatedAnalysis, isUpdating: false };
         setResults(finalResults);
         setDisplayResults(finalResults);
     } catch (err) {
         setError("Failed to update record.");
     }
  }, [results]);

  const handleExport = useCallback(() => {
    if (!results || originalHeaders.length === 0) return;
    const headers = [...originalHeaders, 'Unique ID', 'Matched KDEs', 'Rating', 'Reliability Score', 'Notes'];
    const csvContent = [
        headers.join(','),
        ...results.map(row => {
            const originalValues = originalHeaders.map(h => `"${String(row[h] || '').replace(/"/g, '""')}"`);
            const analysisValues = [row.uniqueId, row.matchedKDEs, row.rating, row.reliabilityScore, row.notes]
              .map(v => `"${String(v || '').replace(/"/g, '""')}"`);
            return [...originalValues, ...analysisValues].join(',');
        })
    ].join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.setAttribute('download', `${currentFileName.replace(/\.[^/.]+$/, "")}_analyzed.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  }, [results, originalHeaders, currentFileName]);

  if (!currentUser) return <Login onLogin={handleLogin} />;

  const renderContent = () => {
    if (view === 'users' && currentUser.role === 'admin') return <UserManagement />;

    if (view === 'dashboard' || (view === 'analyzer' && analyzerState === 'results')) {
      // If we're in analyzer-results, the ResultsTable handles the back button to dash
      if (view === 'dashboard') {
        return (
            <div className="animate-fade-in-up">
                <Dashboard 
                  history={uploadHistory} 
                  onAnalyzeNew={() => { resetAnalyzerState(); setView('analyzer'); }} 
                  onViewResults={handleViewHistoricalResults}
                  userRole={currentUser.role}
                />
            </div>
        );
      }
    }

    return (
      <div className="animate-fade-in-up">
        {error && (
            <div className="bg-red-100 border border-red-400 text-red-700 px-4 py-3 rounded-lg relative my-6 max-w-4xl mx-auto">
              <strong>Error:</strong><span className="ml-2">{error}</span>
            </div>
        )}
        {analyzerState === 'upload' && <FileUpload onProcessFile={handleProcessFile} isLoading={false} />}
        {analyzerState === 'preview' && <DataPreview isAnalyzing={isPreviewLoading} sheetNames={sheetNames} selectedSheet={selectedSheet} onSheetChange={handleSheetChange} headerRowIndex={headerRowIndex} onHeaderRowChange={handleHeaderRowChange} previewData={previewData} onConfirm={handleConfirmPreview} onCancel={resetAnalyzerState} warning={previewWarning}/>}
        {analyzerState === 'mapping' && originalHeaders.length > 0 && <ColumnMapper fileHeaders={originalHeaders} mappableFields={MAPPABLE_FIELDS} onConfirm={handleConfirmMapping} onCancel={() => setAnalyzerState('preview')}/>}
        {analyzerState === 'audit' && auditReport && <DataQualityAudit report={auditReport} onConfirm={handleStartAnalysis} onBack={() => setAnalyzerState('mapping')} />}
        {analyzerState === 'loading' && <Loader progress={progress} onCancel={handleCancelAnalysis} />}
        {analyzerState === 'results' && results && displayResults && (
          <div className="flex flex-col items-center space-y-6">
            <div className="flex justify-center p-1 bg-gray-200 rounded-lg">
              <button onClick={() => setResultsViewMode('table')} className={`px-4 py-2 text-sm font-semibold rounded-md ${resultsViewMode === 'table' ? 'bg-white shadow text-gray-800' : 'text-gray-600'}`}>Table</button>
              <button onClick={() => setResultsViewMode('charts')} className={`px-4 py-2 text-sm font-semibold rounded-md ${resultsViewMode === 'charts' ? 'bg-white shadow text-gray-800' : 'text-gray-600'}`}>Charts</button>
            </div>
            <div className="w-full max-w-7xl">
              {resultsViewMode === 'table' ? (
                <ResultsTable 
                    results={activeFilter ? activeFilter.data : displayResults} 
                    originalHeaders={displayHeaders} 
                    columnMapping={columnMapping}
                    onExport={handleExport}
                    filterTitle={activeFilter?.title}
                    onClearFilter={() => setActiveFilter(null)}
                    visibleColumns={visibleColumns}
                    onVisibleColumnsChange={setVisibleColumns}
                    onUpdateResult={handleUpdateResult}
                />
              ) : (
                <ChartsView results={results} columnMapping={columnMapping} onSegmentClick={(t, d) => { setModalFilterData({title: t, data: d}); setIsFilterModalOpen(true); }} />
              )}
            </div>
            <button onClick={() => setView('dashboard')} className="px-6 py-2 font-semibold text-white bg-[#00629B] rounded-md hover:bg-[#00497b]">Back to Dashboard</button>
          </div>
        )}
         <Modal isOpen={isFilterModalOpen} onClose={() => setIsFilterModalOpen(false)} onConfirm={() => { if(modalFilterData) setActiveFilter(modalFilterData); setResultsViewMode('table'); setIsFilterModalOpen(false); }} title="View Filtered Data">
            <p>Would you like to see the {modalFilterData?.data.length} items for "{modalFilterData?.title}" in the data table?</p>
         </Modal>
      </div>
    );
  };

  return (
    <div className="min-h-screen bg-white text-gray-800 font-sans flex flex-col">
      {/* Top Branding Bar with Integrated Title/Description - COMPACT VERSION */}
      <nav className="bg-[#00629B] text-white shadow-md z-50">
        <div className="container mx-auto px-6 py-4">
          <div className="flex justify-between items-center mb-4">
            <div className="flex flex-col">
                <h1 className="text-2xl font-extrabold text-white tracking-tight leading-tight">
                  Seafood Watch Sust-AI-nability Analyzer
                </h1>
                <p className="text-blue-100 text-xs mt-1 opacity-90 hidden sm:block">
                  Evaluate the eco-friendliness of seafood products with this AI-powered Seafood Watch tool.
                </p>
            </div>
            <div className="flex items-center gap-4">
              <div className="text-right hidden sm:flex flex-col items-end">
                <span className="text-[10px] font-bold opacity-70 uppercase tracking-widest leading-none">{currentUser.role}</span>
                <span className="text-sm font-medium">{currentUser.username}</span>
              </div>
              <div className="h-6 w-px bg-white/20 hidden sm:block"></div>
              <button 
                onClick={handleLogout} 
                className="text-xs font-bold bg-white/10 hover:bg-white/20 px-3 py-1 rounded transition-all flex items-center gap-2 border border-white/20"
              >
                Logout
              </button>
            </div>
          </div>
        </div>
      </nav>

      {/* Tab Navigation Bar */}
      <div className="bg-white border-b border-gray-200 sticky top-0 z-40 shadow-sm">
        <div className="container mx-auto px-6">
          <div className="flex items-center space-x-8">
            <button 
              onClick={() => { setView('dashboard'); resetAnalyzerState(); }}
              className={`py-4 text-sm font-bold border-b-2 transition-all duration-200 flex items-center gap-2 ${view === 'dashboard' || (view === 'analyzer' && analyzerState === 'results') ? 'border-[#00629B] text-[#00629B]' : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'}`}
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2H6a2 2 0 01-2-2V6zM14 6a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2h-2a2 2 0 01-2-2V6zM4 16a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2H6a2 2 0 01-2-2v-2zM14 16a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2h-2a2 2 0 01-2-2v-2z" />
              </svg>
              Results Dashboard
            </button>

            <button 
              onClick={() => { setView('analyzer'); resetAnalyzerState(); }}
              className={`py-4 text-sm font-bold border-b-2 transition-all duration-200 flex items-center gap-2 ${view === 'analyzer' && analyzerState !== 'results' ? 'border-[#00629B] text-[#00629B]' : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'}`}
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 13h6m-3-3v6m5 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
              </svg>
              New Analysis
            </button>

            {currentUser.role === 'admin' && (
              <button 
                onClick={() => setView('users')}
                className={`py-4 text-sm font-bold border-b-2 transition-all duration-200 flex items-center gap-2 ${view === 'users' ? 'border-[#00629B] text-[#00629B]' : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'}`}
              >
                <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4.354a4 4 0 110 5.292M15 21H3v-1a6 6 0 0112 0v1zm0 0h6v-1a6 6 0 00-9-5.197M13 7a4 4 0 11-8 0 4 4 0 018 0z" />
                </svg>
                Manage Users
              </button>
            )}
          </div>
        </div>
      </div>

      <main className="container mx-auto p-4 sm:p-6 md:p-8 flex-grow bg-gray-50/30">
        {renderContent()}
      </main>

      <footer className="text-center py-6 text-gray-400 text-xs border-t bg-white">
        <p>&copy; {new Date().getFullYear()} Monterey Bay Aquarium Seafood Watch Program • Partner Portal</p>
        <p className="mt-1 opacity-60 italic">AI-Powered Sourcing Intelligence</p>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useCallback, useEffect, useRef } from 'react';
import { SeafoodInputItem, SeafoodResultItem, Rating, UploadSummary, User } from './types';
import { rateSeafoodData, analyzeSheetLayout, updateAnalysisForId } from './services/geminiService';
import { loadDatabaseFromUrl } from './services/referenceDatabase';
import { getUploadHistory, saveUploadToHistory } from './services/historyService';
import { performDataAudit, AuditReport } from './services/dataAuditService';
import { getCurrentUser, logout } from './services/authService';
import FileUpload from './components/FileUpload';
import ResultsTable from './components/ResultsTable';
import Loader from './components/Loader';
import Dashboard from './components/Dashboard';
import ColumnMapper from './components/ColumnMapper';
import DataPreview from './components/DataPreview';
import ChartsView from './components/ChartsView';
import Modal from './components/Modal';
import DataQualityAudit from './components/DataQualityAudit';
import Login from './components/Login';
import UserManagement from './components/UserManagement';

// This declaration is necessary because the library is loaded from a script tag in index.html
declare var XLSX: any;

type View = 'dashboard' | 'analyzer' | 'users';
type AnalyzerState = 'upload' | 'preview' | 'mapping' | 'audit' | 'loading' | 'results';
type ResultsViewMode = 'table' | 'charts';

const MAPPABLE_FIELDS = [
  'Wild or Farmed',
  'Common name',
  'Scientific name',
  'Source country',
  'Body of water',
  'Production Method',
  'Certification',
  'Supplier',
  'Product Name',
  'Volume',
];

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [view, setView] = useState<View>('dashboard');
  const [analyzerState, setAnalyzerState] = useState<AnalyzerState>('upload');
  const [results, setResults] = useState<SeafoodResultItem[] | null>(null);
  const [error, setError] = useState<string | null>(null);

  // State for raw data and headers
  const [originalData, setOriginalData] = useState<SeafoodInputItem[] | null>(null);
  const [originalHeaders, setOriginalHeaders] = useState<string[]>([]);
  const [currentFileName, setCurrentFileName] = useState<string>('');

  // State for column mapping and display-optimized results
  const [columnMapping, setColumnMapping] = useState<Record<string, string>>({});
  const [displayResults, setDisplayResults] = useState<any[] | null>(null);
  const [displayHeaders, setDisplayHeaders] = useState<string[]>([]);
  const [visibleColumns, setVisibleColumns] = useState<Set<string>>(new Set());
  const [auditReport, setAuditReport] = useState<AuditReport | null>(null);

  // State for preview step
  const [workbook, setWorkbook] = useState<any>(null); // XLSX workbook object
  const [sheetNames, setSheetNames] = useState<string[]>([]);
  const [selectedSheet, setSelectedSheet] = useState<string>('');
  const [headerRowIndex, setHeaderRowIndex] = useState<number>(1);
  const [previewData, setPreviewData] = useState<(string|number)[][]>([]);
  const [isPreviewLoading, setIsPreviewLoading] = useState<boolean>(false);
  const [previewWarning, setPreviewWarning] = useState<string | null>(null);

  const [uploadHistory, setUploadHistory] = useState<UploadSummary[]>([]);
  const [progress, setProgress] = useState<{ processed: number; total: number } | null>(null);

  // State for results view
  const [resultsViewMode, setResultsViewMode] = useState<ResultsViewMode>('table');
  const [activeFilter, setActiveFilter] = useState<{title: string; data: any[]} | null>(null);
  const [isFilterModalOpen, setIsFilterModalOpen] = useState(false);
  const [modalFilterData, setModalFilterData] = useState<{title: string; data: SeafoodResultItem[]} | null>(null);

  const analysisAbortController = useRef<AbortController | null>(null);

  useEffect(() => {
    const user = getCurrentUser();
    if (user) {
      setCurrentUser(user);
      // Admin: default to Dashboard. User: default to Analyzer (Upload view).
      setView(user.role === 'admin' ? 'dashboard' : 'analyzer');
    }

    setUploadHistory(getUploadHistory());
    loadDatabaseFromUrl('seafood-watch-data.csv');
  }, []);

  const handleLogin = (user: User) => {
    setCurrentUser(user);
    // Role based landing page
    setView(user.role === 'admin' ? 'dashboard' : 'analyzer');
  };

  const handleLogout = () => {
    logout();
    setCurrentUser(null);
    resetAnalyzerState();
  };

  const resetAnalyzerState = useCallback(() => {
    setResults(null);
    setDisplayResults(null);
    setDisplayHeaders([]);
    setError(null);
    setOriginalData(null);
    setOriginalHeaders([]);
    setCurrentFileName('');
    setProgress(null);
    setWorkbook(null);
    setSheetNames([]);
    setSelectedSheet('');
    setHeaderRowIndex(1);
    setPreviewData([]);
    setColumnMapping({});
    setAuditReport(null);
    setVisibleColumns(new Set());
    setResultsViewMode('table');
    setActiveFilter(null);
    setIsFilterModalOpen(false);
    setModalFilterData(null);
    setAnalyzerState('upload');
    setIsPreviewLoading(false);
    setPreviewWarning(null);
    analysisAbortController.current = null;
  }, []);

  const generatePreviewData = (worksheet: any) => {
    const previewJson: (string|number)[][] = XLSX.utils.sheet_to_json(worksheet, { header: 1, defval: '', raw: false, blankrows: false });
    setPreviewData(previewJson.slice(0, 15)); // Preview first 15 rows
  };

  const handleProcessFile = useCallback(async (file: File) => {
    resetAnalyzerState();
    setAnalyzerState('preview');
    setIsPreviewLoading(true);

    const reader = new FileReader();
    reader.onload = async (e) => {
      try {
        const data = e.target?.result;
        if (!data) throw new Error("File data could not be read.");

        let wb: any;
        try {
          wb = XLSX.read(data, { type: 'binary', cellNF: false, cellText: false });
        } catch (parseError) {
          console.error("File parsing error:", parseError);
          throw new Error("Could not parse file. Please ensure it is a valid XLSX or CSV file.");
        }

        const names = wb.SheetNames;
        if (names.length === 0) throw new Error("The file contains no sheets.");

        setWorkbook(wb);
        setSheetNames(names);
        setCurrentFileName(file.name);

        let bestSheetName = names[0];
        let bestHeaderRow = 1;

        try {
          const sheetPreviews = names.map(name => {
            const ws = wb.Sheets[name];
            const sheetData = XLSX.utils.sheet_to_json(ws, { header: 1, defval: '', raw: false, blankrows: false }).slice(0, 15);
            return { sheetName: name, data: sheetData };
          });
          const layout = await analyzeSheetLayout(sheetPreviews);
          bestSheetName = layout.bestSheetName;
          bestHeaderRow = layout.bestHeaderRow;
        } catch (aiError) {
          setPreviewWarning("AI auto-layout failed. Manual selection required.");
        }

        setSelectedSheet(bestSheetName);
        setHeaderRowIndex(bestHeaderRow);
        generatePreviewData(wb.Sheets[bestSheetName]);

      } catch (err: any) {
        setError(`Error processing file: ${err.message}`);
        setAnalyzerState('upload');
      } finally {
        setIsPreviewLoading(false);
      }
    };
    reader.readAsBinaryString(file);
  }, [resetAnalyzerState]);

  const handleSheetChange = (sheetName: string) => {
    if (workbook) {
      setSelectedSheet(sheetName);
      generatePreviewData(workbook.Sheets[sheetName]);
    }
  };

  const handleHeaderRowChange = (newRowIndex: number) => {
    setHeaderRowIndex(newRowIndex);
  };

  const handleConfirmPreview = useCallback(() => {
    setError(null);
    if (!workbook || !selectedSheet) return;

    try {
        const worksheet = workbook.Sheets[selectedSheet];
        const dataAsArray: any[][] = XLSX.utils.sheet_to_json(worksheet, { header: 1, defval: '', blankrows: false });

        if (dataAsArray.length < headerRowIndex) {
            throw new Error(`Header row ${headerRowIndex} not found.`);
        }

        const rawHeaders: string[] = dataAsArray[headerRowIndex - 1].map(header => String(header).trim());
        const headers: string[] = [];
        const counts: Record<string, number> = {};

        for (const header of rawHeaders) {
            if (!header) { headers.push(''); continue; }
            counts[header] = (counts[header] || 0) + 1;
            headers.push(counts[header] > 1 ? `${header} (${counts[header]})` : header);
        }

        const jsonData = dataAsArray.slice(headerRowIndex).map(row => {
            const rowObject: SeafoodInputItem = {};
            headers.forEach((header, index) => {
                if(header) rowObject[header] = row[index];
            });
            return rowObject;
        }).filter(obj => Object.keys(obj).length > 0);

        setOriginalData(jsonData);
        setOriginalHeaders(headers.filter(h => h));
        setAnalyzerState('mapping');

    } catch(err: any) {
        setError(`Error processing sheet: ${err.message}`);
    }
  }, [workbook, selectedSheet, headerRowIndex]);

  const handleConfirmMapping = useCallback((mapping: Record<string, string>) => {
    if (!originalData) return;
    setColumnMapping(mapping);
    const report = performDataAudit(originalData, mapping);
    setAuditReport(report);
    setAnalyzerState('audit');
  }, [originalData]);

  const handleStartAnalysis = useCallback(async () => {
    if (!originalData) return;
    setAnalyzerState('loading');
    setError(null);
    analysisAbortController.current = new AbortController();

    try {
        const commonNameHeader = columnMapping['Common name'];
        let dataToProcess = originalData;
        if (commonNameHeader && commonNameHeader !== 'N/A') {
            dataToProcess = originalData.filter(row => {
                const val = row[commonNameHeader];
                return val !== undefined && val !== null && String(val).trim() !== '';
            });
        }

        setProgress({ processed: 0, total: dataToProcess.length });

        const transformedData = dataToProcess.map(row => {
            const newRow: { [key: string]: string | number } = {};
            for (const mappableField of MAPPABLE_FIELDS) {
                const userColumnName = columnMapping[mappableField];
                if (userColumnName && userColumnName !== 'N/A' && row[userColumnName] !== undefined) {
                    newRow[mappableField] = row[userColumnName];
                }
            }
            return newRow;
        });

        const analysisResults = await rateSeafoodData(transformedData, (p, t) => setProgress({ processed: p, total: t }), analysisAbortController.current.signal);

        const finalResults: SeafoodResultItem[] = dataToProcess.map((originalItem, index) => {
            const analysisPart = analysisResults[index];
            return {
                ...originalItem,
                uniqueId: analysisPart.uniqueId,
                matchedKDEs: analysisPart.matchedKDEs, 
                rating: analysisPart.rating,
                reliabilityScore: analysisPart.reliabilityScore,
                notes: analysisPart.notes,
            };
        });

        setResults(finalResults);
        setDisplayResults(finalResults);
        setDisplayHeaders(originalHeaders);

        const mappedHeaders = Object.values(columnMapping).filter(h => h && h !== 'N/A') as string[];
        setVisibleColumns(new Set([...mappedHeaders, 'uniqueId', 'rating', 'reliabilityScore']));

        // Persistence logic
        const matchedCount = finalResults.filter(r => r.rating !== Rating.NA).length;
        const matchPercentage = finalResults.length > 0 ? (matchedCount / finalResults.length) * 100 : 0;
        const totalReliability = finalResults.reduce((acc, r) => acc + r.reliabilityScore, 0);
        const averageReliability = finalResults.length > 0 ? totalReliability / finalResults.length : 0;
        const ratingDistribution = finalResults.reduce<{[key in Rating]?: number}>((acc, item) => {
            acc[item.rating] = (acc[item.rating] || 0) + 1;
            return acc;
        }, {});

        const uploadSummaryData: Omit<UploadSummary, 'id' | 'uploadDate'> = {
            fileName: currentFileName, 
            rowCount: finalResults.length, 
            matchPercentage,
            averageReliability, 
            ratingDistribution, 
            commonIssues: [],
            fullResults: finalResults,
            columnMapping: columnMapping,
            originalHeaders: originalHeaders
        };

        setUploadHistory(saveUploadToHistory(uploadSummaryData));
        setAnalyzerState('results');
    } catch (err: any) {
        if (err.name === 'AbortError') return;
        setError(`Analysis error: ${err.message}`);
        setAnalyzerState('audit'); 
    }
  }, [originalData, currentFileName, originalHeaders, columnMapping]);

  const handleCancelAnalysis = useCallback(() => {
    if (analysisAbortController.current) analysisAbortController.current.abort();
    setAnalyzerState('audit');
    setError(null);
  }, []);

  const handleViewHistoricalResults = (summary: UploadSummary) => {
    if (summary.fullResults && summary.columnMapping && summary.originalHeaders) {
      setResults(summary.fullResults);
      setDisplayResults(summary.fullResults);
      setDisplayHeaders(summary.originalHeaders);
      setColumnMapping(summary.columnMapping);
      setCurrentFileName(summary.fileName);

      const mappedHeaders = Object.values(summary.columnMapping).filter(h => h && h !== 'N/A') as string[];
      setVisibleColumns(new Set([...mappedHeaders, 'uniqueId', 'rating', 'reliabilityScore']));

      setView('analyzer');
      setAnalyzerState('results');
      setResultsViewMode('table');
    } else {
      setError("Historical data not found.");
    }
  };

  const handleUpdateResult = useCallback(async (index: number, newUniqueId: string) => {
     if (!results || !results[index]) return;
     const updatedResults = [...results];
     updatedResults[index] = { ...updatedResults[index], isUpdating: true, uniqueId: newUniqueId };
     setResults(updatedResults);
     setDisplayResults(updatedResults);

     try {
         const originalItem = updatedResults[index];
         const updatedAnalysis = await updateAnalysisForId(originalItem, newUniqueId);
         const finalResults = [...results];
         finalResults[index] = { ...originalItem, ...updatedAnalysis, isUpdating: false };
         setResults(finalResults);
         setDisplayResults(finalResults);
     } catch (err) {
         setError("Failed to update record.");
     }
  }, [results]);

  const handleExport = useCallback(() => {
    if (!results || originalHeaders.length === 0) return;
    const headers = [...originalHeaders, 'Unique ID', 'Matched KDEs', 'Rating', 'Reliability Score', 'Notes'];
    const csvContent = [
        headers.join(','),
        ...results.map(row => {
            const originalValues = originalHeaders.map(h => `"${String(row[h] || '').replace(/"/g, '""')}"`);
            const analysisValues = [row.uniqueId, row.matchedKDEs, row.rating, row.reliabilityScore, row.notes]
              .map(v => `"${String(v || '').replace(/"/g, '""')}"`);
            return [...originalValues, ...analysisValues].join(',');
        })
    ].join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.setAttribute('download', `${currentFileName.replace(/\.[^/.]+$/, "")}_analyzed.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  }, [results, originalHeaders, currentFileName]);

  if (!currentUser) return <Login onLogin={handleLogin} />;

  const renderContent = () => {
    if (view === 'users' && currentUser.role === 'admin') return <UserManagement />;

    if (view === 'dashboard' || (view === 'analyzer' && analyzerState === 'results')) {
      // If we're in analyzer-results, the ResultsTable handles the back button to dash
      if (view === 'dashboard') {
        return (
            <div className="animate-fade-in-up">
                <Dashboard 
                  history={uploadHistory} 
                  onAnalyzeNew={() => { resetAnalyzerState(); setView('analyzer'); }} 
                  onViewResults={handleViewHistoricalResults}
                  userRole={currentUser.role}
                />
            </div>
        );
      }
    }

    return (
      <div className="animate-fade-in-up">
        {error && (
            <div className="bg-red-100 border border-red-400 text-red-700 px-4 py-3 rounded-lg relative my-6 max-w-4xl mx-auto">
              <strong>Error:</strong><span className="ml-2">{error}</span>
            </div>
        )}
        {analyzerState === 'upload' && <FileUpload onProcessFile={handleProcessFile} isLoading={false} />}
        {analyzerState === 'preview' && <DataPreview isAnalyzing={isPreviewLoading} sheetNames={sheetNames} selectedSheet={selectedSheet} onSheetChange={handleSheetChange} headerRowIndex={headerRowIndex} onHeaderRowChange={handleHeaderRowChange} previewData={previewData} onConfirm={handleConfirmPreview} onCancel={resetAnalyzerState} warning={previewWarning}/>}
        {analyzerState === 'mapping' && originalHeaders.length > 0 && <ColumnMapper fileHeaders={originalHeaders} mappableFields={MAPPABLE_FIELDS} onConfirm={handleConfirmMapping} onCancel={() => setAnalyzerState('preview')}/>}
        {analyzerState === 'audit' && auditReport && <DataQualityAudit report={auditReport} onConfirm={handleStartAnalysis} onBack={() => setAnalyzerState('mapping')} />}
        {analyzerState === 'loading' && <Loader progress={progress} onCancel={handleCancelAnalysis} />}
        {analyzerState === 'results' && results && displayResults && (
          <div className="flex flex-col items-center space-y-6">
            <div className="flex justify-center p-1 bg-gray-200 rounded-lg">
              <button onClick={() => setResultsViewMode('table')} className={`px-4 py-2 text-sm font-semibold rounded-md ${resultsViewMode === 'table' ? 'bg-white shadow text-gray-800' : 'text-gray-600'}`}>Table</button>
              <button onClick={() => setResultsViewMode('charts')} className={`px-4 py-2 text-sm font-semibold rounded-md ${resultsViewMode === 'charts' ? 'bg-white shadow text-gray-800' : 'text-gray-600'}`}>Charts</button>
            </div>
            <div className="w-full max-w-7xl">
              {resultsViewMode === 'table' ? (
                <ResultsTable 
                    results={activeFilter ? activeFilter.data : displayResults} 
                    originalHeaders={displayHeaders} 
                    columnMapping={columnMapping}
                    onExport={handleExport}
                    filterTitle={activeFilter?.title}
                    onClearFilter={() => setActiveFilter(null)}
                    visibleColumns={visibleColumns}
                    onVisibleColumnsChange={setVisibleColumns}
                    onUpdateResult={handleUpdateResult}
                />
              ) : (
                <ChartsView results={results} columnMapping={columnMapping} onSegmentClick={(t, d) => { setModalFilterData({title: t, data: d}); setIsFilterModalOpen(true); }} />
              )}
            </div>
            <button onClick={() => setView('dashboard')} className="px-6 py-2 font-semibold text-white bg-[#00629B] rounded-md hover:bg-[#00497b]">Back to Dashboard</button>
          </div>
        )}
         <Modal isOpen={isFilterModalOpen} onClose={() => setIsFilterModalOpen(false)} onConfirm={() => { if(modalFilterData) setActiveFilter(modalFilterData); setResultsViewMode('table'); setIsFilterModalOpen(false); }} title="View Filtered Data">
            <p>Would you like to see the {modalFilterData?.data.length} items for "{modalFilterData?.title}" in the data table?</p>
         </Modal>
      </div>
    );
  };

  return (
    <div className="min-h-screen bg-white text-gray-800 font-sans flex flex-col">
      {/* Top Branding Bar with Integrated Title/Description - COMPACT VERSION */}
      <nav className="bg-[#00629B] text-white shadow-md z-50">
        <div className="container mx-auto px-6 py-4">
          <div className="flex justify-between items-center mb-4">
            <div className="flex flex-col">
                <h1 className="text-2xl font-extrabold text-white tracking-tight leading-tight">
                  Seafood Watch Sust-AI-nability Analyzer
                </h1>
                <p className="text-blue-100 text-xs mt-1 opacity-90 hidden sm:block">
                  Evaluate the eco-friendliness of seafood products with this AI-powered Seafood Watch tool.
                </p>
            </div>
            <div className="flex items-center gap-4">
              <div className="text-right hidden sm:flex flex-col items-end">
                <span className="text-[10px] font-bold opacity-70 uppercase tracking-widest leading-none">{currentUser.role}</span>
                <span className="text-sm font-medium">{currentUser.username}</span>
              </div>
              <div className="h-6 w-px bg-white/20 hidden sm:block"></div>
              <button 
                onClick={handleLogout} 
                className="text-xs font-bold bg-white/10 hover:bg-white/20 px-3 py-1 rounded transition-all flex items-center gap-2 border border-white/20"
              >
                Logout
              </button>
            </div>
          </div>
        </div>
      </nav>

      {/* Tab Navigation Bar */}
      <div className="bg-white border-b border-gray-200 sticky top-0 z-40 shadow-sm">
        <div className="container mx-auto px-6">
          <div className="flex items-center space-x-8">
            <button 
              onClick={() => { setView('dashboard'); resetAnalyzerState(); }}
              className={`py-4 text-sm font-bold border-b-2 transition-all duration-200 flex items-center gap-2 ${view === 'dashboard' || (view === 'analyzer' && analyzerState === 'results') ? 'border-[#00629B] text-[#00629B]' : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'}`}
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2H6a2 2 0 01-2-2V6zM14 6a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2h-2a2 2 0 01-2-2V6zM4 16a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2H6a2 2 0 01-2-2v-2zM14 16a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2h-2a2 2 0 01-2-2v-2z" />
