import { GoogleGenAI, Type } from "@google/genai";
import { SeafoodInputItem, SeafoodResultItem, Rating } from "../types";
import { getSeafoodById, findCandidates, Candidate } from "./referenceDatabase";

declare var process: {
  env: {
    API_KEY: string;
  };
};

const singleItemSchema = {
  type: Type.OBJECT,
  properties: {
    uniqueId: {
      type: Type.STRING,
      description: "The official ID from provided candidates. Use 'N/A' if no good match.",
    },
    rating: {
      type: Type.STRING,
      enum: Object.values(Rating),
      description: "The suggested rating. If the item is Certified (MSC, ASC, etc.), this MUST be 'Certified'.",
    },
    reliabilityScore: {
      type: Type.NUMBER,
      description: "Confidence (0-100).",
    },
    notes: {
      type: Type.STRING,
      description: "Detailed reasoning for why this candidate was chosen, referencing specific attributes that matched.",
    },
  },
  required: ["uniqueId", "rating", "reliabilityScore", "notes"],
};

const responseSchema = {
    type: Type.ARRAY,
    items: singleItemSchema
};

const analysisSystemInstruction = `You are a strict data matching engine for Seafood Watch. Your task is to receive a list of seafood products and their corresponding official database candidates, then pick the best Candidate ID for each. 

Rules: 
1. Only use IDs from the provided 'candidates' list or 'N/A'. 
2. Match Species name, Country/Location, and Production Method as closely as possible. 
3. If the input specifies a Certification like MSC, ASC, or BAP, set the UniqueID to 'N/A' and the rating to 'Certified'.
4. For 'notes', provide a clear rationale why this candidate was chosen, referencing specific attributes that matched or why it was flagged as Certified.
5. Return a JSON array of results in the exact same order as the input items.`;

type AnalysisResult = Pick<SeafoodResultItem, 'uniqueId' | 'matchedKDEs' | 'rating' | 'reliabilityScore' | 'notes'>;

// PERFORMANCE CONFIGURATION
const BATCH_SIZE = 20;
const MAX_CONCURRENT_BATCHES = 2; 
const API_DELAY_MS = 1500; 

interface MinifiedInput {
    id: number;
    spec: string;
    cntry: string;
    mthd: string;
    fw: string;
    cert: string;
}

interface BatchItemWithCandidates {
    index: number;
    data: MinifiedInput;
    candidates: { id: string; desc: string; rating: string }[];
}

function isRateLimitError(error: any): boolean {
    const errString = JSON.stringify(error).toUpperCase();
    return errString.includes('429') || errString.includes('RESOURCE_EXHAUSTED') || errString.includes('RATE_LIMIT');
}

function getRowSignature(item: SeafoodInputItem): string {
    return `${item['Common name']}|${item['Source country']}|${item['Production Method']}|${item['Wild or Farmed']}|${item['Certification']}`.toLowerCase();
}

async function rateBatch(items: { input: SeafoodInputItem; index: number }[]): Promise<AnalysisResult[]> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    let retries = 5;
    let delay = 5000;

    const failedResult: AnalysisResult = {
        uniqueId: "N/A",
        matchedKDEs: "Analysis Failed",
        rating: Rating.NA,
        reliabilityScore: 0,
        notes: "An error occurred during analysis.",
    };

    const batchWithCandidates: BatchItemWithCandidates[] = items.map((item) => {
        const candidates = findCandidates({
            species: String(item.input['Common name'] || ''),
            country: String(item.input['Source country'] || ''),
            method: String(item.input['Production Method'] || ''),
            farmedWild: String(item.input['Wild or Farmed'] || '')
        }, 5);

        return {
            index: item.index,
            data: {
                id: item.index,
                spec: String(item.input['Common name'] || ''),
                cntry: String(item.input['Source country'] || ''),
                mthd: String(item.input['Production Method'] || ''),
                fw: String(item.input['Wild or Farmed'] || ''),
                cert: String(item.input['Certification'] || '')
            },
            candidates: candidates.map(c => ({
                id: c.record.UniqueID,
                desc: c.description,
                rating: c.record.RatingColor
            }))
        };
    });

    while (retries > 0) {
        try {
            const prompt = `Match products to candidate IDs:\n${JSON.stringify(batchWithCandidates)}`;

            const response = await ai.models.generateContent({
                model: 'gemini-3-flash-preview',
                contents: prompt,
                config: {
                    systemInstruction: analysisSystemInstruction,
                    responseMimeType: "application/json",
                    responseSchema: responseSchema,
                    temperature: 0.0,
                },
            });

            const results: any[] = JSON.parse(response.text.trim());

            return results.map(result => {
                const uniqueId = result.uniqueId || "N/A";
                let matchedKDEs = "N/A";
                let rating = (result.rating as Rating) || Rating.NA;

                if (uniqueId !== "N/A") {
                    const officialRecord = getSeafoodById(uniqueId);
                    if (officialRecord) {
                        matchedKDEs = officialRecord.matchedKDEs;
                        rating = officialRecord.rating;
                    }
                }

                return {
                    uniqueId,
                    matchedKDEs, 
                    rating,
                    reliabilityScore: result.reliabilityScore || 0,
                    notes: result.notes || "Analyzed by AI.",
                };
            });

        } catch (error: any) {
            if (isRateLimitError(error) && --retries > 0) {
                await new Promise(resolve => setTimeout(resolve, delay + Math.random() * 2000));
                delay *= 1.5;
                continue;
            }
            return items.map(() => failedResult);
        }
    }
    return items.map(() => failedResult);
}

export async function rateSeafoodData(
  data: SeafoodInputItem[],
  onProgress: (processed: number, total: number) => void,
  signal?: AbortSignal
): Promise<AnalysisResult[]> {
  const total = data.length;

  // 1. Group unique items
  const uniqueItems: SeafoodInputItem[] = [];
  const signatureToIndices = new Map<string, number[]>();

  data.forEach((item, index) => {
      const sig = getRowSignature(item);
      if (!signatureToIndices.has(sig)) {
          signatureToIndices.set(sig, []);
          uniqueItems.push(item);
      }
      signatureToIndices.get(sig)!.push(index);
  });

  const uniqueTotal = uniqueItems.length;
  const uniqueResults: AnalysisResult[] = new Array(uniqueTotal);
  let totalRowsFullyProcessed = 0;

  const updateProgressSmoothly = (newTotalProcessed: number) => {
    while (totalRowsFullyProcessed < newTotalProcessed) {
      totalRowsFullyProcessed++;
      onProgress(totalRowsFullyProcessed, total);
    }
  };

  // 2. Short-Circuit Phase
  const itemsRequiringAI: { input: SeafoodInputItem; index: number }[] = [];

  uniqueItems.forEach((item, uIdx) => {
      // If manually marked as certified in the spreadsheet, we still want AI to verify it.
      // But if it's a perfect match in our DB, we take it.
      const candidates = findCandidates({
          species: String(item['Common name'] || ''),
          country: String(item['Source country'] || ''),
          method: String(item['Production Method'] || ''),
          farmedWild: String(item['Wild or Farmed'] || '')
      }, 1);

      if (candidates.length > 0 && candidates[0].score >= 160) {
          const top = candidates[0];
          uniqueResults[uIdx] = {
              uniqueId: top.record.UniqueID,
              matchedKDEs: top.description,
              rating: getSeafoodById(top.record.UniqueID)?.rating || Rating.NA,
              reliabilityScore: 100,
              notes: "Exact match found on all relevant sourcing attributes.",
          };

          const affectedRows = signatureToIndices.get(getRowSignature(item))?.length || 0;
          updateProgressSmoothly(totalRowsFullyProcessed + affectedRows);
      } else {
          itemsRequiringAI.push({ input: item, index: uIdx });
      }
  });

  // 3. AI Analysis Phase
  for (let i = 0; i < itemsRequiringAI.length; i += (BATCH_SIZE * MAX_CONCURRENT_BATCHES)) {
    if (signal?.aborted) throw new DOMException('Aborted', 'AbortError');

    const batchPromises = [];
    for (let j = 0; j < MAX_CONCURRENT_BATCHES; j++) {
        const start = i + (j * BATCH_SIZE);
        if (start >= itemsRequiringAI.length) break;

        const batch = itemsRequiringAI.slice(start, start + BATCH_SIZE);

        const p = rateBatch(batch).then(results => {
            let newlyProcessedCount = 0;
            results.forEach((res, idx) => {
                const globalBatchIdx = start + idx;
                const originalUniqueIdx = itemsRequiringAI[globalBatchIdx].index;
                uniqueResults[originalUniqueIdx] = res;

                const sig = getRowSignature(uniqueItems[originalUniqueIdx]);
                newlyProcessedCount += signatureToIndices.get(sig)?.length || 0;
            });
            updateProgressSmoothly(totalRowsFullyProcessed + newlyProcessedCount);
            return results;
        });

        batchPromises.push(p);
    }

    await Promise.all(batchPromises);

    if (i + (BATCH_SIZE * MAX_CONCURRENT_BATCHES) < itemsRequiringAI.length) {
      await new Promise(resolve => setTimeout(resolve, API_DELAY_MS));
    }
  }

  // 4. Map back
  const finalResults: AnalysisResult[] = new Array(total);
  uniqueItems.forEach((item, uniqueIdx) => {
      const sig = getRowSignature(item);
      const res = uniqueResults[uniqueIdx];
      signatureToIndices.get(sig)?.forEach(originalIdx => {
          finalResults[originalIdx] = res;
      });
  });

  onProgress(total, total);
  return finalResults;
}

export async function updateAnalysisForId(
  item: SeafoodInputItem,
  newId: string
): Promise<AnalysisResult> {
    const officialRecord = getSeafoodById(newId);
    if (officialRecord) {
        return {
            uniqueId: newId,
            matchedKDEs: officialRecord.matchedKDEs,
            rating: officialRecord.rating,
            reliabilityScore: 100, 
            notes: "Manually verified by user.",
        };
    }
    return {
        uniqueId: newId,
        matchedKDEs: "Unknown ID",
        rating: Rating.NA,
        reliabilityScore: 0,
        notes: "Invalid ID provided.",
    };
}

export async function getColumnMapping(
  mappableFields: string[],
  fileHeaders: string[]
): Promise<{ mapping: Record<string, string>; isFallback: boolean }> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const properties: Record<string, object> = {};
  mappableFields.forEach(field => {
    properties[field] = {
      type: Type.STRING,
      enum: [...fileHeaders, 'N/A'],
      description: `Best column for '${field}'.`
    };
  });

  const schema = {
    type: Type.OBJECT,
    properties: properties,
    required: mappableFields,
  };

  const systemInstruction = `You are an expert data mapping specialist. Map required seafood sourcing fields to file headers. Synonyms: 'Origin' = 'Source Country', 'Gear' = 'Production Method', 'Species' = 'Common Name'. Use 'N/A' if no match exists.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Map: ${JSON.stringify(mappableFields)} to ${JSON.stringify(fileHeaders)}`,
      config: { 
          systemInstruction,
          responseMimeType: "application/json", 
          responseSchema: schema, 
          temperature: 0 
      },
    });
    return { mapping: JSON.parse(response.text.trim()), isFallback: false };
  } catch {
    return { mapping: performStaticMapping(mappableFields, fileHeaders), isFallback: true };
  }
}

export async function analyzeSheetLayout(
  sheetPreviews: { sheetName: string; data: (string | number)[][] }[]
): Promise<{ bestSheetName: string; bestHeaderRow: number }> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const schema = {
    type: Type.OBJECT,
    properties: { 
        bestSheetName: { type: Type.STRING }, 
        bestHeaderRow: { type: Type.NUMBER } 
    },
    required: ["bestSheetName", "bestHeaderRow"],
  };

  const systemInstruction = `Expert spreadsheet analyst. Identify the main seafood sourcing sheet and the 1-based index of the header row.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Analyze layout: ${JSON.stringify(sheetPreviews)}`,
      config: { 
          systemInstruction,
          responseMimeType: "application/json", 
          responseSchema: schema, 
          temperature: 0 
      },
    });
    return JSON.parse(response.text.trim());
  } catch (err) {
    return { bestSheetName: sheetPreviews[0]?.sheetName || '', bestHeaderRow: 1 };
  }
}

function performStaticMapping(mappableFields: string[], fileHeaders: string[]): Record<string, string> {
  const mapping: Record<string, string> = {};
  const lowerHeaders = fileHeaders.map(h => h.toLowerCase());

  mappableFields.forEach(field => {
    const fLow = field.toLowerCase();
    const idx = lowerHeaders.findIndex(h => h.includes(fLow) || fLow.includes(h));
    mapping[field] = idx !== -1 ? fileHeaders[idx] : 'N/A';
  });
  return mapping;
}

import React, { useState } from 'react';
import { Rating, SeafoodResultItem } from '../types';

// Updated rating colors as requested
const ratingColors: { [key in Rating]: string } = {
  [Rating.BestChoice]: '#23872B',
  [Rating.GoodAlternative]: '#BA8C17',
  [Rating.Avoid]: '#AA323C',
  [Rating.Certified]: '#00629B',
  [Rating.NA]: '#9ca3af',
};

const ratingLabels: { [key in Rating]: string } = {
  [Rating.BestChoice]: 'Green',
  [Rating.GoodAlternative]: 'Yellow',
  [Rating.Avoid]: 'Red',
  [Rating.Certified]: 'Certified',
  [Rating.NA]: 'N/A',
};

const ratingOrder: Rating[] = [Rating.BestChoice, Rating.GoodAlternative, Rating.Avoid, Rating.Certified, Rating.NA];

export interface BarChartDataItem {
  label: string;
  totalValue: number;
  breakdown: { [key in Rating]?: number };
  sourceItems: SeafoodResultItem[];
}

interface StackedBarChartProps {
  title: string;
  data: BarChartDataItem[];
  metric: 'volume' | 'count';
  chartType: 'species' | 'country' | 'supplier';
  columnMapping: Record<string, string>;
  onSegmentClick: (title: string, data: SeafoodResultItem[]) => void;
}

const StackedBarChart: React.FC<StackedBarChartProps> = ({ title, data, metric, chartType, columnMapping, onSegmentClick }) => {
  const [tooltip, setTooltip] = useState<{ content: React.ReactNode; x: number; y: number } | null>(null);

  const rowHeight = 25;
  const chartHeight = data.length * rowHeight;
  const chartWidth = 600;
  const yAxisWidth = 150;
  const plotWidth = chartWidth - yAxisWidth;
  const maxValue = Math.max(...data.map(d => d.totalValue));

  const handleMouseOver = (e: React.MouseEvent, content: React.ReactNode) => {
    const chartRect = (e.currentTarget as SVGElement).closest('svg')?.getBoundingClientRect();
    if (chartRect) {
      setTooltip({ content, x: e.clientX - chartRect.left, y: e.clientY - chartRect.top });
    }
  };

  const getKDEInfo = (item: SeafoodResultItem) => {
    if (item.uniqueId !== 'N/A') {
      // Use matched KDEs from DB
      const kdeParts = item.matchedKDEs.split(' | ');
      const speciesPart = kdeParts[0] || 'N/A';
      // Strip rating like (Wild) from species name if present for cleaner tooltip
      const species = speciesPart.replace(/\s*\([^)]+\)/, '');
      const country = kdeParts[1] || 'N/A';
      const method = kdeParts[2] || 'N/A';

      if (chartType === 'species') return { country, method };
      if (chartType === 'country') return { species, method };
      return { species, country, method };
    } else {
      // Use original product dataset for non-matches
      const speciesHeader = columnMapping['Common name'];
      const countryHeader = columnMapping['Source country'];
      const methodHeader = columnMapping['Production Method'];

      const species = (speciesHeader && speciesHeader !== 'N/A') ? String(item[speciesHeader] || 'N/A') : 'N/A';
      const country = (countryHeader && countryHeader !== 'N/A') ? String(item[countryHeader] || 'N/A') : 'N/A';
      const method = (methodHeader && methodHeader !== 'N/A') ? String(item[methodHeader] || 'N/A') : 'N/A';

      if (chartType === 'species') return { country, method };
      if (chartType === 'country') return { species, method };
      return { species, country, method };
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent, title: string, items: SeafoodResultItem[]) => {
    if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      onSegmentClick(title, items);
    }
  };

  return (
    <div className="bg-white p-6 rounded-lg shadow-lg border border-gray-200 w-full">
      <h2 className="text-xl font-bold text-gray-800 mb-4">{title}</h2>
      {data.length === 0 ? (
        <p className="text-gray-500 text-center py-8">Not enough data to display this chart.</p>
      ) : (
        <div className="relative">
          <svg width="100%" viewBox={`0 0 ${chartWidth} ${chartHeight + 30}`} role="img" aria-label={title}>
            {data.map((item, index) => {
              let currentX = yAxisWidth;
              const y = index * rowHeight;
              return (
                <g key={item.label} className="group">
                  <text x={yAxisWidth - 10} y={y + (rowHeight / 2) + 4} textAnchor="end" alignmentBaseline="middle" className="text-[11px] fill-current text-gray-600 truncate">
                     {item.label.length > 25 ? `${item.label.substring(0, 23)}...` : item.label}
                  </text>
                  {ratingOrder.map(rating => {
                    const value = item.breakdown[rating] || 0;
                    if (value === 0) return null;
                    const width = (value / maxValue) * plotWidth;
                    const percentage = (value / item.totalValue) * 100;

                    const segmentItems = item.sourceItems.filter(source => source.rating === rating);
                    const label = ratingLabels[rating];
                    const segmentTitle = `${item.label} (${label})`;

                    const uniqueKDEs = Array.from(new Set<string>(segmentItems.map(si => {
                        const info = getKDEInfo(si);
                        return JSON.stringify(info);
                    }))).map((s: string) => JSON.parse(s)).slice(0, 3);

                    const tooltipContent = (
                      <div className="flex flex-col gap-2 min-w-[180px]">
                        <div className="border-b border-gray-100 pb-2 mb-1">
                          <div 
                            className="text-[10px] font-bold uppercase tracking-wider leading-none mb-1"
                            style={{ color: ratingColors[rating] }}
                          >
                            {label}
                          </div>
                          <div className="text-xs font-bold text-gray-800">
                            {value.toLocaleString()} {metric === 'volume' ? 'Units' : 'Products'} ({percentage.toFixed(1)}%)
                          </div>
                        </div>

                        <div className="space-y-2">
                          {uniqueKDEs.map((kde, idx) => (
                            <div key={idx} className="text-[10px] leading-snug">
                              {chartType === 'species' && (
                                <div className="flex flex-col">
                                  <span className="font-semibold text-gray-700">{kde.country}</span>
                                  <span className="text-gray-500">{kde.method}</span>
                                </div>
                              )}
                              {chartType === 'country' && (
                                <div className="flex flex-col">
                                  <span className="font-semibold text-gray-700">{kde.species}</span>
                                  <span className="text-gray-500">{kde.method}</span>
                                </div>
                              )}
                              {chartType === 'supplier' && (
                                <div className="flex flex-col">
                                  <span className="font-semibold text-gray-700">{kde.species}</span>
                                  <span className="text-gray-500">{kde.country} • {kde.method}</span>
                                </div>
                              )}
                            </div>
                          ))}
                        </div>

                        {segmentItems.length > 3 && (
                          <div className="text-[9px] text-gray-400 italic pt-1 border-t border-gray-50">
                            + {segmentItems.length - 3} additional sourcing variants
                          </div>
                        )}
                      </div>
                    );

                    const rectEl = (
                        <rect
                            key={`${rating}-rect`}
                            x={currentX}
                            y={y + 5}
                            width={width}
                            height={15}
                            fill={ratingColors[rating]}
                            className="cursor-pointer transition-opacity duration-200 group-hover:opacity-100 opacity-90 hover:!opacity-100 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2"
                            onClick={() => onSegmentClick(segmentTitle, segmentItems)}
                            onMouseMove={(e) => handleMouseOver(e, tooltipContent)}
                            onMouseOut={() => setTooltip(null)}
                            onKeyDown={(e) => handleKeyDown(e, segmentTitle, segmentItems)}
                            role="button"
                            tabIndex={0}
                            aria-label={`${segmentTitle}: ${value.toLocaleString()} (${percentage.toFixed(1)}%)`}
                        />
                    );

                    const textEl = width > 25 ? (
                        <text
                            key={`${rating}-text`}
                            x={currentX + width / 2}
                            y={y + 5 + 15 / 2}
                            textAnchor="middle"
                            alignmentBaseline="middle"
                            fill="white"
                            className="text-[11px] font-bold pointer-events-none"
                            style={{ textShadow: '0px 0px 2px rgba(0,0,0,0.5)' }}
                        >
                            {Math.round(percentage)}%
                        </text>
                    ) : null;

                    const group = (
                        <g key={rating}>
                            {rectEl}
                            {textEl}
                        </g>
                    );

                    currentX += width;
                    return group;
                  })}
                </g>
              );
            })}
            <line x1={yAxisWidth} x2={chartWidth} y1={chartHeight} y2={chartHeight} stroke="#d1d5db" />
            <text x={yAxisWidth} y={chartHeight + 20} textAnchor="start" className="text-[11px] fill-current text-gray-500">0</text>
            <text x={chartWidth} y={chartHeight + 20} textAnchor="end" className="text-[11px] fill-current text-gray-500">{maxValue.toLocaleString()}</text>
             <text x={yAxisWidth + plotWidth / 2} y={chartHeight + 20} textAnchor="middle" className="text-[11px] font-semibold fill-current text-gray-600">
               Total {metric === 'volume' ? 'Volume' : 'Products'}
             </text>
          </svg>
          {tooltip && (
            <div
              className="absolute bg-white text-gray-800 p-3 rounded-lg shadow-xl z-50 pointer-events-none border border-gray-100 max-w-xs transition-transform duration-75"
              style={{ 
                left: tooltip.x + 15, 
                top: tooltip.y + 15, 
                transform: 'translateZ(0)',
                filter: 'drop-shadow(0 4px 6px -1px rgb(0 0 0 / 0.1))'
              }}
            >
              {tooltip.content}
            </div>
          )}
        </div>
      )}
    </div>
  );
};

